(1694, 1, 'Make conditionals (Verbs/Conditional)', NULL, 49, '', '<h3>Napite v&nbsp;kondicionálu!</h3>  <table cellSpacing=\"0\" cellPadding=\"2\" border=\"0\" width=\"100%\">    <tbody>      <tr height=\"27\">        <td vAlign=\"bottom\" bgcolor=\"#000000\">&nbsp;</td>        <td vAlign=\"bottom\" bgcolor=\"#CCCCCC\"><b>On</b></td>        <td vAlign=\"bottom\" bgcolor=\"#000000\">&nbsp;</td>        <td vAlign=\"bottom\" bgcolor=\"#CCCCCC\"><b>Ona</b></td>      </tr>      <tr height=\"27\">        <td vAlign=\"bottom\">          <p><i>jste</i></p>        </td>        <td vAlign=\"bottom\">          <p> [$1, text 10:byli]   [$1, text 6:byste] </p>        </td>        <td vAlign=\"bottom\">          <p><i>chce&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</i></p>        </td>        <td vAlign=\"bottom\"> [$1, text 10:chtěla]   [$1, text 6:bys] </td>      </tr>      <tr height=\"27\">        <td vAlign=\"top\">          <p><i>jsi</i></p>        </td>        <td vAlign=\"top\">          <p> [$1, text 10:byl]   [$1, text 6:bys] </p>        </td>        <td vAlign=\"top\">          <p><i>chcete</i></p>        </td>        <td vAlign=\"top\"> [$1, text 10:chtěly]   [$1, text 6:byste] </td>      </tr>      <tr height=\"27\">        <td vAlign=\"top\">          <p><i>je</i></p>        </td>        <td vAlign=\"top\">          <p> [$1, text 10:byl]   [$1, text 6:by] </p>        </td>        <td vAlign=\"top\">          <p><i>musíme</i></p>        </td>        <td vAlign=\"top\"> [$1, text 10:musely]   [$1, text 6:bychom] </td>      </tr>      <tr height=\"27\">        <td vAlign=\"top\">          <p><i>jsou</i></p>        </td>        <td vAlign=\"top\">          <p> [$1, text 10:byli]   [$1, text 6:by] </p>        </td>        <td vAlign=\"top\">          <p><i>musím</i></p>        </td>        <td vAlign=\"top\"> [$1, text 10:musela]   [$1, text 6:bych] </td>      </tr>      <tr height=\"27\">        <td vAlign=\"top\">          <p><i>jsme</i></p>        </td>        <td vAlign=\"top\">          <p> [$1, text 10:byli]   [$1, text 6:bychom] </p>        </td>        <td vAlign=\"top\">          <p><i>musí (oni)</i></p>        </td>        <td vAlign=\"top\"> [$1, text 10:musely]   [$1, text 6:by] </td>      </tr>      <tr height=\"27\">        <td vAlign=\"top\">          <p><i>je</i></p>        </td>        <td vAlign=\"top\">          <p> [$1, text 10:byl]   [$1, text 6:by] </p>        </td>        <td vAlign=\"top\">          <p><i>jde</i></p>        </td>        <td vAlign=\"top\"> [$1, text 10:la]   [$1, text 6:by] </td>      </tr>      <tr height=\"27\">        <td vAlign=\"top\">          <p><i>chci</i></p>        </td>        <td vAlign=\"top\">          <p> [$1, text 10:chtěl]   [$1, text 6:bych] </p>        </td>        <td vAlign=\"top\">          <p><i>jdu</i></p>        </td>        <td vAlign=\"top\"> [$1, text 10:la]   [$1, text 6:bych] </td>      </tr>      <tr height=\"27\">        <td vAlign=\"top\">          <p><i>chceme</i></p>        </td>        <td vAlign=\"top\">          <p> [$1, text 10:chtěli]   [$1, text 6:bychom] </p>        </td>        <td vAlign=\"top\">          <p><i>jdou</i></p>        </td>        <td vAlign=\"top\"> [$1, text 10:ly]   [$1, text 6:by] </td>      </tr>      <tr height=\"27\">        <td vAlign=\"top\">          <p><i>přečtu si</i></p>        </td>        <td vAlign=\"top\">          <p> [$1, text 10:přečetl]   [$1, text 6:bych]  si</p>        </td>        <td vAlign=\"top\">          <p><i>vidí (ona)</i></p>        </td>        <td vAlign=\"top\"> [$1, text 10:viděla]   [$1, text 6:by] </td>      </tr>      <tr height=\"27\">        <td vAlign=\"top\">          <p><i>připravíme</i></p>        </td>        <td vAlign=\"top\"> [$1, text 10:připravili]   [$1, text 6:bychom] </td>        <td vAlign=\"top\">          <p><i>jedeme</i></p>        </td>        <td vAlign=\"top\"> [$1, text 10:jely]   [$1, text 6:bychom] </td>      </tr>      <tr height=\"27\">        <td vAlign=\"top\">          <p><i>nerozumí (on)</i></p>        </td>        <td vAlign=\"top\"> [$1, text 10:nerozuměl]   [$1, text 6:by] </td>        <td vAlign=\"top\">          <p><i>nelíbí se mu</i></p>        </td>        <td vAlign=\"top\"> [$1, text 10:nelíbila]   [$1, text 6:by]  se</td>      </tr>      <tr height=\"27\">        <td vAlign=\"top\">          <p><i>můe</i></p>        </td>        <td vAlign=\"top\"> [$1, text 10:mohl]   [$1, text 6:bys] </td>        <td vAlign=\"top\">          <p><i>zůstanu</i></p>        </td>        <td vAlign=\"top\"> [$1, text 10:zůstala]   [$1, text 6:bych] </td>      </tr>      <tr height=\"27\">        <td vAlign=\"top\">          <p><i>objedná si (ona)</i></p>        </td>        <td vAlign=\"top\"> [$1, text 10:objednal]   [$1, text 6:by]  sis</td>        <td vAlign=\"top\">          <p><i>vím</i></p>        </td>        <td vAlign=\"top\"> [$1, text 10:věděla]   [$1, text 6:bych] </td>      </tr>      <tr height=\"27\">        <td vAlign=\"top\">          <p><i>dám si</i></p>        </td>        <td vAlign=\"top\"> [$1, text 10:dal]   [$1, text 6:bych]  sis</td>        <td vAlign=\"top\">          <p><i>jede</i></p>        </td>        <td vAlign=\"top\"> [$1, text 10:jela]   [$1, text 6:by] </td>      </tr>      <tr height=\"27\">        <td vAlign=\"top\">          <p><i>spím</i></p>        </td>        <td vAlign=\"top\"> [$1, text 10:spal]   [$1, text 6:bych] </td>        <td vAlign=\"top\">          <p><i>udělám</i></p>        </td>        <td vAlign=\"top\"> [$1, text 10:udělala]   [$1, text 6:bych] </td>      </tr>      <tr height=\"27\">        <td vAlign=\"top\">          <p><i>podívám se</i></p>        </td>        <td vAlign=\"top\"> [$1, text 10:podíval]   [$1, text 6:bych]  se</td>        <td vAlign=\"top\">          <p><i>navtíví (ona)</i></p>        </td>        <td vAlign=\"top\"> [$1, text 10:navtívila]   [$1, text 6:by] </td>      </tr>      <tr height=\"27\">        <td vAlign=\"top\">          <p><i>jím</i></p>        </td>        <td vAlign=\"top\"> [$1, text 10:jedl]   [$1, text 6:bych] </td>        <td vAlign=\"top\">          <p><i>vystoupíte</i></p>        </td>        <td vAlign=\"top\"> [$1, text 10:vystoupilt]   [$1, text 6:byste] </td>      </tr>      <tr height=\"27\">        <td vAlign=\"top\">          <p><i>rozumějí</i></p>        </td>        <td vAlign=\"top\"> [$1, text 10:rozuměli]   [$1, text 6:by] </td>        <td vAlign=\"top\">          <p><i>řeknu vám to</i></p>        </td>        <td vAlign=\"top\"> [$1, text 10:řekla]   [$1, text 6:bych]  vám to</td>      </tr>    </tbody>  </table>    ', 3, ''),
(1695, 1, 'Make polite sentences (Verbs/Conditional)', NULL, 49, '', '<h3>Řěkněte v&nbsp;kondicionálu!</h3>  <p><i>Co řeknete řidiči taxi, kdy chcete jet do Hostivaře?<br>  </i> [$1, textarea 60,2] </p>  <p><i>Co řeknete kolegyni, kdy chcete půjčit pero?<br>  </i> [$1, textarea 60,2] </p>  <p><i>Co řeknete, kdy nevíte kde je vá hotel?<br>  </i> [$1, textarea 60,2] </p>  <p><i>Co řeknete, kdy se chcete omluvit, e jdete pozdě?<br>  </i> [$1, textarea 60,2] </p>  <p><i>Co řeknete, kdy chcete otevřít okno?<br>  </i> [$1, textarea 60,2] </p>  <p><i>Co řeknete, kdy chcete v&nbsp; restauraci&nbsp; dvě kávy?<br>  </i> [$1, textarea 60,2] </p>     ', 3, ''),
(1696, 1, 'Translate English conditionals into Czech (Verbs/Conditional)', NULL, 49, '', '<h3>Přelote!</h3>  <table cellSpacing=\"0\" cellPadding=\"0\" border=\"0\">    <tbody>      <tr height=\"36\">        <td>          <p><i>How would you answer this question?</i></p>        </td>        <td>          <p> [$1, textarea 30,2] </p>        </td>      </tr>      <tr height=\"36\">        <td>          <p><i>Would you like to live by the sea?</i></p>        </td>        <td>          <p> [$1, textarea 30,2] </p>        </td>      </tr>      <tr height=\"36\">        <td>          <p><i>What would you say to him if he will called you this evening?</i></p>        </td>        <td>          <p> [$1, textarea 30,2] </p>        </td>      </tr>      <tr height=\"36\">        <td>          <p><i>Would you like to see their new flat?</i></p>        </td>        <td>          <p> [$1, textarea 30,2] </p>        </td>      </tr>      <tr height=\"36\">        <td>          <p><i>I´d be happy if they came today.</i></p>        </td>        <td>          <p> [$1, textarea 30,2] </p>        </td>      </tr>      <tr height=\"36\">        <td>          <p><i>If I had a pen I would writen it.</i></p>        </td>        <td>          <p> [$1, textarea 30,2] </p>        </td>      </tr>      <tr height=\"36\">        <td>          <p><i>I would be able to come.</i></p>        </td>        <td>          <p> [$1, textarea 30,2] </p>        </td>      </tr>      <tr height=\"36\">        <td>          <p><i>If we had their address we would visit them immediately.</i></p>        </td>        <td>          <p> [$1, textarea 30,2] </p>        </td>      </tr>    </tbody>  </table>    ', 3, ''),
(1697, 1, 'Answer Jak se jmenuje (Verbs/Conjugation)', NULL, 49, '', '<h3>Odpovězte!</h3>  <table cellSpacing=\"0\" cellPadding=\"0\" border=\"0\">    <tbody>      <tr>        <td vAlign=\"top\" width=\"187\">          <p><i>Jak se jmenuje?</i></p>        </td>        <td vAlign=\"top\" width=\"321\">          <p align=\"left\"> [$1, text 10]  Hana.</p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"187\">          <p><i>Jak se jmenujete?</i></p>        </td>        <td vAlign=\"top\" width=\"321\">          <p align=\"left\"> [$1, text 10]  Novák.</p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"187\">          <p><i>Jak se jmenujou?</i></p>        </td>        <td vAlign=\"top\" width=\"321\">          <p align=\"left\"> [$1, text 10]  Braunovi.</p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"187\">          <p><i>Jak se jmenuje?</i></p>        </td>        <td vAlign=\"top\" width=\"321\">          <p align=\"left\"> [$1, text 10]  Michal.</p>        </td>      </tr>    </tbody>  </table>    ', 3, ''),
(1698, 1, 'Conjugate číst (Verbs/Conjugation)', NULL, 49, '', '<h3>Doplňte&nbsp; sloveso <i>číst!</i></h3>  <p>Rád  [$1, text 5:čtu]  o architektuře. <b>(já)</b> Co  [$1, text 5:čte] , Jano? Američané  &nbsp; [$1, text 5:čtou]  The Prague Post. Kadé ráno  [$1, text 5:čteme]  noviny. <b>(my)</b>  Jana  [$1, text 5:čte]  knihu o Americe. Pane řediteli, co to  [$1, text 5:čtete] ? Zuzana a Karel  &nbsp; [$1, text 5:čtou]  dopis z Ameriky. Kadý den  [$1, text 5:čtu]  noviny. <b>(já)</b></p>  ', 3, ''),
(1699, 1, 'Conjugate dělat (Verbs/Conjugation)', NULL, 49, '', '<h3>Doplňte sloveso <i>dělat</i>!</h3>  <table border=\"0\" width=\"100%\">    <tr>      <td valign=\"top\"><b><img src=\"/tuit/img/exercises/delaveceri.gif\" width=\"64\" height=\"59\"><br>        Dělá večeři.</b></td>      <td valign=\"top\"> [$1, text 6:Dělám] &nbsp;<b>(já)</b> domácí úkol. &nbsp;Co  [$1, text 6:dělá]        Jana? &nbsp;Petra  [$1, text 6:dělá]  večeři.  [$1, text 6:děláme]  <b>(my) </b>cvičení.        &nbsp;Co &nbsp; [$1, text 6:děláte]  <b>(vy) </b>dnes odpoledne? &nbsp;Novákovi        &nbsp; [$1, text 6:dělají]  dnes večer párty.</td>      <td valign=\"top\"><b><img src=\"/tuit/img/exercises/delaukol.gif\" width=\"93\" height=\"68\"><br>        Dělá úkol.</b></td>    </tr>  </table>  <p align=\"left\">&nbsp;</p>', 3, ''),
(1700, 1, 'Conjugate to be 1 (Verbs/Conjugation)', NULL, 49, '', '<h3>Doplňte!</h3>  <p align=\"left\">On  [$1, text 4:je]  . My  [$1, text 4:jsme] . Ona  [$1, text 4:je] . Já  [$1, text 4:jsem] . &nbsp; Ono   [$1, text 4:je] . Ty  [$1, text 4:jsi] .&nbsp;Oni  [$1, text 4:jsou] . Vy  [$1, text 4:jste] . Já  [$1, text 4:jsem]  Petr. &nbsp;To   [$1, text 4:je]  Jana. <br>   [$1, text 4:jste]  Michal Horák? Ano,  [$1, text 4:jsem] . &nbsp;<br>   [$1, text 4:jste]  Hanákovi? &nbsp;Ne,  [$1, text 6:nejsme] ?</p>    ', 3, ''),
(1701, 1, 'Conjugate to be 2 (Verbs/Conjugation)', NULL, 49, '', '<h3>Doplňte!</h3>  <p align=\"left\">On  [$1, text 4:je]  . My  [$1, text 4:jsme] . Ona  [$1, text 4:je] . Já  [$1, text 4:jsem] . Ono  [$1, text 4:je] .  Ty  [$1, text 4:jsi] . Oni  [$1, text 4:jsou] . Vy  [$1, text 4:jste] . &nbsp; [$1, text 4:My]  jsme.  [$1, text 4:Oni]  jsou.  [$1, text 4]  je.   [$1, text 4:Já]  jsem.  [$1, text 4]  je.  [$1, text 4:Vy]  jste.  [$1, text 4:Ty]  jsi. &nbsp;On  [$1, text 4:je]  Američan. Vy   [$1, text 4:jste]  Čech. Já  [$1, text 4:jsem]  Čeka. My  [$1, text 4:jsme]  Čei. &nbsp;Ty  [$1, text 4:jsi]  Američanka.  Ona  [$1, text 4:je]  Čeka. Oni  [$1, text 4:jsou]  Američané.</p>    ', 3, ''),
(1702, 1, 'Conjugate to have 1 (Verbs/Conjugation)', NULL, 49, '', '<h3>Kdo co má?</h3>  <p>My  [$1, text 4:máme]  chleba. Honza  [$1, text 4:má]  čerstvý rohlík. Petr a Petra  [$1, text 4:mají]  banány. Jana  [$1, text 4:má]  okurku. Vy  [$1, text 4:máte]  mléko. Já  [$1, text 4:mám]  sýr. Radek  [$1, text 4:má]  pivo. Marie a Dana  [$1, text 4:mají]  kávu. Já  [$1, text 4:mám]  čaj.</p>    ', 3, ''),
(1703, 1, 'Conjugate to have 2 (Verbs/Conjugation)', NULL, 49, '', '<h3>Doplňte sloveso : <i>mít !</i></h3>  <p>Jana    [$1, text 4:má]    rohlík.  Co to    [$1, text 4:má]  ? <b>(ty)</b> Petr    [$1, text 4:má]  banán.    [$1, text 4:máte]   pivo?  <b>(vy)</b>  árka a David    [$1, text 4:mají]   víno.    [$1, text 4:Mám]   čaj.  <b> (já)</b></p>   ', 3, ''),
(1704, 1, 'Conjugate jet (Verbs/Conjugation)', NULL, 49, '', '<h3>Doplňte sloveso <i>jet</i>!</h3>  <p>V 7 hodin <b>(já)</b>  [$1, text 5:jedu]  do koly.</p>  <p><b>(ty)</b>  [$1, text 5:jede]  do Prahy?</p>  <p>Kdo  [$1, text 5:jede]  do USA?</p>  <p>Kdy <b>(vy)</b> &nbsp; [$1, text 6:jedete]  domů?</p>   ', 3, ''),
(1705, 1, 'Conjugate jít (Verbs/Conjugation)', NULL, 49, '', '<h3>Doplňte sloveso <i>jít</i>!</h3>  <ol>    <li>V 8 hodin musím &nbsp; [$1, text 4:jít]  do koly.</li>    <li>Dane, &nbsp; [$1, text 4:jde]  do restaurace ?</li>    <li>V kolik hodin  [$1, text 4:jde]  Radek do kina ?</li>    <li>Zítra <b>(my) </b>ne [$1, text 5:jdeme]  do koly.</li>    <li>V úterý &nbsp; [$1, text 4:jde]  Pavel do divadla.</li>    <li>My  [$1, text 5:jdeme]  domů, ale do hospody.</li>    <li>Hana, Anna a Michal &nbsp; [$1, text 4:jdou]  na večeři.</li>  </ol>   ', 3, ''),
(1706, 1, 'Conjugate and choose jít and přijít (Verbs/Conjugation)', NULL, 49, '', '<h3>Doplňte slovesa! <i>Jít</i> nebo <i>přijít</i>?</h3>  <p>Zítra  [$1, text 8:jdu]  do koly v 8 hodin. <b><i>(já) </i></b>&nbsp;Domů  [$1, text 8:přijdu]  v 6 hodin.<b><i>(já)</i></b> Hana  [$1, text 8:jde]  dneska do kina. &nbsp;Táta  [$1, text 8:přijde]  z práce pozdě. Včera  [$1, text 8:el]  na návtěvu k Petrovi.<b><i>(on)</i></b>  &nbsp;Bolelo mě v krku a tak  [$1, text 8:jsem el)]  k doktorovi. Rodiče k nám  [$1, text 8:přili]  v sobotu.</p>', 3, ''),
(1707, 1, 'Conjugate misc verbs (Verbs/Conjugation)', NULL, 49, '', '<h3>Doplňte!</h3>  <table cellSpacing=\"0\" cellPadding=\"0\" border=\"0\">    <tbody>      <tr>        <td vAlign=\"top\" width=\"149\">          <p align=\"right\"><i>čtu - ty</i></p>        </td>        <td vAlign=\"top\" width=\"151\">          <p>&nbsp; [$1, text 8:čte] </p>        </td>        <td vAlign=\"top\" width=\"104\">          <p align=\"right\"><i>píe - oni</i></p>        </td>        <td vAlign=\"top\" width=\"180\">          <p>&nbsp; [$1, text 8:píou] </p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"149\">          <p align=\"right\"><i>studujeme - oni</i></p>        </td>        <td vAlign=\"top\" width=\"151\">          <p>&nbsp; [$1, text 8:studují] </p>        </td>        <td vAlign=\"top\" width=\"104\">          <p align=\"right\"><i>bydlíme - já</i></p>        </td>        <td vAlign=\"top\" width=\"180\">          <p>&nbsp; [$1, text 8:bydlím] </p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"149\">          <p align=\"right\"><i>děkuje - ona</i></p>        </td>        <td vAlign=\"top\" width=\"151\">          <p>&nbsp; [$1, text 8:děkuje] </p>        </td>        <td vAlign=\"top\" width=\"104\">          <p align=\"right\"><i>spí - já</i></p>        </td>        <td vAlign=\"top\" width=\"180\">          <p>&nbsp; [$1, text 8:spím] </p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"149\">          <p align=\"right\"><i>jíte - ona</i></p>        </td>        <td vAlign=\"top\" width=\"151\">          <p>&nbsp;jí</p>        </td>        <td vAlign=\"top\" width=\"104\">          <p align=\"right\"><i>piju - vy</i></p>        </td>        <td vAlign=\"top\" width=\"180\">          <p>&nbsp; [$1, text 8:pijete] </p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"149\">          <p align=\"right\"><i>opakuje - on</i></p>        </td>        <td vAlign=\"top\" width=\"151\">    