=160 height=56 alt=>                            <div align=right>     </td>    <td align=center valign=top width=32% height=105>                     <p> </p>                        <p>  <img src=/tuit/img/textbook/aa-setkani.gif border=0 width=100 height=84 alt=>         <br>  [$1,text 15] </p>    </td>    <td align=center valign=top width=32% height=113>                     <p><img src=/tuit/img/textbook/aa-odchod.gif alt= width=100 height=81>        <br>        </p>               <p>[$1,text 15]</p>    </td>    </tr>            </tbody>   </table>   <br>   <br>  <br> <br> ', 3, NULL),
(1986, 1, 'Hotovo W1 (6-8) Jak se máte?', '', 58, '', '<H1><FONT color=#330099>Jak se máte?</FONT></H1><BR>\r\n<P></P>\r\n<TABLE cellSpacing=0 cellPadding=2 width=\"100%\" border=0>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=top align=middle width=\"50%\" height=229>\r\n<P align=center><IMG style=\"WIDTH: 390px; HEIGHT: 285px\" height=502 alt=\"\" src=\"http://www.bohemica.com/tuit/img/textbook/ab-jaksemate1.jpg\" width=631 align=default border=2></P></TD>\r\n<TD class=\"\" vAlign=top align=middle width=\"50%\" height=200>\r\n<P align=left><IMG style=\"WIDTH: 385px; HEIGHT: 289px\" height=499 alt=\"\" src=\"http://www.bohemica.com/tuit/img/textbook/ab-jaksemate2.jpg\" width=627 border=2></P></TD></TR>\r\n<TR>\r\n<TD class=\"\" vAlign=top align=left width=\"50%\" height=200>\r\n<P align=left><IMG style=\"WIDTH: 393px; HEIGHT: 318px\" height=494 alt=\"\" src=\"http://www.bohemica.com/tuit/img/textbook/ab-jaksemate3.jpg\" width=634 border=2></P>\r\n<P align=left>&nbsp;</P></TD>\r\n<TD vAlign=top align=middle width=\"50%\" height=236>\r\n<P align=left><IMG title=\"\" style=\"WIDTH: 395px; HEIGHT: 326px\" height=498 alt=\"\" src=\"http://www.bohemica.com/tuit/img/textbook/ab-jaksemate4.jpg\" width=631 align=default border=2></P></TD></TR></TBODY></TABLE>\r\n<P></P>\r\n<H3><STRONG></STRONG><STRONG><FONT color=#330099>Představte sebe a Vaeho souseda učitelce!</FONT></STRONG></H3>\r\n<P><FONT color=#330099></FONT></P>\r\n<TABLE class=\"\" cellSpacing=0 cellPadding=2 width=\"98%\" bgColor=#b0c4de border=0>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=top width=\"100%\" height=26>&nbsp;<FONT color=#330099>[$1,text 50]</FONT></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=\"100%\">&nbsp;<FONT color=#330099>[$1,text 50]</FONT></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=\"100%\">&nbsp;<FONT color=#330099>[$1,text 50]</FONT></TD></TR></TBODY></TABLE>\r\n<P><FONT color=#330099></FONT></P>\r\n<P><FONT color=#330099></FONT></P>\r\n<H3><STRONG></STRONG><FONT color=#330099><STRONG>Napite ve správném </STRONG><STRONG>pořadí!</STRONG></FONT></H3>\r\n<P><FONT color=#330099></FONT></P>\r\n<TABLE class=\"\" cellSpacing=0 cellPadding=2 width=\"98%\" bgColor=#b0c4de border=0>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=top width=\"46%\" height=19><FONT color=#330099>&nbsp;Těí mě.</FONT></TD>\r\n<TD vAlign=top width=\"54%\" height=19><FONT color=#330099>1.[$1,text 30]</FONT></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=\"46%\" height=19><FONT color=#330099>&nbsp;Dobrý den, Jana Nováková.</FONT></TD>\r\n<TD vAlign=top width=\"54%\" height=19><FONT color=#330099>2.[$1,text 30]</FONT></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=\"46%\" height=19><FONT color=#330099>&nbsp;Těí mě.</FONT></TD>\r\n<TD vAlign=top width=\"54%\" height=19><FONT color=#330099>3.[$1,text 30]</FONT></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=\"46%\" height=19><FONT color=#330099>&nbsp;Jano, to je Jim.</FONT></TD>\r\n<TD vAlign=top width=\"54%\" height=19><FONT color=#330099>4.[$1,text 30]</FONT></TD></TR></TBODY></TABLE>\r\n<P><FONT color=#330099></FONT></P>\r\n<H3><STRONG></STRONG><FONT color=#330099><STRONG>Odpovězte!</STRONG> Answer!</FONT></H3>\r\n<P><FONT color=#330099></FONT></P>\r\n<TABLE class=\"\" cellSpacing=0 cellPadding=2 width=\"98%\" bgColor=#b0c4de border=0>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=top width=\"41%\" height=23><FONT color=#330099>Jak se má?</FONT></TD>\r\n<TD vAlign=bottom width=\"59%\" height=23><FONT color=#330099>[$1,text 30]</FONT></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=\"41%\" height=19><FONT color=#330099>Ahoj!</FONT></TD>\r\n<TD vAlign=top width=\"59%\" height=19><FONT color=#330099>[$1,text 30]</FONT></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=\"41%\" height=19><FONT color=#330099>Dobrý den. Já jsem Pavel Novák.</FONT></TD>\r\n<TD vAlign=top width=\"59%\" height=19><FONT color=#330099>[$1,text 30]</FONT></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=\"41%\" height=19><FONT color=#330099>Ahoj. Já jsem Eva.</FONT></TD>\r\n<TD vAlign=top width=\"59%\" height=19><FONT color=#330099>[$1,text 30]</FONT></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=\"41%\" height=19><FONT color=#330099>Na shledanou.</FONT></TD>\r\n<TD vAlign=top width=\"59%\" height=19><FONT color=#330099>[$1,text 30]</FONT></TD></TR></TBODY></TABLE>\r\n<P></P>\r\n<H3><STRONG></STRONG><STRONG><FONT color=#330099>Kdo je to?</FONT></STRONG></H3>\r\n<P align=center><FONT color=#330099>MU <IMG height=42 alt=\"\" src=\"http://www.bohemica.com/tuit/img/textbook/ab-muz.jpg\" width=39 border=0> <IMG height=39 alt=\"\" src=\"http://www.bohemica.com/tuit/img/textbook/ab-zena.jpg\" width=39 border=0> ENA<BR>Petr je mu. Anna je ena. </FONT></P>\r\n<P><FONT color=#330099><BR></FONT></P>\r\n<TABLE class=\"\" cellSpacing=0 cellPadding=2 width=\"97%\" bgColor=#b0c4de border=0>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=top align=right width=\"14%\" height=31><FONT color=#330099>Elika</FONT></TD>\r\n<TD vAlign=top width=\"5%\" height=31><FONT color=#330099>je</FONT></TD>\r\n<TD vAlign=top width=\"13%\" height=31><FONT color=#330099>[$1,text 6]</FONT></TD>\r\n<TD vAlign=top align=right width=\"15%\" height=31><FONT color=#330099>Tereza</FONT></TD>\r\n<TD vAlign=top width=\"5%\" height=31><FONT color=#330099>je</FONT></TD>\r\n<TD vAlign=top width=\"15%\" height=31><FONT color=#330099>[$1,text 6]</FONT></TD>\r\n<TD vAlign=top align=right width=\"14%\" height=31><FONT color=#330099>Luká</FONT></TD>\r\n<TD vAlign=top width=\"5%\" height=31><FONT color=#330099>je</FONT></TD>\r\n<TD vAlign=top width=\"13%\" height=31><FONT color=#330099>[$1,text 6]</FONT></TD></TR>\r\n<TR>\r\n<TD vAlign=top align=right width=\"14%\" height=27><FONT color=#330099>Erik</FONT></TD>\r\n<TD vAlign=top width=\"5%\" height=27><FONT color=#330099>je</FONT></TD>\r\n<TD vAlign=top width=\"13%\" height=27><FONT color=#330099>[$1,text 6]</FONT></TD>\r\n<TD vAlign=top align=right width=\"15%\" height=27><FONT color=#330099>Silvie</FONT></TD>\r\n<TD vAlign=top width=\"5%\" height=27><FONT color=#330099>je</FONT></TD>\r\n<TD vAlign=top width=\"15%\" height