(2059, 1, 'Hotovo W4 (41) Modální slovesa', 'Cvičení', 58, '', '<H3><FONT color=#330099>Přelote!</FONT></H3>\r\n<TABLE cellSpacing=2 cellPadding=2 bgColor=#b0c4de border=0>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=top width=244>\r\n<P><FONT color=#330099>V kolik hodin musí vstávat?</FONT></P></TD>\r\n<TD vAlign=top width=388>\r\n<P><FONT color=#330099>&nbsp;[$1,text 50]</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=244>\r\n<P><FONT color=#330099>V neděli nemusíme vstávat brzo.</FONT></P></TD>\r\n<TD vAlign=top width=388>\r\n<P><FONT color=#330099>&nbsp;[$1,text 50]</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=244>\r\n<P><FONT color=#330099>Co musí Petr dělat?</FONT></P></TD>\r\n<TD vAlign=top width=388>\r\n<P><FONT color=#330099>&nbsp;[$1,text 50]</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=244>\r\n<P><FONT color=#330099>Musíme obědvat ve 12:15.</FONT></P></TD>\r\n<TD vAlign=top width=388>\r\n<P><FONT color=#330099>&nbsp;[$1,text 50]</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=244>\r\n<P><FONT color=#330099>Večer se musíme učit česky.</FONT></P></TD>\r\n<TD vAlign=top width=388>\r\n<P><FONT color=#330099>&nbsp;[$1,text 50]</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=244>\r\n<P><FONT color=#330099>Děti musí jít spát brzo.</FONT></P></TD>\r\n<TD vAlign=top width=388>\r\n<P><FONT color=#330099>&nbsp;[$1,text 50]</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=244>\r\n<P><FONT color=#330099>V kolik hodin musíte večeřet?</FONT></P></TD>\r\n<TD vAlign=top width=388>\r\n<P><FONT color=#330099>&nbsp;[$1,text 50]</FONT></P></TD></TR></TBODY></TABLE>\r\n<P><FONT color=#330099></FONT>&nbsp;</P>\r\n<H3><FONT color=#330099>Musí nebo nemusí?</FONT></H3>\r\n<TABLE cellSpacing=2 cellPadding=2 bgColor=#b0c4de border=0>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=bottom width=310>\r\n<P><I><FONT color=#330099>V&nbsp;neděli [$1,text 15:nemusí] Petr brzo vstávat.</FONT></I></P></TD>\r\n<TD vAlign=bottom width=321>\r\n<P><I><FONT color=#330099>V sobotu [$1,text 15:nemusí] jít do koly.</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=310>\r\n<P><I><FONT color=#330099>V úterý [$1,text 15:musí] jít Martin do práce.</FONT></I></P></TD>\r\n<TD vAlign=bottom width=321>\r\n<P><I><FONT color=#330099>V pondělí [$1,text 15:musí] Jana brzo vstávat.</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=310>\r\n<P><I><FONT color=#330099>Bob se [$1,text 15:musí] učit četinu.</FONT></I></P></TD>\r\n<TD vAlign=bottom width=321>\r\n<P><I><FONT color=#330099>Jiří se [$1,text 15:nemusí] dívat na televizi.</FONT></I></P></TD></TR></TBODY></TABLE>\r\n<P><FONT color=#330099></FONT>&nbsp;</P>\r\n<H3><FONT color=#330099>Musí nebo nesmí?</FONT></H3>\r\n<TABLE cellSpacing=2 cellPadding=2 bgColor=#b0c4de border=0>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=bottom width=380>\r\n<P><I><FONT color=#330099>David [$1,text 15:nesmí] kouřit v&nbsp;nemocnici.</FONT></I></P></TD>\r\n<TD vAlign=bottom width=321>\r\n<P><I><FONT color=#330099><IMG height=32 src=\"http://www.bohemica.com/tuit/img/textbook/ar-image004.gif\" width=32> &nbsp;Tady se [$1,text 15:nesmí] parkovat.</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD class=\"\" vAlign=bottom align=left width=380>\r\n<P><I><FONT color=#330099>V úterý [$1,text 15:musí] jít Lenka do koly.</FONT></I></P></TD>\r\n<TD vAlign=bottom width=321>\r\n<P><I><FONT color=#330099>Děti [$1,text 15:musí] jíst zeleninu.</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD class=\"\" vAlign=bottom align=left width=380>\r\n<P><I><FONT color=#330099>Děti [$1,text 15:nesmí] pít pivo.</FONT></I></P></TD>\r\n<TD vAlign=bottom width=321>\r\n<P><I><FONT color=#330099><IMG height=32 src=\"http://www.bohemica.com/tuit/img/textbook/ar-image006.gif\" width=32> Tady [$1,text 15:musíte] zastavit.</FONT></I></P></TD></TR></TBODY></TABLE><BR><BR>', 3, NULL),
(2061, 1, 'Hotovo W1 (10) Závěrečný dialog.', '', 58, '', '<P><FONT color=#330099 size=4><STRONG>Poslouchejte dialog!</STRONG></FONT></P>\r\n<TABLE cellSpacing=2 cellPadding=2 bgColor=#ffffcc border=0>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=top width=39>\r\n<P><B><I><FONT color=#330099><IMG id=_x0000_i1035 height=32 src=\"http://www.bohemica.com/tuit/img/textbook/ae-tnvr1.gif\" width=34></FONT></I></B></P></TD>\r\n<TD width=297>\r\n<P><I><FONT color=#330099>Dobrý den.</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=39>\r\n<P><B><I><FONT color=#330099><IMG id=_x0000_i1036 style=\"WIDTH: 32px; HEIGHT: 30px\" height=30 src=\"http://www.bohemica.com/tuit/img/textbook/ae-tnvr2.gif\" width=30></FONT></I></B></P></TD>\r\n<TD width=297>\r\n<P><I><FONT color=#330099>Dobrý den.</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=39>\r\n<P><B><I><FONT color=#330099><IMG id=_x0000_i1037 height=32 src=\"http://www.bohemica.com/tuit/img/textbook/ae-tnvr1.gif\" width=34></FONT></I></B></P></TD>\r\n<TD width=297>\r\n<P><I><FONT color=#330099>Vy jste pan Krátký ?</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=39>\r\n<P><FONT color=#330099><IMG id=_x0000_i1038 style=\"WIDTH: 31px; HEIGHT: 30px\" height=30 src=\"http://www.bohemica.com/tuit/img/textbook/ae-tnvr2.gif\" width=30></FONT></P></TD>\r\n<TD width=297>\r\n<P><FONT color=#330099><I>Ano. </I>&nbsp;<I>Áááá .. Vy jste ten Američan!</I></FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=39>\r\n<P><B><I><FONT color=#330099><IMG id=_x0000_i1039 height=32 src=\"http://www.bohemica.com/tuit/img/textbook/ae-tnvr1.gif\" width=34></FONT></I></B></P></TD>\r\n<TD width=297>\r\n<P><I><FONT color=#330099>Ano. Jim Brown, těí mě!</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=39>\r\n<P><B><I><FONT color=#330099><IMG id=_x0000_i1040 style=\"WIDTH: 32px; HEIGHT: 31px\" height=30 src=\"http://www.bohemica.com/tuit/img/textbook/ae-tnvr2.gif\" width=30></FONT></I></B></P></TD>\r\n<TD width=297>\r\n<P><I><FONT color=#330099>Těí mě!</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=39>\r\n<P><B><I><FONT color=#330099><IMG id=_x0000_i1041 height=32 src=\"http://www.bohemica.com/tuit/img/textbook/ae-tnvr1.gif\" width=34></FONT></I></B></P></TD>\r\n<TD width=297>\r\n<P><I><FONT color=#330099>Pane Krátký, to je Jana.</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=39>\r\n<P><B><I><FONT color=#330099><IMG id=_x0000_i1042 height=30 src=\"http://www.bohemica.com/tuit/img/textbook/ae-tnvr3.gif\" width=30></FONT></I></B></P></TD>\r\n<TD width=297>\r\n<P><I><FONT color=#330099>Těí mě. Nováková.</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=39>\r\n<P><B><I><FONT color=#330099><IMG id=_x0000_i1043 style=\"WIDTH: 32px; HEIGHT: 31px\" height=30 src=\"http://www.bohemica.com/tuit/img/textbook/ae-tnvr2.gif\" width=30></FONT></I></B></P></TD>\r\n<TD width=297>\r\n<P><FONT color=#330099><I>Mě taky.</I> <I>Ale vy jste Čeka?!</I></FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=39>\r\n<P><B><I><FONT color=#330099><IMG id=_x0000_i1044 height=30 src=\"http://www.bohemica.com/tuit/img/textbook/ae-tnvr3.gif\" width=30></FONT></I></B></P></TD>\r\n<TD width=297>\r\n<P><I><FONT color=#330099>Ano.</FONT></I></P></TD></TR></TBODY></TABLE>\r\n<H3><FONT color=#330099>Odpovězte!</FONT></H3>\r\n<TABLE cellPadding=0 bgColor=#b0c4de border=0>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=top>\r\n<P><B><I><FONT color=#330099><IMG id=_x0000_i1045 height=30 src=\"http://www.bohemica.com/tuit/img/textbook/ae-tnvr2.gif\" width=30></FONT></I></B></P></TD>\r\n<TD vAlign=top><EM><FONT color=#330099>Kdo je to?</FONT></EM></TD>\r\n<TD vAlign=top>\r\n<P><FONT color=#330099>[$1,text 10]</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top>\r\n<P><B><I><FONT color=#330099><IMG id=_x0000_i1046 style=\"WIDTH: 31px; HEIGHT: 29px\" height=32 src=\"http://www.bohemica.com/tuit/img/textbook/ae-tnvr1.gif\" width=34></FONT></I></B></P></TD>\r\n<TD vAlign=top>\r\n<P><I><FONT color=#330099>Vy jste Američan?</FONT></I></P></TD>\r\n<TD vAlign=top>\r\n<P><FONT color=#330099>[$1,text 10]</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top>\r\n<P><B><I><FONT color=#330099><IMG id=_x0000_i1047 height=30 src=\"http://www.bohemica.com/tuit/img/textbook/ae-tnvr3.gif\" width=30></FONT></I></B></P></TD>\r\n<TD vAlign=top>\r\n<P><I><FONT color=#330099>Je to Anna?</FONT></I></P></TD>\r\n<TD vAlign=top>\r\n<P><FONT color=#330099>[$1,text 10]</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top>\r\n<P><B><I><FONT color=#330099><IMG id=_x0000_i1048 height=30 src=\"http://www.bohemica.com/tuit/img/textbook/ae-tnvr2.gif\" width=30></FONT></I></B></P></TD>\r\n<TD vAlign=top>\r\n<P><I><FONT color=#330099>Je to Čech?</FONT></I></P></TD>\r\n<TD vAlign=top>\r\n<P><FONT color=#330099>[$1,text 10]</FONT></P></TD></TR></TBODY></TABLE>\r\n<H3><FONT color=#330099>Napite dialog!</FONT></H3>\r\n<P><FONT color=#330099>&nbsp;[$1,textarea 50,10]</FONT></P>', 3, NULL),
(2062, 1, '', '', 58, 'Complete with', '<BR>\r\n<TABLE cellSpacing=2 cellPadding=2 bgColor=#ffcc00 border=0>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=top width=164 bgColor=#ffcc00 colSpan=3 rowSpan=5>\r\n<P align=center><FONT color=#330099><BR></FONT></P>\r\n<P align=center><B><FONT color=#330099>KÝM?</FONT></B></P>\r\n<P align=center><B><FONT color=#330099>ČÍM?</FONT></B></P></TD>\r\n<TD width=139 bgColor=#ffcc00 colSpan=2>\r\n<P align=center><B><FONT color=#330099>jet</FONT></B></P></TD>\r\n<TD width=473 bgColor=#ffcc00 colSpan=2>\r\n<P><I><FONT color=#330099>jedu, jede, jede, jedeme, jedete, jedou</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=139 bgColor=#ffcc00 colSpan=2>\r\n<P align=center><FONT color=#330099>setk<B><U>at se</U></B></FONT></P></TD>\r\n<TD width=473 bgColor=#ffcc00 colSpan=2>\r\n<P><I><FONT color=#330099>setkám se, setká se, setká se, setkáme se, setkáte se, setkají se</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=139 bgColor=#ffcc00 colSpan=2>\r\n<P align=center><FONT color=#330099>spoluprac<B><U>ovat</U></B></FONT></P></TD>\r\n<TD width=473 bgColor=#ffcc00 colSpan=2>\r\n<P><I><FONT color=#330099>spolupracuju, spolupracuje, spolupracuje, spolupracujeme, spolupracujete, psolupracujou</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=139 bgColor=#ffcc00 colSpan=2>\r\n<P align=center><FONT color=#330099><B>jet </B>s / <B>jít </B>s</FONT></P></TD>\r\n<TD width=473 bgColor=#ffcc00 colSpan=2>\r\n<P><FONT color=#330099></FONT></P><BR></TD></TR>\r\n<TR>\r\n<TD width=139 bgColor=#ffcc00 colSpan=2>\r\n<P align=center><FONT color=#330099>souhlas<B><U>it</U></B></FONT></P></TD>\r\n<TD width=473 bgColor=#ffcc00 colSpan=2>\r\n<P><I><FONT color=#330099>souhlasím, souhlasí, souhlasí, souhlasíme, souhlasíte, souhlasí</FONT></I></P></TD></TR></TBODY></TABLE>\r\n<H3><FONT color=#330099>Odpovězte!</FONT></H3>\r\n<TABLE cellSpacing=2 cellPadding=2 bgColor=#b0c4de border=0>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=bottom width=619>\r\n<P><FONT color=#330099>Čím jede?(auto, vlak, a