(2132, 1, 'Opakování kauzativu.', '', 58, '', '<H3 align=left><FONT color=#330099>Dělejte věty!</FONT></H3>\r\n<TABLE cellSpacing=2 cellPadding=2 bgColor=#b0c4de border=0>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=bottom width=196>\r\n<P><FONT color=#330099>Jana - mít  počítač.</FONT></P></TD>\r\n<TD width=407>\r\n<P><I><FONT color=#330099>[$1,text 30:Jana má počítač.]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=196>\r\n<P><FONT color=#330099>David - mít  mobil.</FONT></P></TD>\r\n<TD width=407>\r\n<P><I><FONT color=#330099>[$1,text 30:David má mobil.]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=196>\r\n<P><FONT color=#330099>Jana - nemít  telefon.</FONT></P></TD>\r\n<TD width=407>\r\n<P><I><FONT color=#330099>[$1,text 30:Jana nemá telefon.]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=196>\r\n<P><FONT color=#330099>Já  chtít  fotoaparát.</FONT></P></TD>\r\n<TD width=407>\r\n<P><I><FONT color=#330099>[$1,text 30:Chci fotoaparát.]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=196>\r\n<P><FONT color=#330099>David - nemít  nůky.</FONT></P></TD>\r\n<TD width=407>\r\n<P><I><FONT color=#330099>[$1,text 30:David nemá nůky.]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=196>\r\n<P><FONT color=#330099>Ty - nemít  klíč?</FONT></P></TD>\r\n<TD width=407>\r\n<P><I><FONT color=#330099>[$1,text 30:Nemá klíč?]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=196>\r\n<P><FONT color=#330099>Petr  nechtít  hrnek.</FONT></P></TD>\r\n<TD width=407>\r\n<P><I><FONT color=#330099>[$1,text 30:Petr nechce hrnek.]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=196>\r\n<P><FONT color=#330099>Co  oni  mít?</FONT></P></TD>\r\n<TD width=407>\r\n<P><I><FONT color=#330099>[$1,text 30:Co mají?]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=196>\r\n<P><FONT color=#330099>Já  potřebovat  idle.</FONT></P></TD>\r\n<TD width=407>\r\n<P><I><FONT color=#330099>[$1,text 30:Potřebuju idl