(2343, 1, '50/2', '', 58, '', '<P class=MsoNormal align=left><B><FONT color=#330099 size=4>Napite, co byste dělal!</FONT></B></P>\r\n<DIV align=left>\r\n<TABLE id=table13 cellSpacing=2 cellPadding=2 bgColor=#b0c4de border=0>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=bottom width=180 bgColor=#f2f2f2><FONT color=#330099>Hrát tenis</FONT></TD>\r\n<TD vAlign=bottom width=468><FONT color=#330099>[$1,text 60:Hrál bych tenis.]</FONT></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=180 bgColor=#f2f2f2><FONT color=#330099>Kadý den&nbsp; číst noviny</FONT></TD>\r\n<TD vAlign=bottom width=468><FONT color=#330099>[$1,text 60:Kadý den bych četl noviny.]</FONT></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom align=left width=180 bgColor=#f2f2f2><FONT color=#330099>Chodit na koncerty</FONT></TD>\r\n<TD vAlign=bottom width=468><FONT color=#330099>[$1, text 60:Chodil bych na koncerty.]</FONT></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=180 bgColor=#f2f2f2><FONT color=#330099>Jezdit na hory</FONT></TD>\r\n<TD vAlign=bottom width=468><FONT color=#330099>[$1, text 60:Jezdil bych na hory.]</FONT></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=180 bgColor=#f2f2f2><FONT color=#330099>Sportovat</FONT></TD>\r\n<TD vAlign=bottom width=468><FONT color=#330099>[$1,text 60:Sportoval bych.]</FONT></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=180 bgColor=#f2f2f2><FONT color=#330099>Mluvit jenom česky</FONT></TD>\r\n<TD vAlign=bottom width=468><FONT color=#330099>[$1,text 60:Mluvil bych jenom česky.]</FONT></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=180 bgColor=#f2f2f2><FONT color=#330099>Domluvit si schůzku</FONT></TD>\r\n<TD vAlign=bottom width=468><FONT color=#330099>[$1,text 60:Domluvil bych si schůzku.]</FONT></TD></TR></TBODY></TABLE></DIV>', 3, NULL),
