(1625, 1, 'Answer questions 2 (Nouns/Case/Genitive)', NULL, 49, '', '<h3>Kam pojedou na dovolenou?</h3>  <table cellSpacing=\"0\" cellPadding=\"0\" border=\"0\">    <tbody>      <tr>        <td vAlign=\"top\" width=\"234\">          <p><i>Vy!</i></p>        </td>        <td vAlign=\"top\" width=\"370\">          <p> [$1, text 40] </p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"234\">          <p><i>Vá český kamarád!</i></p>        </td>        <td vAlign=\"top\" width=\"370\">          <p> [$1, text 40] </p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"234\">          <p><i>Vae manelka / Vá manel!</i></p>        </td>        <td vAlign=\"top\" width=\"370\">          <p> [$1, text 40] </p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"234\">          <p><i>Vá tatínek a vae maminka!</i></p>        </td>        <td vAlign=\"top\" width=\"370\">          <p> [$1, text 40] </p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"234\">          <p><i>Vá éf!</i></p>        </td>        <td vAlign=\"top\" width=\"370\">          <p> [$1, text 40] </p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"234\">          <p><i>Pan Novák!</i></p>        </td>        <td vAlign=\"top\" width=\"370\">          <p>Pan Novák pojede do Francie a do řecka.</p>        </td>      </tr>    </tbody>  </table>   ', 3, ''),
(1626, 1, 'Choose correct answer (Nouns/Case/Genitive)', NULL, 49, '', '<h3>Co je dobře?</h3>  <table cellSpacing=\"0\" cellPadding=\"0\" border=\"0\">    <tbody>      <tr>        <td vAlign=\"top\" width=\"604\">          <p><i>Braunovi jsou u </i> [$1, select:/obchod/obchoda/(obchodu] .</p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"604\">          <p><i>Braunovi jsou u</i>  [$1, select:/(koly/kole/kolu] .</p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"604\">          <p><i>Braunovi jsou u</i>  [$1, select:/potu/(poty/potě] .</p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"604\">          <p><i>Braunovi jsou u</i>  [$1, select:/park/parkem/(parku] .</p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"604\">          <p><i>Braunovi jsou u</i>  [$1, select:/babičce/(babičky/babičku] .</p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"604\">          <p><i>Braunovi jsou u</i>  [$1, select:/(kamaráda/kamarád/kamaráde] .</p>        </td>      </tr>    </tbody>  </table>   ', 3, ''),
(1627, 1, 'Complete endings (Nouns/Case/Genitive)', NULL, 49, '', '<h3>Doplňte !</h3>  <p align=\"left\">Jdu do&nbsp;obchod [$1, text 1:u]  . Chodíme do hospod [$1, text 1:y] . Jedete do Prah [$1, text 1:y]  . Jde do restaurac [$1, text 1:e] . Chcete jít  do&nbsp;kin [$1, text 1:a] . Jezdíme do&nbsp;Brn [$1, text 1:a] . Chodíte do park [$1, text 1:u]  . Jde do&nbsp;kol [$1, text 1:y] ?</p>  ', 3, ''),
(1628, 1, 'Complete phrases (Nouns/Case/Genitive)', NULL, 49, '', '<h3>Co je to ?</h3>  <table cellSpacing=\"0\" cellPadding=\"0\" border=\"0\" width=\"100%\">    <tbody>      <tr height=\"114\">        <td width=\"84\">          <p align=\"center\"><img src=\"/tuit/img/exercises/mleko.gif\" width=\"61\" height=\"64\"></p>        </td>        <td>          <p align=\"left\"><i>láhev<br>          sklenice </i> [$1, text 5:mléka] <i><br>          krabice</i></td>        <td width=\"84\">          <p align=\"center\"><img src=\"/tuit/img/exercises/dzusu.gif\" width=\"49\" height=\"89\"></p>        </td>        <td>          <p><i>krabice</i>  [$1, text 5:dusu] </p>        </td>        <td width=\"84\">          <p align=\"center\"><img src=\"/tuit/img/exercises/kava.gif\" width=\"79\" height=\"73\"></p>        </td>        <td>          <p><i>álek</i>  [$1, text 4:kávy] </p>        </td>      </tr>      <tr height=\"114\">        <td width=\"84\">          <p align=\"center\"><img src=\"/tuit/img/exercises/vino.gif\" width=\"23\" height=\"65\"></p>        </td>        <td>          <p align=\"left\"><i>láhev </i> [$1, text 4:vína] </p>        </td>        <td width=\"84\">          <p align=\"center\"><img src=\"/tuit/img/exercises/voda.gif\" width=\"48\" height=\"64\"></p>        </td>        <td>          <p><i>sklenice </i> [$1, text 4:vody] </p>        </td>        <td width=\"84\">          <p align=\"center\"><img src=\"/tuit/img/exercises/polevka.gif\" width=\"74\" height=\"93\"></p>        </td>        <td>          <p><i>talíř</i>  [$1, text 7:polévky] </p>        </td>      </tr>      <tr>        <td width=\"84\">          <p align=\"left\"><img src=\"/tuit/img/exercises/cokolada.gif\" width=\"88\" height=\"54\"></p>        </td>        <td>          <p><i>balíček</i>  [$1, text 8:čokolády] </p>        </td>        <td vAlign=\"bottom\" width=\"84\">          <p align=\"center\"><img src=\"/tuit/img/exercises/fanta.gif\" width=\"29\" height=\"74\"></p>     