(1767, 1, 'Convert adjectives to adverbs 2 (Adverbs)', NULL, 49, '', '<h3>Doplňte!</h3>  <table cellSpacing=\"0\" cellPadding=\"0\" border=\"0\">    <tbody>      <tr>        <td vAlign=\"top\" width=\"206\">          <p><i>Dnes je hezké počasí.</i></p>        </td>        <td vAlign=\"top\" width=\"387\">          <p>Je  [$1, text 8:hezky] .</p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"206\">          <p><i>Je dobrý kamarád.</i></p>        </td>        <td vAlign=\"top\" width=\"387\">          <p>Studuje <b>dobře.</b></p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"206\">          <p><i>To je dlouhý úkol.</i></p>        </td>        <td vAlign=\"top\" width=\"387\">          <p>Budu ho psát  [$1, text 8:dlouho] </p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"206\">          <p><i>Zítra ráno jedeme na výlet.</i></p>        </td>        <td vAlign=\"top\" width=\"387\">          <p>Musíme  [$1, text 8:brzo] &nbsp;vstávat.</p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"206\">          <p><i>Je to daleko?</i></p>        </td>        <td vAlign=\"top\" width=\"387\">          <p>Ne je to  [$1, text 8:blízko] </p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"206\">          <p><i>Snědl jsem patný párek.</i></p>        </td>        <td vAlign=\"top\" width=\"387\">          <p>Je mi  [$1, text 8:patně] </p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"206\">          <p><i>Kolik chce kávy?</i></p>        </td>        <td vAlign=\"top\" width=\"387\">          <p>Jenom  [$1, text 8] , prosím.</p>        </td>      </tr>    </tbody>  </table>   ', 3, ''),
