(1879, 1, 'Complete words (Spelling)', NULL, 49, '', '<h3>Doplňte!</h3>  <p> [$1, text 1:a] hoj, ja [$1, text 1:k] , r [$1, text 1:á] no,  pros [$1, text 1:í] m,  [$1, text 1:d] obrý, de [$1, text 1:n] ,  n [$1, text 1:o] c, d [$1, text 1:ě] kuju,  [$1, text 1:j] e,  na shledano [$1, text 1:u] , jmen [$1, text 1:u] je, doubr [$1, text 2:ou]  ch [$1, text 1:u] </p>   ', 3, ''),
(1880, 1, 'Correct telegram (Spelling)', NULL, 49, '', '<h3>Doplňte háčky a čárky!</h3>  <table cellSpacing=\"0\" cellPadding=\"2\" border=\"2\" bordercolor=\"#000000\" width=\"621\" height=\"520\">    <tbody>      <tr>        <td vAlign=\"top\" width=\"632\" colSpan=\"5\" height=\"63\">          <p><b><big>Telegram</big></b></p>          <p><b>Pite čitelně  adresu hůlkovým písmem!          &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;          </b><sub>Silně orámované části vyplní odesílatel!</sub></p>        </td>      </tr>      <tr height=\"38\">        <td vAlign=\"top\" width=\"201\" height=\"120\" colspan=\"2\" rowspan=\"2\">          <p></p>        </td>        <td vAlign=\"top\" width=\"218\" height=\"76\">          <p><b>Adresa odesílatele<br>          <br>          </b>Jim Brown<br>          nam. B. Smetany 15<br>          Jihlava</p>        </td>        <td vAlign=\"top\" width=\"194\" height=\"82\"> [$1, textarea 20,4] </td>        <td vAlign=\"top\" width=\"1\" height=\"120\" rowspan=\"2\"></td>      </tr>      <tr height=\"38\">        <td vAlign=\"top\" width=\"218\" height=\"32\">          <p>&nbsp;</p>        </td>        <td vAlign=\"top\" width=\"194\" height=\"32\"></td>      </tr>      <tr height=\"19\">        <td vAlign=\"top\" width=\"650\" height=\"19\" colspan=\"4\"></td>      </tr>      <tr height=\"38\">        <td vAlign=\"top\" width=\"632\" height=\"32\" colspan=\"5\"></td>      </tr>      <tr height=\"76\">        <td vAlign=\"top\" width=\"60\" height=\"95\" style=\"border-style: solid\">          <p><b>Placené údaje</b></p>        </td>        <td vAlign=\"top\" width=\"566\" colSpan=\"4\" height=\"95\" style=\"border-style: solid\">          <p align=\"left\"><b>Adresa příjemce (jméno nebo označení  ulice           číslo domu  místo určení má-li adresát telefon, uveďte          jeho číslo před adresou!)</b></p>          <p>(0425) 56 256 21, Jan Holy, Dlouha 35, 470 01Ceska Lipa<br>   [$1, text 40] </p>        </td>      </tr>      <tr height=\"208\">        <td vAlign=\"top\" width=\"632\" colSpan=\"5\" height=\"155\" style=\"border-style: solid\">          <p><b>Text a podpis</b></p>          <p>Prijedu do Ceske Lipy ve ctvrtek 27. 7. ve 14:35 na autobusove          nadrazi.</p>          <p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;          Jim Brown<br>   [$1, textarea 50,3] </p>        </td>      </tr>    </tbody>  </table>   ', 3, ''),
(1881, 1, 'Separate words in sentences (Spelling)', NULL, 49, '', '<h3>Napite věty!</h3>  <table cellSpacing=\"0\" cellPadding=\"0\" border=\"0\" width=\"607\">    <tbody>      <tr>        <td vAlign=\"top\" width=\"248\">          <p>KOLIKJEHODIN?</p>        </td>        <td vAlign=\"top\" width=\"355\">          <p> [$1, text 40] </p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"248\">          <p>JMENUJUSEOLGA.</p>        </td>        <td vAlign=\"top\" width=\"355\"> [$1, text 40] </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"248\">          <p>UčÍMSEČESKY.</p>        </td>        <td vAlign=\"top\" width=\"355\"> [$1, text 40] </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"248\">          <p>VEČERDĚLÁMDOMÁCÍÚKOLY.</p>        </td>        <td vAlign=\"top\" width=\"355\">          <p> [$1, text 40] </p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"248\">          <p>RÁDJEZDÍMNAKOLE.</p>        </td>        <td vAlign=\"top\" width=\"355\"> [$1, text 40] </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"248\">          <p>MÁMDOBROUVODU.</p>        </td>        <td vAlign=\"top\" width=\"355\"> [$1, text 40] </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"248\">          <p>JAKSEMÁ?</p>        </td>        <td vAlign=\"top\" width=\"355\">          <p> [$1, text 40] </p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"248\">          <p>DOKOLYCHODÍMPĚKY.</p>        </td>        <td vAlign=\"top\" width=\"355\">          <p> [$1, text 40] </p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"248\">          <p>MONÁPůJDEMEDOHOSPODY.</p>        </td>        <td vAlign=\"top\" width=\"355\"> [$1, text 40] </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"248\">VPĚTHODINJDEMEDOMů.</td>        <td vAlign=\"top\" width=\"355\"> [$1, text 40] </td>      </tr>    </tbody>  </table>   ', 3, ''),
(1882, 1, 'Separate words in sentences 2 (Spelling)', NULL, 49, '', '<h3>Napite&nbsp; věty</h3>  <table cellSpacing=\"0\" cellPadding=\"0\" border=\"0\">    <tbody>      <tr>        <td vAlign=\"top\" width=\"225\">          <p><i>minulývíkendjsmebylivpraze</i></p>        </td>        <td vAlign=\"top\" width=\"379\">          <p>&nbsp; [$1, text 50] </p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"225\">          <p><i>dámtidárekknarozeninám</i></p>        </td>        <td vAlign=\"top\" width=\"379\">          <p>&nbsp; [$1, text 50] </p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"225\">          <p><i>cojsiměldneskakesnídani</i></p>        </td>        <td vAlign=\"top\" width=\"379\">          <p>&nbsp; [$1, text 50] </p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"225\">          <p><i>dnesjehezképočasí,svítíslunce</i></p>        </td>        <td vAlign=\"top\" width=\"379\">          <p>&nbsp; [$1, text 50] </p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"225\">          <p><i>vziměrádalyuju</i></p>        </td>        <td vAlign=\"top\" width=\"379\">          <p>&nbsp; [$1, text 50] </p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"225\">          <p><i>podstolemjekniha</i></p>        </td>        <td vAlign=\"top\" width=\"379\">          <p>&nbsp; [$1, text 50] </p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"225\">          <p><i>častochodilinaprocházku</i></p>        </td>        <td vAlign=\"top\" width=\"379\">          <p>&nbsp; [$1, text 50] </p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"225\">          <p><i>kadýdenobědvámevmenze</i></p>        </td>        <td vAlign=\"top\" width=\"379\">          <p>&nbsp; [$1, text 50] </p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"225\">          <p><i>bolíměvkrku</i></p>        </td>        <td vAlign=\"top\" width=\"379\">          <p>&nbsp; [$1, text 50] </p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"225\">          <p><i>janabylauzubaře</i></p>        </td>        <td vAlign=\"top\" width=\"379\">          <p>&nbsp; [$1, text 50] </p>        </td>      </tr>    </tbody>  </table>   ', 3, ''),
(1883, 1, 'Compare <i>chodit</i> and <i>jezdit</i> (Idioms)', NULL, 49, '', '<h3>Chodit nebo jezdit.</h3>  <p>Kadý rok    [$1, text 7:jezdím]   na hory. <b>(já) </b>Ve středu    [$1, text 7:chodím]   cvičit.  <b>(já)  </b>   [$1, text 7:jezdí]   na kole? <b>(ty) </b>Ano,    [$1, text 7:jezdím]  . Jana  ráda    [$1, text 7:chodí]   pěky, ale Petr ne. Kadou sobotu    [$1, text 7:chodí]    plavat do  bazénu. <b> (oni)</b>    [$1, text 7:jezdíte]   hrát golf do Karlových Varů?  <b>  (vy)  </b>Obvykle    [$1, text 7:chodím]   nakupovat ráno.  <b> (já)</b></p>  <p><img src=\"/tuit/img/exercises/jezdit.gif\" width=\"144\" height=\"114\"> <img src=\"/tuit/img/exercises/chodit.gif\" width=\"107\" height=\"85\"></p>   ', 3, ''),
(1884, 1, 'Compare <i>jít</i> and <i>jet</i> (Idioms)', NULL, 49, '', '<h3><i>jít  </i></b><i>x  jet</i></h3>  <p>Kdy <b>(vy) </b>   [$1, text 6:jedete]   do Budapeti ? V sobotu.<b> (ona)</b>    [$1, text 6:jde]  do parku. Ve středu <b>(já)</b>    [$1, text 6:jdu]   do hospody. V úterý <b>(on)</b>    [$1, text 6:jede]  autobusem do Prahy. Kdy <b>(vy) </b>   [$1, text 6:jedete]   do Ameriky? <b>(ty)</b>    [$1, text 6:jde]  do restaurace ?  Kdy <b>(oni)</b>    [$1, text 6:jedou]   do Brna?<b> (my)</b>    [$1, text 6:jedeme]  autobusem. <b>(já)</b> ne   [$1, text 6:jdu]   domů .</p>   ', 3, ''),
(1885, 1, 'Write what you like (Idioms)', NULL, 49, '', '<h3>Napi, co se ti líbí nebo nelíbí!</h3>  <table cellSpacing=\"0\" cellPadding=\"0\" border=\"0\" width=\"874\">    <tbody>      <tr height=\"32\">        <td vAlign=\"top\" width=\"101\">          <p><i>literatura</i></p>        </td>        <td vAlign=\"top\" width=\"415\">          <p>    [$1, text 40]  </p>        </td>      </tr>      <tr height=\"32\">        <td vAlign=\"top\" width=\"101\">          <p><i>četina</i></p>        </td>        <td vAlign=\"top\" width=\"415\">          <p>Líbí se mi četina.</p>        </td>      </tr>      <tr height=\"32\">        <td vAlign=\"top\" width=\"101\">          <p><i>architektura</i></p>        </td>        <td vAlign=\"top\" width=\"415\">    [$1, text 40]  </td>      </tr>      <tr height=\"32\">        <td vAlign=\"top\" width=\"101\">          <p><i>eny</i></p>        </td>        <td vAlign=\"top\" width=\"415\">    [$1, text 40]  </td>      </tr>      <tr height=\"32\">        <td vAlign=\"top\" width=\"101\">          <p><i>mui</i></p>        </td>        <td vAlign=\"top\" width=\"415\">    [$1, text 40]  </td>      </tr>      <tr height=\"32\">        <td vAlign=\"top\" width=\"101\">          <p><i>kultura</i></p>        </td>        <td vAlign=\"top\" width=\"415\">    [$1, text 40]  </td>      </tr>      <tr height=\"32\">        <td vAlign=\"top\" width=\"101\">          <p><i>Praský hrad</i></p>        </td>        <td vAlign=\"top\" width=\"415\">    [$1, text 40]  </td>      </tr>      <tr height=\"32\">        <td vAlign=\"top\" width=\"101\">          <p><i>Praha</i></p>        </td>        <td vAlign=\"top\" width=\"415\">    [$1, text 40]  </td>      </tr>      <tr height=\"32\">        <td vAlign=\"top\" width=\"101\">          <p><i>Amerika</i></p>        </td>        <td vAlign=\"top\" width=\"415\">    [$1, text 40]  </td>      </tr>    </tbody>  </table>    ', 3, ''),
(1886, 1, 'Write what you like 2 (Idioms)', NULL, 49, '', '<h3>Napi, co má rád!</h3>  <table cellSpacing=\"0\" cellPadding=\"0\" border=\"0\">    <tbody>      <tr height=\"32\">        <td vAlign=\"top\" width=\"121\">          <p><i>pivo</i></p>        </td>        <td vAlign=\"top\" width=\"28\">          <p> </p>        </td>        <td vAlign=\"top\" width=\"351\">          <p>    [$1, text 30]  </p>        </td>      </tr>      <tr height=\"32\">        <td vAlign=\"top\" width=\"121\">          <p><i>knedlíky</i></p>        </td>        <td vAlign=\"top\" width=\"28\">          <p> </p>        </td>        <td vAlign=\"top\" width=\"351\">          <p>    [$1, text 30]  </p>        </td>      </tr>      <tr height=\"32\">        <td vAlign=\"top\" width=\"121\">          <p><i>víno</i></p>        </td>        <td vAlign=\"top\" width=\"28\">          <p> </p>        </td>        <td vAlign=\"top\" width=\"351\">          <p>    [$1, text 30]  </p>        </td>      </tr>      <tr height=\"32\">        <td vAlign=\"top\" width=\"121\">          <p><i>káva</i></p>        </td>        <td vAlign=\"top\" width=\"28\">          <p> </p>        </td>        <td vAlign=\"top\" width=\"351\">          <p>    [$1, text 30]  </p>        </td>      </tr>      <tr height=\"32\">        <td vAlign=\"top\" width=\"121\">          <p><i>čaj</i></p>        </td>        <td vAlign=\"top\" width=\"28\">          <p> </p>        </td>        <td vAlign=\"top\" width=\"351\">          <p>    [$1, text 30]  </p>        </td>      </tr>      <tr height=\"32\">        <td vAlign=\"top\" width=\"121\">          <p><i>ovoce</i></p>        </td>        <td vAlign=\"top\" width=\"28\">          <p> </p>        </td>        <td vAlign=\"top\" width=\"351\">          <p>    [$1, text 30]  </p>        </td>      </tr>      <tr height=\"32\">        <td vAlign=\"top\" width=\"121\">          <p><i>zelenina</i></p>        </td>        <td vAlign=\"top\" width=\"28\">          <p> </p>        </td>        <td vAlign=\"top\" width=\"351\">          <p>                         Mám rád zeleninu.</p>        </td>      </tr>      <tr height=\"32\">        <td vAlign=\"top\" width=\"121\">          <p><i>sýr</i></p>        </td>        <td vAlign=\"top\" width=\"28\">          <p> </p>        </td>        <td vAlign=\"top\" width=\"351\">          <p>    [$1, text 30]  </p>        </td>      </tr>      <tr height=\"32\">        <td vAlign=\"top\" width=\"121\">          <p><i>slivovice</i></p>        </td>        <td vAlign=\"top\" width=\"28\">          <p> </p>        </td>        <td vAlign=\"top\" width=\"351\">          <p>    [$1, text 30]  </p>        </td>      </tr>      <tr height=\"32\">        <td vAlign=\"top\" width=\"121\">          <p><i>becherovka</i></p>        </td>        <td vAlign=\"top\" width=\"28\">          <p> </p>        </td>        <td vAlign=\"top\" width=\"351\">          <p>    [$1, text 30]  </p>        </td>      </tr>      <tr height=\"32\">        <td vAlign=\"top\" width=\"121\">          <p><i>Amerika</i></p>        </td>        <td vAlign=\"top\" width=\"28\">          <p> </p>        </td>        <td vAlign=\"top\" width=\"351\">          <p>    [$1, text 30]  </p>        </td>      </tr>    </tbody>  </table>    ', 3, ''),
(1887, 1, 'Complete <i>potom, nejdřív, první</i> (Idioms)', NULL, 49, '', '<h3>Doplňte <i>potom</i>, <i>nejdřív, první</i> !</h3>  <p>Můj    [$1, text 7:první]   den v Praze.</p>  <p>Moje    [$1, text 7:první]   noc v České republice.</p>  <p>Její    [$1, text 7:první]   manel se jmenuje Pavel.</p>  <p>   [$1, text 7:Nejdřív]   se  sprchuju,    [$1, text 7:potom]   snídám.</p>  <p>   [$1, text 7:Nejdřív]   jdu do koupelny,    [$1, text 7:potom]   do kuchyně.</p>  <p>   [$1, text 7:První]   den v týdnu je pondělí.</p>  <p>   [$1, text 7:První]   Čech na Severním pólu.</p>  <p>   [$1, text 7:Nejdřív]   se budu dívat na televizi,    [$1, text 7:potom]   si budu číst.</p>  <p>   [$1, text 7:První]   měsíc v roce je leden.</p>   ', 3, ''),
(1888, 1, 'Complete <i>znát, vědět, umět </i> 2', NULL, 49, '', '<h3>Doplňte <i>znát</i>, <i>vědět, umět </i>!</h3>  <p>Pane Horáku,    [$1, text 8:znáte]   pana Malého?  Paní inenýrko,    [$1, text 8:umíte]  francouzky?  Pane doktore,    [$1, text 8:víte]  ,  e Dominik je nemocný?  Tomái,    [$1, text 8:zná]   tu krásnou enu?  Martino,    [$1, text 8:umí]   jezdit na kole?  Prosím  Vás,    [$1, text 8:víte]  ,  kdy jede autobus do Praha ? Braunovi,    [$1, text 8:znáte]   film  Titanik? Katko    [$1, text 8:víte]  ,  jak se jmenuje tenhle pán?  Petr nikoho    [$1, text 8:nezná]  .  Nikdo nic     [$1, text 8:neví]  .  </p>   ', 3, ''),
(1889, 1, 'Complete <i>znát, vědět, umět </i> 2 (Idioms)', NULL, 49, '', '<h3>Doplňte <i>znát, vědět, umět </i>!</h3>  <table cellSpacing=\"0\" cellPadding=\"3\" border=\"0\" width=\"476\">    <tbody>      <tr>        <td vAlign=\"top\" width=\"195\">          <p align=\"right\">   [$1, text 10]  </td>        <td vAlign=\"top\" width=\"277\">          <p>Karel dobře plavat?</p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"195\">          <p align=\"right\">   [$1, text 10]  </td>        <td vAlign=\"top\" width=\"277\">          <p>, kde je pan ředitel?</p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"195\">          <p align=\"right\">   [$1, text 10]  </td>        <td vAlign=\"top\" width=\"277\">          <p>pana ředitele?</p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"195\">          <p align=\"right\">   [$1, text 10]  </td>        <td vAlign=\"top\" width=\"277\">          <p>tady nikoho.</p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"195\">          <p align=\"right\">   [$1, text 10]  </td>        <td vAlign=\"top\" width=\"277\">          <p>nic.</p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"195\">          <p align=\"right\">   [$1, text 10]  </td>        <td vAlign=\"top\" width=\"277\">          <p>Billa Piatta.</p>        </td>      </tr>    </tbody>  </table>   ', 3, ''),
(1890, 1, 'Compare <i>jít</i> and <i>jet</i> 2 (Idioms)', NULL, 49, '', '<h3>Doplňte</h3>  <p><b>půjdu - pojedu</b></p>  <p>V sobotu     [$1, text 12:pojedu]   do českých Budějovic. Nechci jet autem,     [$1, text 12:půjdu]   pěky.  Katka     [$1, text 12:půjde]   zítra do kina. Petr tam     [$1, text 12:pojede]   autem.</p>  <p><b>jít - jet</b></p>  <p align=\"left\">    [$1, text 12:jedu]   na kole,     [$1, text 12:jdu]   pěky,     [$1, text 12:jdu]   na procházku,     [$1, text 12:jedu]   do Ostravy,     [$1, text 12:jdu]   do restaurace,     [$1, text 12:jdu]   do postele</p>    ', 3, ''),
