(1893, 1, 'Seasons (Idioms)', NULL, 49, '', '<h3>Který měsíc nebo období?</h3>  <table cellSpacing=\"0\" cellPadding=\"0\" border=\"0\">    <tbody>      <tr>        <td vAlign=\"top\" width=\"168\">          <p><i>Kdy jsou prázdniny?</i></p>        </td>        <td vAlign=\"top\" width=\"436\">          <p> [$1, text 40] </p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"168\">          <p><i>Kdy jsou vánoce?</i></p>        </td>        <td vAlign=\"top\" width=\"436\">          <p> [$1, text 40] </p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"168\">          <p><i>Kdy jsou velikonoce?</i></p>        </td>        <td vAlign=\"top\" width=\"436\">          <p> [$1, text 40] </p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"168\">          <p><i>Kdy má narozeniny?</i></p>        </td>        <td vAlign=\"top\" width=\"436\">          <p> [$1, text 40] </p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"168\">          <p><i>Kdy sněí?</i></p>        </td>        <td vAlign=\"top\" width=\"436\">          <p>&nbsp; Sněí v zimě.</p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"168\">          <p><i>Kdy hodně prí?</i></p>        </td>        <td vAlign=\"top\" width=\"436\">          <p> [$1, text 40] </p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"168\">          <p><i>Kdy lyuje?</i></p>        </td>        <td vAlign=\"top\" width=\"436\">          <p> [$1, text 40] </p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"168\">          <p><i>Kdy svítí slunce?</i></p>        </td>        <td vAlign=\"top\" width=\"436\">          <p> [$1, text 40] </p>        </td>      </tr>    </tbody>  </table>   ', 3, ''),
(1894, 1, 'Translate sentences (Idioms)', NULL, 49, '', '<h3>Co to vlastně znamená? Translate idiomatically.</h3>  <table cellSpacing=\"0\" cellPadding=\"0\" border=\"0\">    <tbody>      <tr>        <td vAlign=\"top\" width=\"604\">          <p><i>Nechce jít zítra na pivo?</i></p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"604\">          <p> [$1, textarea 60,2] </p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"604\">          <p><i>Nevíte, kde je tady nádraí?</i></p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"604\">          <p> [$1, textarea 60,2] </p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"604\">          <p><i>Nemáte, prosím Vás, jízdní řád?</i></p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"604\">          <p> [$1, textarea 60,2] </p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"604\">          <p><i>Nechcete jetě trochu polévky?</i></p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"604\">          <p> [$1, textarea 60,2] </p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"604\">          <p><i>Nemáte, prosím Vás, chvíli čas?</i></p>        </td>      </tr>      <tr>        <td vAlign=\"top\" width=\"604\">          <p> [$1, textarea 60,2] </p>        </td>      </tr>    </tbody>  </table>   ', 3, '');
