(1895, 1, 'Weights and measures (Idioms)', NULL, 49, '', '<h3>V obchodě:<br>  &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <i>Prosím INSERT INTO `exercises` (`ex_id`, `ex_type`, `ex_name`, `ex_description`, `ex_creator`, `ex_task`, `ex_story`, `ex_difficulty`, `ex_options`) VALUES
(1918, 1, 'Translate sentences 5 (Vocabulary)', NULL, 49, '', '<h3>Přelote!</h3>  <table cellSpacing=\"0\" cellPadding=\"0\" border=\"0\">    <tbody>      <tr height=\"20\">        <td vAlign=\"top\" width=\"604\" height=\"20\">          <p><i>I like to watch TV.</i></p>        </td>      </tr>      <tr height=\"20\">        <td vAlign=\"top\" width=\"604\" height=\"20\">          <p> [$1, text 60] </p>        </td>      </tr>      <tr height=\"20\">        <td vAlign=\"top\" width=\"604\" height=\"20\">          <p><i>My wife likes to look at young men.</i></p>        </td>      </tr>      <tr height=\"20\">        <td vAlign=\"top\" width=\"604\" height=\"20\">          <p> [$1, text 60] </p>        </td>      </tr>      <tr height=\"20\">        <td vAlign=\"top\" width=\"604\" height=\"20\">          <p><i>I will never forget you!</i></p>        </td>      </tr>      <tr height=\"20\">        <td vAlign=\"top\" width=\"604\" height=\"20\">          <p> [$1, text 60] </p>        </td>      </tr>      <tr height=\"20\">        <td vAlign=\"top\" width=\"604\" height=\"20\">          <p><i>Excuse me. I forgot all about it.</i></p>        </td>      </tr>      <tr height=\"20\">        <td vAlign=\"top\" width=\"604\" height=\"20\">          <p> [$1, text 60] </p>        </td>      </tr>      <tr height=\"20\">        <td vAlign=\"top\" width=\"604\" height=\"20\">          <p><i>Who are you waiting for?</i></p>        </td>      </tr>      <tr height=\"20\">        <td vAlign=\"top\" width=\"604\" height=\"20\">          <p> [$1, text 60] </p>        </td>      </tr>      <tr height=\"20\">        <td vAlign=\"top\" width=\"604\" height=\"20\">          <p><i>I am waiting for two our teachers.</i></p>        </td>      </tr>      <tr height=\"20\">        <td vAlign=\"top\" width=\"604\" height=\"20\">          <p> [$1, text 60] </p>        </td>      </tr>      <tr height=\"20\">        <td vAlign=\"top\" width=\"604\" height=\"20\">          <p><i>I rely on you, Mrs. Veselá.</i></p>        </td>      </tr>      <tr height=\"20\">        <td vAlign=\"top\" width=\"604\" height=\"20\">          <p> [$1, text 60] </p>        </td>      </tr>      <tr height=\"20\">        <td vAlign=\"top\" width=\"604\" height=\"20\">          <p><i>We could not rely on anybody.</i></p>        </td>      </tr>      <tr height=\"20\">        <td vAlign=\"top\" width=\"604\" height=\"20\">          <p> [$1, text 60] </p>        </td>      </tr>    </tbody>  </table>  <table cellSpacing=\"0\" cellPadding=\"0\" border=\"0\">    <tbody>      <tr height=\"20\">        <td vAlign=\"top\" width=\"604\" height=\"20\">          <p><i>I will definitely get it!</i></p>        </td>      </tr>      <tr height=\"20\">        <td vAlign=\"top\" width=\"604\" height=\"20\">          <p> [$1, text 60] </p>        </td>      </tr>      <tr height=\"20\">        <td vAlign=\"top\" width=\"604\" height=\"20\">          <p><i>Parents think about you.</i></p>        </td>      </tr>      <tr height=\"20\">        <td vAlign=\"top\" width=\"604\" height=\"20\">          <p> [$1, text 60] </p>        </td>      </tr>      <tr height=\"20\">        <td vAlign=\"top\" width=\"604\" height=\"20\">          <p><i>Think of Henry!</i></p>        </td>      </tr>      <tr height=\"20\">        <td vAlign=\"top\" width=\"604\" height=\"20\">          <p> [$1, text 60] </p>        </td>      </tr>      <tr height=\"20\">        <td vAlign=\"top\" width=\"604\" height=\"20\">          <p><i>I am in the Czech Republic for two years.</i></p>        </td>      </tr>      <tr height=\"20\">        <td vAlign=\"top\" width=\"604\" height=\"20\">          <p> [$1, text 60] </p>        </td>      </tr>      <tr height=\"20\">        <td vAlign=\"top\" width=\"604\" height=\"20\">          <p><i>Czech students often go for a year to America.</i></p>        </td>      </tr>      <tr height=\"20\">        <td vAlign=\"top\" width=\"604\" height=\"20\"> [$1, text 60] </td>      </tr>    </tbody>  </table>   ', 3, ''),
(1919, 1, 'Presentation example', NULL, 49, '', '<h3>Doplňte věty</h3>  Petr má dvě     [$1, select:/auto/(auta/aut]  .<br>  Jana     [$1, text 4:má]   jedn    [$1, text 1:u]   knih    [$1, text 1:u]  .<p>   <i>Write about the accusative:</i><br>     [$1, textarea 60,3]   ', 3, ''),
(1921, 1, 'Moje pokuné čvičení', 'Blablablablablablablabla', 1, 'Complete', 'Something in the way [$2, radio kiss]<br><br>\r\nSomething in the day [$0, radio kiss]<br><br>\r\nSomething in the May [$1, radio kiss]<br><br>\r\nMy way [$3, checkbox].', 3, NULL),
(1922, 1, 'Kadý správný frajer, klobouk značky Majer', 'Hoho!', 1, 'Complete', '[\"text:dloooouhej text]', 3, NULL),
(1924, 6, 'Introductoin to Parts of Speech', '', 49, '', '<h4><b>Word classes - slovní druhy - parts of speech</b></a></h4>\r\n</div>\r\n<p>There are 10 word classes\r\nrecognized in the grammar of the Czech language:</p>\r\n<table border=0 cellspacing=0 cellpadding=0>\r\n <tr>\r\n <td width=227 valign=top>\r\n <p><i>1.<font size=1 face=\"Times New Roman\">      </i><b>Nouns</b></p>\r\n </td>\r\n <td width=132 valign=top>\r\n <p><i>podstatná jména</i></p>\r\n </td>\r\n </tr>\r\n <tr>\r\n <td width=227 valign=top>\r\n <p><i>2.<font size=1 face=\"Times New Roman\">      </i><b>Adjectives\r\n </b></p>\r\n </td>\r\n <td width=132 valign=top>\r\n <p><i>přídavná jména</i></p>\r\n </td>\r\n </tr>\r\n <tr>\r\n <td width=227 valign=top>\r\n <p><i>3.<font size=1 face=\"Times New Roman\">      </i><b>Pronouns</b></p>\r\n </td>\r\n <td width=132 valign=top>\r\n <p><i>zájmena</i></p>\r\n </td>\r\n </tr>\r\n <tr>\r\n <td width=227 valign=top>\r\n <p><i>4.<font size=1 face=\"Times New Roman\">      </i><b>Numerals</b></p>\r\n </td>\r\n <td width=132 valign=top>\r\n <p><i>číslovky</i></p>\r\n </td>\r\n </tr>\r\n <tr>\r\n <td width=227 valign=top>\r\n <p><i>5.<font size=1 face=\"Times New Roman\">      </i><b>Verbs</b></p>\r\n </td>\r\n <td width=132 valign=top>\r\n <p><i>slovesa</i></p>\r\n </td>\r\n </tr>\r\n <tr>\r\n <td width=227 valign=top>\r\n <p><i>6.<font size=1 face=\"Times New Roman\">      </i><b>Adverbs</b></p>\r\n </td>\r\n <td width=132 valign=top>\r\n <p><i>příslovce</i></p>\r\n </td>\r\n </tr>\r\n <tr>\r\n <td width=227 valign=top>\r\n <p><i>7.<font size=1 face=\"Times New Roman\">      </i><b>Prepositions</b></p>\r\n </td>\r\n <td width=132 valign=top>\r\n <p><i>předloky</i></p>\r\n </td>\r\n </tr>\r\n <tr>\r\n <td width=227 valign=top>\r\n <p><i>8.<font size=1 face=\"Times New Roman\">      </i><b>Conjunctions</b></p>\r\n </td>\r\n <td width=132 valign=top>\r\n <p><i>spojky</i></p>\r\n </td>\r\n </tr>\r\n <tr>\r\n <td width=227 valign=top>\r\n <p><i>9.<font size=1 face=\"Times New Roman\">      </i><b>Particles</b></p>\r\n </td>\r\n <td width=132 valign=top>\r\n <p><i>částice</i></p>\r\n </td>\r\n </tr>\r\n <tr>\r\n <td width=227 valign=top>\r\n <p><i>10.<font size=1 face=\"Times New Roman\">  </i><b>Interjections</b></p>\r\n </td>\r\n <td width=132 valign=top>\r\n <p><i>citoslovce</i></p>\r\n </td>\r\n </tr>\r\n</table>\r\n<p>The first 5\r\nclasses change their form in different contexts. The changes in 1  4 are\r\ncalled <i>declension</i>. The\r\nchanges in verbs (5) are called conjugation.</p>\r\n<p>Classes 6  10 do not change\r\ntheir form (with one minor exception).</p>\r\n', 2, NULL),
(1925, 6, 'Nouns Overview', 'Nouns Overview', 49, 'Nouns Overview', '<p><font size=\"2\"><span style=\"FONT-SIZE: 11pt\">When we talk about nouns, we\r\nindicate their:</span></font></p>\r\n<table style=\"BORDER-COLLAPSE: collapse\" cellSpacing=\"0\" cellPadding=\"0\" border=\"0\">\r\n  <tbody>\r\n    <tr>\r\n      <td style=\"PADDING-RIGHT: 5.4pt; PADDING-LEFT: 5.4pt; PADDING-BOTTOM: 0cm; WIDTH: 104.65pt; PADDING-TOP: 0cm\" vAlign=\"top\" width=\"140\" rowSpan=\"4\">\r\n        <p style=\"TEXT-ALIGN: left\" align=\"left\"> </p>\r\n      </td>\r\n      <td style=\"BORDER-RIGHT: windowtext 0.25pt solid; PADDING-RIGHT: 5.4pt; BORDER-TOP: windowtext 0.25pt solid; PADDING-LEFT: 5.4pt; PADDING-BOTTOM: 0cm; BORDER-LEFT: windowtext 0.25pt solid; WIDTH: 70.85pt; PADDING-TOP: 0cm; BORDER-BOTTOM: medium none\" vAlign=\"top\" width=\"94\">\r\n        <p style=\"TEXT-ALIGN: left\" align=\"left\"><font size=\"2\"><span style=\"FONT-SIZE: 11pt\">CASE</span></font></p>\r\n      </td>\r\n      <td style=\"PADDING-RIGHT: 5.4pt; PADDING-LEFT: 5.4pt; PADDING-BOTTOM: 0cm; WIDTH: 184.3pt; PADDING-TOP: 0cm\" vAlign=\"top\" width=\"246\">\r\n        <p style=\"TEXT-ALIGN: left\" align=\"left\"><font size=\"2\"><span style=\"FONT-SIZE: 11pt\">1st\r\n        - 7th</span></font></p>\r\n      </td>\r\n      <td style=\"PADDING-RIGHT: 5.4pt; PADDING-LEFT: 5.4pt; PADDING-BOTTOM: 0cm; WIDTH: 70.85pt; PADDING-TOP: 0cm\" vAlign=\"top\" width=\"94\">\r\n        <p style=\"TEXT-ALIGN: left\" align=\"left\"><i><font size=\"2\"><span style=\"FONT-SIZE: 11pt; FONT-STYLE: italic\">(pád</span></font><span style=\"FONT-STYLE: italic\">)</span></i></p>\r\n      </td>\r\n    </tr>\r\n    <tr>\r\n      <td style=\"BORDER-RIGHT: windowtext 0.25pt solid; PADDING-RIGHT: 5.4pt; BORDER-TOP: medium none; PADDING-LEFT: 5.4pt; PADDING-BOTTOM: 0cm; BORDER-LEFT: windowtext 0.25pt solid; WIDTH: 70.85pt; PADDING-TOP: 0cm; BORDER-BOTTOM: medium none\" vAlign=\"top\" width=\"94\">\r\n        <p style=\"TEXT-ALIGN: left\" align=\"left\"><font size=\"2\"><span style=\"FONT-SIZE: 11pt\">NUMBER</span></font></p>\r\n      </td>\r\n      <td style=\"PADDING-RIGHT: 5.4pt; PADDING-LEFT: 5.4pt; PADDING-BOTTOM: 0cm; WIDTH: 184.3pt; PADDING-TOP: 0cm\" vAlign=\"top\" width=\"246\">\r\n        <p style=\"TEXT-ALIGN: left\" align=\"left\"><font size=\"2\"><span style=\"FONT-SIZE: 11pt\">singular\r\n        or plural</span></font></p>\r\n      </td>\r\n      <td style=\"PADDING-RIGHT: 5.4pt; PADDING-LEFT: 5.4pt; PADDING-BOTTOM: 0cm; WIDTH: 70.85pt; PADDING-TOP: 0cm\" vAlign=\"top\" width=\"94\">\r\n        <p style=\"TEXT-ALIGN: left\" align=\"left\"><i><font size=\"2\"><span style=\"FONT-SIZE: 11pt; FONT-STYLE: italic\">(číslo</span></font><span style=\"FONT-STYLE: italic\">)</span></i></p>\r\n      </td>\r\n    </tr>\r\n    <tr>\r\n      <td style=\"BORDER-RIGHT: windowtext 0.25pt solid; PADDING-RIGHT: 5.4pt; BORDER-TOP: medium none; PADDING-LEFT: 5.4pt; PADDING-BOTTOM: 0cm; BORDER-LEFT: windowtext 0.25pt solid; WIDTH: 70.85pt; PADDING-TOP: 0cm; BORDER-BOTTOM: medium none\" vAlign=\"top\" width=\"94\">\r\n        <p style=\"TEXT-ALIGN: left\" align=\"left\"><font size=\"2\"><span style=\"FONT-SIZE: 11pt\">GENDER</span></font></p>\r\n      </td>\r\n      <td style=\"PADDING-RIGHT: 5.4pt; PADDING-LEFT: 5.4pt; PADDING-BOTTOM: 0cm; WIDTH: 184.3pt; PADDING-TOP: 0cm\" vAlign=\"top\" width=\"246\">\r\n        <p style=\"TEXT-ALIGN: left\" align=\"left\"><font size=\"2\"><span style=\"FONT-SIZE: 11pt\">masculine,\r\n        feminine or neuter</span></font></p>\r\n      </td>\r\n      <td style=\"PADDING-RIGHT: 5.4pt; PADDING-LEFT: 5.4pt; PADDING-BOTTOM: 0cm; WIDTH: 70.85pt; PADDING-TOP: 0cm\" vAlign=\"top\" width=\"94\">\r\n        <p style=\"TEXT-ALIGN: left\" align=\"left\"><i><font size=\"2\"><span style=\"FONT-SIZE: 11pt; FONT-STYLE: italic\">(rod</span></font><span style=\"FONT-STYLE: italic\">)</span></i></p>\r\n      </td>\r\n    </tr>\r\n    <tr>\r\n      <td style=\"BORDER-RIGHT: windowtext 0.25pt solid; PADDING-RIGHT: 5.4pt; BORDER-TOP: medium none; PADDING-LEFT: 5.4pt; PADDING-BOTTOM: 0cm; BORDER-LEFT: windowtext 0.25pt solid; WIDTH: 70.85pt; PADDING-TOP: 0cm; BORDER-BOTTOM: windowtext 0.25pt solid\" vAlign=\"top\" width=\"94\">\r\n        <p style=\"TEXT-ALIGN: left\" align=\"left\"><font size=\"2\"><span style=\"FONT-SIZE: 11pt\">MODEL</span></font></p>\r\n      </td>\r\n      <td style=\"PADDING-RIGHT: 5.4pt; PADDING-LEFT: 5.4pt; PADDING-BOTTOM: 0cm; WIDTH: 184.3pt; PADDING-TOP: 0cm\" vAlign=\"top\" width=\"246\">\r\n        <p style=\"TEXT-ALIGN: left\" align=\"left\"><font size=\"2\"><span style=\"FONT-SIZE: 11pt\">pán,\r\n        mu, čaj, ena, kuře,...</span></font></p>\r\n      </td>\r\n      <td style=\"PADDING-RIGHT: 5.4pt; PADDING-LEFT: 5.4pt; PADDING-BOTTOM: 0cm; WIDTH: 70.85pt; PADDING-TOP: 0cm\" vAlign=\"top\" width=\"94\">\r\n        <p style=\"TEXT-ALIGN: left\" align=\"left\"><i><font size=\"2\"><span style=\"FONT-SIZE: 11pt; FONT-STYLE: italic\">(vzor</span></font><span style=\"FONT-STYLE: italic\">)</span></i></p>\r\n      </td>\r\n    </tr>\r\n  </tbody>\r\n</table>\r\n<p><font size=\"2\"><span style=\"FONT-SIZE: 11pt\"> </span></font></p>\r\n<table style=\"BORDER-COLLAPSE: collapse\" cellSpacing=\"0\" cellPadding=\"0\" border=\"0\">\r\n  <tbody>\r\n    <tr>\r\n      <td style=\"PADDING-RIGHT: 5.4pt; PADDING-LEFT: 5.4pt; PADDING-BOTTOM: 0cm; WIDTH: 154.25pt; PADDING-TOP: 0cm\" vAlign=\"top\" width=\"206\">\r\n        <p style=\"TEXT-ALIGN: left\" align=\"left\"><font size=\"2\"><span style=\"FONT-SIZE: 11pt\">These\r\n        are the names of cases:</span></font></p>\r\n      </td>\r\n      <td style=\"BORDER-RIGHT: medium none; PADDING-RIGHT: 5.4pt; BORDER-TOP: windowtext 0.25pt solid; PADDING-LEFT: 5.4pt; PADDING-BOTTOM: 0cm; BORDER-LEFT: windowtext 0.25pt solid; WIDTH: 80.05pt; PADDING-TOP: 0cm; BORDER-BOTTOM: medium none\" vAlign=\"top\" width=\"107\">\r\n        <p style=\"TEXT-ALIGN: left\" align=\"left\"><b><i><font size=\"2\"><span style=\"FONT-WEIGHT: bold; FONT-SIZE: 11pt; FONT-STYLE: italic\">nominative</span></font></i></b></p>\r\n      </td>\r\n      <td style=\"BORDER-RIGHT: windowtext 0.25pt solid; PADDING-RIGHT: 5.4pt; BORDER-TOP: windowtext 0.25pt solid; PADDING-LEFT: 5.4pt; PADDING-BOTTOM: 0cm; BORDER-LEFT: medium none; WIDTH: 43.7pt; PADDING-TOP: 0cm; BORDER-BOTTOM: medium none\" vAlign=\"top\" width=\"58\">\r\n        <p style=\"TEXT-ALIGN: left\" align=\"left\"><b><font size=\"2\"><span style=\"FONT-WEIGHT: bold; FONT-SIZE: 11pt\">1.pád</span></font></b></p>\r\n      </td>\r\n      <td style=\"PADDING-RIGHT: 5.4pt; PADDING-LEFT: 5.4pt; PADDING-BOTTOM: 0cm; WIDTH: 53pt; PADDING-TOP: 0cm\" vAlign=\"top\" width=\"71\">\r\n        <p style=\"TEXT-ALIGN: left\" align=\"left\"><font size=\"1\"><span style=\"FONT-SIZE: 8pt\">1st\r\n        case</span></font></p>\r\n      </td>\r\n      <td style=\"PADDING-RIGHT: 5.4pt; PADDING-LEFT: 5.4pt; PADDING-BOTTOM: 0cm; WIDTH: 95.15pt; PADDING-TOP: 0cm\" vAlign=\"top\" width=\"127\">\r\n        <p style=\"TEXT-ALIGN: left\" align=\"left\"><i><font size=\"2\"><span style=\"FONT-SIZE: 11pt; FONT-STYLE: italic\">Kdo?\r\n        Co?</span></font></i></p>\r\n      </td>\r\n    </tr>\r\n    <tr>\r\n      <td style=\"PADDING-RIGHT: 5.4pt; PADDING-LEFT: 5.4pt; PADDING-BOTTOM: 0cm; WIDTH: 154.25pt; PADDING-TOP: 0cm\" vAlign=\"top\" width=\"206\">\r\n        <p style=\"TEXT-ALIGN: left\" align=\"left\"> </p>\r\n      </td>\r\n      <td style=\"BORDER-RIGHT: medium none; PADDING-RIGHT: 5.4pt; BORDER-TOP: medium none; PADDING-LEFT: 5.4pt; PADDING-BOTTOM: 0cm; BORDER-LEFT: windowtext 0.25pt solid; WIDTH: 80.05pt; PADDING-TOP: 0cm; BORDER-BOTTOM: medium none\" vAlign=\"top\" width=\"107\">\r\n        <p style=\"TEXT-ALIGN: left\" align=\"left\"><b><i><font size=\"2\"><span style=\"FONT-WEIGHT: bold; FONT-SIZE: 11pt; FONT-STYLE: italic\">genitive</span></font></i></b></p>\r\n      </td>\r\n      <td style=\"BORDER-RIGHT: windowtext 0.25pt solid; PADDING-