(2012, 1, 'HotovoW7 (79-82) Počasí a roční období', '', 58, '', '<H1><FONT color=#330099>Počasí</FONT></H1>\r\n<TABLE cellSpacing=0 cellPadding=0 border=1>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=top width=454>\r\n<P align=center><IMG height=269 src=\"http://www.bohemica.com/tuit/img/textbook/bc-image002.gif\" width=337> </P></TD>\r\n<TD width=492>\r\n<P align=center><IMG height=237 src=\"http://www.bohemica.com/tuit/img/textbook/bc-image004.gif\" width=319> </P>\r\n<P align=center><I>Na jaře a na podzim není moc hezké počasí. Často prí. Občas svítí sluníčko.</I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=454>\r\n<P align=center>&nbsp;</P>\r\n<P align=center><IMG height=219 src=\"http://www.bohemica.com/tuit/img/textbook/bc-image006.gif\" width=289> </P>\r\n<P align=center><I>V létě je moc teplo. Často je přes třicet stupňů. Taky jsou bouřky.</I></P></TD>\r\n<TD vAlign=top width=492>\r\n<P align=center><IMG height=239 src=\"http://www.bohemica.com/tuit/img/textbook/bc-image008.gif\" width=311> </P>\r\n<P align=center><I>V zimě je chladno. Prí nebo sněí. Někdy taky mrzne.</I></P></TD></TR></TBODY></TABLE>\r\n<P>&nbsp;</P>\r\n<H3><FONT color=#330099>Napite, co obvykle děláte v&nbsp;létě a v&nbsp;zimě, na jaře a na podzim!</FONT></H3>\r\n<TABLE cellSpacing=0 cellPadding=0 border=0>\r\n<TBODY>\r\n<TR>\r\n<TD width=331 colSpan=2>\r\n<P align=right><FONT color=#330099>stupňů Fahrenheita</FONT></P></TD>\r\n<TD width=8 rowSpan=3>\r\n<P align=center><I><FONT color=#330099><IMG height=523 src=\"http://www.bohemica.com/tuit/img/textbook/bc-image010.gif\" width=136> </FONT></I></P></TD>\r\n<TD width=8 colSpan=2>\r\n<P><FONT color=#330099>stupňů Celsia</FONT></P></TD></TR>\r\n<TR>\r\n<TD class=\"\" vAlign=top align=middle width=331 bgColor=#b0c4de>\r\n<P><I><FONT color=#330099></FONT></I>&nbsp;</P>\r\n<P><I><FONT color=#330099>Na jaře je teplo</FONT></I></P><FONT color=#330099>[$1,textarea 40,10]</FONT></TD>\r\n<TD class=\"\" vAlign=top align=middle width=8 rowSpan=2>\r\n<P><FONT color=#330099></FONT>&nbsp;</P></TD>\r\n<TD class=\"\" vAlign=top align=middle width=8 rowSpan=2>\r\n<P><FONT color=#330099></FONT>&nbsp;</P></TD>\r\n<TD class=\"\" vAlign=top align=middle width=322 bgColor=#b0c4de>\r\n<P><I><FONT color=#330099></FONT></I>&nbsp;</P>\r\n<P><I><FONT color=#330099>V létě je horko<BR></FONT></I></P>\r\n<P><FONT color=#330099>[$1,textarea 40,10]</FONT></P></TD></TR>\r\n<TR>\r\n<TD class=\"\" vAlign=top align=left width=331 bgColor=#b0c4de>\r\n<P><I><FONT color=#330099></FONT></I>&nbsp;</P>\r\n<P align=center><I><FONT color=#330099>V zimě je zima a mrzne<BR></FONT></I></P>\r\n<P align=center><FONT color=#330099>[$1,textarea 40,10]</FONT></P>\r\n<DIV align=center><FONT color=#330099></FONT></DIV></TD>\r\n<TD class=\"\" vAlign=top align=left width=8 bgColor=#b0c4de>\r\n<P><I><FONT color=#330099></FONT></I>&nbsp;</P>\r\n<P align=center><I><FONT color=#330099>Na podzim je chladno<BR></FONT></I></P>\r\n<P align=center><FONT color=#330099>[$1,textarea 40,10]</FONT></P>\r\n<DIV align=center><FONT color=#330099></FONT></DIV></TD></TR></TBODY></TABLE>\r\n<P><FONT color=#330099></FONT>&nbsp;</P>\r\n<H3><FONT color=#330099>Jaké je počasí? </FONT></H3>\r\n<TABLE cellSpacing=2 cellPadding=2 bgColor=#b0c4de border=0>\r\n<TBODY>\r\n<TR>\r\n<TD width=90>\r\n<P align=center><FONT color=#330099></FONT>&nbsp;</P></TD>\r\n<TD width=104>\r\n<P align=center><FONT color=#330099>co?</FONT></P></TD>\r\n<TD width=270>\r\n<P align=center><FONT color=#330099>dnes</FONT></P></TD>\r\n<TD width=237>\r\n<P align=center><FONT color=#330099>včera</FONT></P></TD></TR>\r\n<TR>\r\n<TD width=90>\r\n<P><FONT color=#330099><IMG height=53 src=\"http://www.bohemica.com/tuit/img/textbook/bc-image012.gif\" width=56> </FONT></P></TD>\r\n<TD width=104>\r\n<P align=center><I><FONT color=#330099>slunce</FONT></I></P></TD>\r\n<TD width=270>\r\n<P align=center><I><FONT color=#330099>Svítí slunce.</FONT></I></P></TD>\r\n<TD width=237>\r\n<P align=center><I><FONT color=#330099>[$1,text 20:Svítilo slunce.]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=90>\r\n<P><FONT color=#330099><IMG height=53 src=\"http://www.bohemica.com/tuit/img/textbook/bc-image014.jpg\" width=63> </FONT></P></TD>\r\n<TD width=104>\r\n<P align=center><I><FONT color=#330099>dé</FONT></I></P></TD>\r\n<TD width=270>\r\n<P align=center><I><FONT color=#330099>Prí.</FONT></I></P></TD>\r\n<TD width=237>\r\n<P align=center><I><FONT color=#330099>[$1,text 20:Prelo.]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=90>\r\n<P><FONT color=#330099><IMG height=53 src=\"http://www.bohemica.com/tuit/img/textbook/bc-image016.jpg\" width=70> </FONT></P></TD>\r\n<TD width=104>\r\n<P align=center><I><FONT color=#330099>sníh</FONT></I></P></TD>\r\n<TD width=270>\r\n<P align=center><I><FONT color=#330099>Sněí.</FONT></I></P></TD>\r\n<TD width=237>\r\n<P align=center><I><FONT color=#330099>[$1,text 20:Sněilo.]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=90>\r\n<P><FONT color=#330099><IMG height=53 src=\"http://www.bohemica.com/tuit/img/textbook/bc-image018.jpg\" width=64> </FONT></P></TD>\r\n<TD width=104>\r\n<P align=center><I><FONT color=#330099>bouřka</FONT></I></P></TD>\r\n<TD width=270>\r\n<P align=center><I><FONT color=#330099>Je bouřka.</FONT></I></P></TD>\r\n<TD width=237>\r\n<P align=center><I><FONT color=#330099>[$1,text 20:Byla bouřka.]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=90>\r\n<P><FONT color=#330099><IMG height=55 src=\"http://www.bohemica.com/tuit/img/textbook/bc-image020.gif\" width=72> </FONT></P></TD>\r\n<TD width=104>\r\n<P align=center><I><FONT color=#330099>mlha</FONT></I></P></TD>\r\n<TD width=270>\r\n<P align=center><I><FONT color=#330099>Je mlha.</FONT></I></P></TD>\r\n<TD width=237>\r\n<P align=center><I><FONT color=#330099>[$1,text 20:Byla mlha.]</FONT></I></P></TD></TR></TBODY></TABLE>\r\n<H3><FONT color=#330099>Jaké bylo počasí?</FONT></H3>\r\n<TABLE cellSpacing=0 cellPadding=0 width=700 bgColor=#b0c4de border=0>\r\n<TBODY>\r\n<TR>\r\n<TD width=241>\r\n<P><I><FONT color=#330099><IMG height=43 src=\"http://www.bohemica.com/tuit/img/textbook/bc-image022.gif\" width=75> </FONT></I></P>\r\n<P align=left><I><FONT color=#330099>Je skoro jasno.</FONT></I></P></TD>\r\n<TD width=222>\r\n<P><I><FONT color=#330099><IMG height=47 src=\"http://www.bohemica.com/tuit/img/textbook/bc-image024.gif\" width=76> </FONT></I></P>\r\n<P align=left><I><FONT color=#330099>Je polojasno.</FONT></I></P></TD>\r\n<TD width=237>\r\n<P><I><FONT color=#330099><IMG height=33 src=\"http://www.bohemica.com/tuit/img/textbook/bc-image026.gif\" width=80> </FONT></I></P>\r\n<P align=left><I><FONT color=#330099>Je zataeno.</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=241>\r\n<P align=left><I><FONT color=#330099>Včera [$1,text 20:bylo skoro jasno.]</FONT></I></P></TD>\r\n<TD width=222>\r\n<P align=left><I><FONT color=#330099>Včera [$1,text 20:bylo polojasno.]</FONT></I></P></TD>\r\n<TD width=237>\r\n<P align=left><I><FONT color=#330099>Včera [$1,text 20:bylo zataeno.]</FONT></I></P></TD></TR></TBODY></TABLE><FONT color=#330099>\r\n<H3><BR></H3></FONT>\r\n<H3><FONT color=#330099>Jaké počasí je v&nbsp;Evropě?</FONT></H3>\r\n<TABLE cellSpacing=2 cellPadding=2 bgColor=#b0c4de border=0>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=center align=left width=85>\r\n<P><FONT color=#330099>védsko</FONT></P></TD>\r\n<TD vAlign=center align=left width=227>\r\n<P><I><FONT color=#330099>[$1,text 30:Sněí. Mínus devět stupňů.]</FONT></I></P></TD>\r\n<TD vAlign=top rowSpan=8><FONT color=#330099>&nbsp; </FONT>\r\n<P align=center><FONT color=#330099><IMG height=600 alt=\"\" src=\"http://www.bohemica.com/tuit/img/textbook/bc-image028.gif\" width=506> </FONT></P><BR></TD></TR>\r\n<TR>\r\n<TD vAlign=center align=left width=85>\r\n<P><FONT color=#330099>Polsko</FONT></P></TD>\r\n<TD vAlign=center align=left width=227>\r\n<P><I><FONT color=#330099>[$1,text 30:Je zataeno. Nula stupňů.]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=center align=left width=85>\r\n<P><FONT color=#330099>Anglie</FONT></P></TD>\r\n<TD vAlign=center align=left width=227>\r\n<P><I><FONT color=#330099>[$1,text 30:Je polojasno. Dva stupně.]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=center align=left width=85>\r\n<P><FONT color=#330099>Francie</FONT></P></TD>\r\n<TD vAlign=center align=left width=227>\r\n<P><I><FONT color=#330099>[$1,text 30:Prí. Pět stupňů.]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=center align=left width=85>\r\n<P><FONT color=#330099>panělsko </FONT></P></TD>\r\n<TD vAlign=center align=left width=227>\r\n<P><I><FONT color=#330099>[$1,text 30:Je skoro jasno. Patnáct stupňů.]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=center align=left width=85>\r\n<P><FONT color=#330099>Itálie</FONT></P></TD>\r\n<TD vAlign=center align=left width=227>\r\n<P><I><FONT color=#330099>[$1,text 30:Svítí slunce. Čtrnáct stupňů.]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=center align=left width=85>\r\n<P><FONT color=#330099>Německo</FONT></P></TD>\r\n<TD vAlign=center align=left width=227>\r\n<P><I><FONT color=#330099>[$1,text 30:Je zataeno. Čtyři stupně.]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=center align=left width=85>\r\n<P><FONT color=#330099>Rumunsko</FONT></P></TD>\r\n<TD vAlign=center align=left width=227>\r\n<P><I><FONT color=#330099>[$1,text 30:Je skoro jasno. est stupňů.]</FONT></I></P></TD></TR></TBODY></TABLE>\r\n<P align=center><FONT color=#330099><BR></FONT></P>\r\n<H3><B><FONT color=#330099>Co dělají Čei.</FONT></B></H3><BR clear=all>\r\n<TABLE style=\"WIDTH: 659px; HEIGHT: 377px\" cellSpacing=2 cellPadding=2 bgColor=#ffffcc border=0>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=top width=222>\r\n<P><FONT color=#330099><IMG height=163 src=\"http://www.bohemica.com/tuit/img/textbook/bc-image029.gif\" width=212> </FONT></P></TD>\r\n<TD vAlign=top width=392 colSpan=2>\r\n<P><I><FONT color=#330099>Téměř kadá česká rodina má chatu, chalupu nebo alespoň malou zahrádku a tak větinu volného času tráví tam. Lidé pracují na zahradě, upravují svoje domy, věnují se svému autu a&nbsp; koníčkům.</FONT></I></P>\r\n<P><I><FONT color=#330099>Čei také rádi cestují. Navtěvují české hrady a zámky, chodí na túry nebo cestují do zahraničí. </FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=614 colSpan=3>\r\n<P><I><FONT color=#330099>Léto nejčastěji tráví na venkově. Chodí do lesa, sbírají houby, jezdí na kole nebo se koupou v&nbsp;rybníce.</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=364 colSpan=2>\r\n<P><I><FONT color=#330099>Od listopadu do února lidé tráví víc času doma. Čtou knihy, dívají se na televizi, poslouchají hudbu, častěji chodí do divadla a na koncerty.</FONT></I></P>\r\n<P><I><FONT color=#330099>V zimě nejraději lyují. Obvykle tráví na horách alespoň týden dovolené. Ti největí fandové ale jezdí lyovat kadý víkend. Někdy je sníh i ve městě, pak děti lyují a sáňkují na kadém kopci.</FONT></I></P></TD>\r\n<TD width=250>\r\n<P align=right><FONT color=#330099><IMG height=144 src=\"http://www.bohemica.com/tuit/img/textbook/bc-image031.gif\" width=242> </FONT></P></TD></TR></TBODY></TABLE>\r\n<H3><FONT color=#330099>Je to pravda?</FONT></H3>\r\n<DIV align=center>\r\n<TABLE cellSpacing=2 cellPadding=2 bgColor=#b0c4de border=0>\r\n<TBODY>\r\n<TR>\r\n<TD width=259>\r\n<P><I><FONT color=#330099>V zimě jezdí na dovolenou na hory.</FONT></I></P></TD>\r\n<TD width=57>\r\n<P align=center><FONT color=#330099>[$1, select:/(ano/ne]</FONT></P></TD>\r\n<TD width=303>\r\n<P><I><FONT color=#330099>Koupou se v&nbsp;rybníce.</FONT></I></P></TD>\r\n<TD width=62>\r\n<P align=center><FONT color=#330099>[$1, select:/(ano/ne]</FONT></P></TD></TR>\r\n<TR>\r\n<TD width=259>\r\n<P><I><FONT color=#330099>Větinu času tráví doma.</FONT></I></P></TD>\r\n<TD width=57>\r\n<P align=center><FONT color=#330099>[$1, select:/ano/(ne]</FONT></P></TD>\r\n<TD width=303>\r\n<P><I><FONT color=#330099>V létě častěji chodí do divadla.</FONT></I></P></TD>\r\n<TD width=62>\r\n<P align=center><FONT color=#330099>[$1, select:/ano/(ne]</FONT></P></TD></TR>\r\n<TR>\r\n<TD width=259>\r\n<P><I><FONT color=#330099>Rádi pracují na zahradě.</FONT></I></P></TD>\r\n<TD width=57>\r\n<P align=center><FONT color=#330099>[$1, select:/(ano/ne]</FONT></P></TD>\r\n<TD width=303>\r\n<P><I><FONT color=#330099>Ve městě není sníh.</FONT></I></P></TD>\r\n<TD width=62>\r\n<P align=center><FONT color=#330099>[$1, select:/(ano/ne]</FONT></P></TD></TR>\r\n<TR>\r\n<TD width=259>\r\n<P><I><FONT color=#330099>Nechodí do lesa na houby.</FONT></I></P></TD>\r\n<TD width=57>\r\n<P align=center><FONT color=#330099>[$1, select:/(ano/ne]</FONT></P></TD>\r\n<TD width=303>\r\n<P><I><FONT color=#330099>V zimě se dívají na televizi a čtou knihy.</FONT></I></P></TD>\r\n<TD width=62>\r\n<P align=center><FONT color=#330099>[$1, select:/(ano/ne]</FONT></P></TD></TR>\r\n<TR>\r\n<TD width=259>\r\n<P><I><FONT color=#330099>V zimě jezdí na kole.</FONT></I></P></TD>\r\n<TD width=57>\r\n<P align=center><FONT color=#330099>[$1, select:/ano/(ne]</FONT></P></TD>\r\n<TD width=303>\r\n<P><I><FONT color=#330099>Taky cestují do zahraničí.</FONT></I></P></TD>\r\n<TD width=62>\r\n<P align=center><FONT color=#330099>[$1, select:/(ano/ne]</FONT></P></TD></TR></TBODY></TABLE><BR></DIV>', 3, NULL),
(2013, 1, 'HotovoW7 (76-78) Aktivity', 'Texty, cvičení, rád+verb', 58, '', '<H1><FONT color=#330099>Rozvrh</FONT></H1>\r\n<H3><FONT color=#330099><BR></FONT></H3>\r\n<H3><FONT color=#330099><IMG height=356 alt=\"\" src=\"http://www.bohemica.com/tuit/img/textbook/bd-image002.gif\" width=652 align=top> </FONT></H3>\r\n<P align=right><FONT color=#330099><BR></FONT></P>\r\n<H3><FONT color=#330099>Odpovězte!</FONT></H3>\r\n<TABLE cellSpacing=2 cellPadding=2 bgColor=#b0c4de border=0>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=bottom width=208>\r\n<P><I><FONT color=#330099>Jak se jmenuje?</FONT></I></P></TD>\r\n<TD vAlign=bottom width=478 colSpan=4>\r\n<P><I><FONT color=#330099>[$1,text 30:Jmenuje se Ale Borovanský.]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=208>\r\n<P><I><FONT color=#330099>Kde bydlí?</FONT></I></P></TD>\r\n<TD vAlign=bottom width=478 colSpan=4>\r\n<P><I><FONT color=#330099>[$1,text 30:Bydlí ve Slaném.]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=208>\r\n<P><I><FONT color=#330099>Kde pracuje?</FONT></I></P></TD>\r\n<TD vAlign=bottom width=478 colSpan=4>\r\n<P><I><FONT color=#330099>[$1,text 30:Pracuje v&nbsp;Komerční bance.]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=208>\r\n<P><I><FONT color=#330099>V kolik hodin je v&nbsp;kanceláři?</FONT></I></P></TD>\r\n<TD vAlign=bottom width=478 colSpan=4>\r\n<P><I><FONT color=#330099>[$1,text 30:V kanceláři je v&nbsp;9 hodin.]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=208>\r\n<P><I><FONT color=#330099>Kdy obědvá?</FONT></I></P></TD>\r\n<TD vAlign=bottom width=478 colSpan=4>\r\n<P><I><FONT color=#330099>[$1,text 30:Obědvá v&nbsp;poledne.]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=208>\r\n<P><I><FONT color=#330099>Co dělá odpoledne?</FONT></I></P></TD>\r\n<TD vAlign=bottom width=478 colSpan=4>\r\n<P><I><FONT color=#330099>[$1,text 30:Odpoledne pracuje.]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=208>\r\n<P><I><FONT color=#3