(2043, 1, 'Hotovo W5 (58/1-2, 59/1) Doplňte správnou koncovku genitívu!', 'Substantíva, adjektíva.', 58, '', '<H3><FONT color=#330099>Doplňte!</FONT></H3>\r\n<TABLE class=\"\" cellSpacing=2 cellPadding=2 bgColor=#b0c4de border=0>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=top width=440>\r\n<P><I><FONT color=#330099>Chodím do [$1,text 12:koly] kadý den.</FONT></I></P></TD>\r\n<TD vAlign=top width=170>\r\n<P><FONT color=#330099>(kola)</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=440>\r\n<P><I><FONT color=#330099>Jdu do [$1,text 12:kina] bez [$1,text 12:kamaráda].</FONT></I></P></TD>\r\n<TD vAlign=top width=170>\r\n<P><FONT color=#330099>(kino)(kamarád)</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=440>\r\n<P><I><FONT color=#330099>Chci kávu bez [$1,text 12:cukru].</FONT></I></P></TD>\r\n<TD vAlign=top width=170>\r\n<P><FONT color=#330099>(cukr)</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=440>\r\n<P><I><FONT color=#330099>Jsi z [$1,text 12:Jihlavy]?</FONT></I></P></TD>\r\n<TD vAlign=top width=170>\r\n<P><FONT color=#330099>(Jihlava)</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=440>\r\n<P><I><FONT color=#330099>V sobotu jedeme do [$1,text 12:Plzně].</FONT></I></P></TD>\r\n<TD vAlign=top width=170>\r\n<P><FONT color=#330099>(Plzeň)</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=440>\r\n<P><I><FONT color=#330099>Kino je vedle [$1,text 12:parku].</FONT></I></P></TD>\r\n<TD vAlign=top width=170>\r\n<P><FONT color=#330099>(park)</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=440>\r\n<P><I><FONT color=#330099>Dnes večer jdeme do [$1,text 12:restaurace.]</FONT></I></P></TD>\r\n<TD vAlign=top width=170>\r\n<P><FONT color=#330099>(restaurace)</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=440>\r\n<P><I><FONT color=#330099>Petr je u [$1,text 12:Alee].</FONT></I></P></TD>\r\n<TD vAlign=top width=170>\r\n<P><FONT color=#330099>(Ale)</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=440>\r\n<P><I><FONT color=#330099>Renata je vedle [$1,text 12:Jany].</FONT></I></P></TD>\r\n<TD vAlign=top width=170>\r\n<P><FONT color=#330099>(Jana)</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=440>\r\n<P><I><FONT color=#330099>Čekám na Kateřinu u [$1,text 12:Tesca].</FONT></I></P></TD>\r\n<TD vAlign=top width=170>\r\n<P><FONT color=#330099>(Tesco)</FONT></P></TD></TR></TBODY></TABLE>\r\n<P><FONT color=#330099></FONT>&nbsp;</P>\r\n<H3><FONT color=#330099>Doplňte!</FONT></H3>\r\n<TABLE class=\"\" cellSpacing=2 cellPadding=2 bgColor=#b0c4de border=0>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=bottom width=424>\r\n<P align=left><I><FONT color=#330099>Jana je z [$1,text 12:malého města].</FONT></I></P></TD>\r\n<TD vAlign=top width=199>\r\n<P align=center><FONT color=#330099>malé město</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=424>\r\n<P align=left><I><FONT color=#330099>Dám si trochu [$1,text 15:ovocného čaje].</FONT></I></P></TD>\r\n<TD vAlign=top width=199>\r\n<P align=center><FONT color=#330099>ovocný čaj</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=424>\r\n<P align=left><I><FONT color=#330099>Kdy jede do [$1,text 12:České Lípy]?</FONT></I></P></TD>\r\n<TD vAlign=top width=199>\r\n<P align=center><FONT color=#330099>Česká Lípa</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=424>\r\n<P align=left><I><FONT color=#330099>Jedu z [$1,text 12:Českého Krumlova] do [$1,text 12:Prahy].</FONT></I></P></TD>\r\n<TD vAlign=top width=199>\r\n<P align=center><FONT color=#330099>Český Krumlov, Praha</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=424>\r\n<P align=left><I><FONT color=#330099>Prosím kilo [$1,text 12:uzeného masa].</FONT></I></P></TD>\r\n<TD vAlign=top width=199>\r\n<P align=center><FONT color=#330099>uzené maso</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=424>\r\n<P align=left><I><FONT color=#330099>Chce kousek [$1,text 15:eidamského sýra].</FONT></I></P></TD>\r\n<TD vAlign=top width=199>\r\n<P align=center><FONT color=#330099>eidamský sýr</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=424>\r\n<P align=left><I><FONT color=#330099>Banka je vedle [$1,text 15:moderního hotelu].</FONT></I></P></TD>\r\n<TD vAlign=top width=199>\r\n<P align=center><FONT color=#330099>moderní hotel</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=424>\r\n<P align=left><I><FONT color=#330099>Co je [$1,text 12:nového]?</FONT></I></P></TD>\r\n<TD vAlign=top width=199>\r\n<P align=center><FONT color=#330099>nový</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=424>\r\n<P align=left><I><FONT color=#330099>Bydlí blízko [$1,text 12:Prahy].</FONT></I></P></TD>\r\n<TD vAlign=top width=199>\r\n<P align=center><FONT color=#330099>Praha</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=424>\r\n<P align=left><I><FONT color=#330099>Chcete jet do [$1,text 12:Kutné Hory]?</FONT></I></P></TD>\r\n<TD vAlign=top width=199>\r\n<P align=center><FONT color=#330099>Kutná Hora</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=424>\r\n<P align=left><I><FONT color=#330099>Dnes jdeme do [$1,text 12:kina] bez [$1,text 12:Tomáe].</FONT></I></P></TD>\r\n<TD vAlign=top width=199>\r\n<P align=center><FONT color=#330099>&nbsp;kino,Tomá</FONT></P></TD></TR></TBODY></TABLE>\r\n<H3><FONT color=#330099><BR></FONT></H3>\r\n<H3><FONT color=#330099>Doplňte!&nbsp; </FONT></H3>\r\n<TABLE class=\"\" cellSpacing=2 cellPadding=2 bgColor=#b0c4de border=0>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=top width=424>\r\n<P><I><FONT color=#330099>Mám tu knihu od kamaráda [$1,text 12:Jany].</FONT></I></P></TD>\r\n<TD width=199>\r\n<P align=center><FONT color=#330099>Jana</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=424>\r\n<P><I><FONT color=#330099>Vedle knihy [$1,text 12:Michala] je káva.</FONT></I></P></TD>\r\n<TD width=199>\r\n<P align=center><FONT color=#330099>Michal</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=424>\r\n<P><I><FONT color=#330099>Jsme u bratra [$1,text 12:Dominika].</FONT></I></P></TD>\r\n<TD width=199>\r\n<P align=center><FONT color=#330099