(2048, 1, 'Hotovo W6 (67) Kolik je Vam let', 'Dialig,tabulka a cvičení', 58, '', '<H1><FONT color=#330099>Kolik je Vám let?</FONT></H1>\r\n<TABLE cellSpacing=0 cellPadding=0 width=876 border=1>\r\n<TBODY>\r\n<TR>\r\n<TD width=450>\r\n<P align=center><IMG height=364 src=\"http://www.bohemica.com/tuit/img/textbook/ax-image003.gif\" width=426> </P></TD>\r\n<TD vAlign=top width=426>\r\n<P><IMG height=337 src=\"http://www.bohemica.com/tuit/img/textbook/ax-image005.gif\" width=436> </P></TD></TR></TBODY></TABLE>\r\n<H3><FONT color=#330099>Odpovězte!</FONT></H3>\r\n<TABLE class=\"\" cellSpacing=2 cellPadding=2 bgColor=#b0c4de border=0>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=bottom width=250>\r\n<P><I><FONT color=#330099>Kolik mají dětí?</FONT></I></P></TD>\r\n<TD vAlign=bottom width=364>\r\n<P><FONT color=#330099>&nbsp;[$1,text 40]</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=250>\r\n<P><I><FONT color=#330099>Kolik let je Kláře?</FONT></I></P></TD>\r\n<TD vAlign=bottom width=364>\r\n<P><FONT color=#330099>&nbsp;[$1,text 40]</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=250>\r\n<P><I><FONT color=#330099>Kolik let je Anně?</FONT></I></P></TD>\r\n<TD vAlign=bottom width=364>\r\n<P><FONT color=#330099>&nbsp;[$1,text 40]</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=250>\r\n<P><I><FONT color=#330099>Jak se jmenuje jejich syn?</FONT></I></P></TD>\r\n<TD vAlign=bottom width=364>\r\n<P><FONT color=#330099>&nbsp;[$1,text 40]</FONT></P></TD></TR></TBODY></TABLE>\r\n<P><FONT color=#330099></FONT>&nbsp;</P>\r\n<P><FONT color=#330099>\r\n<TABLE class=\"\" style=\"BORDER-RIGHT: #c0c0c0 1px dotted; BORDER-TOP: #c0c0c0 1px dotted; BORDER-LEFT: #c0c0c0 1px dotted; WIDTH: 371px; BORDER-BOTTOM: #c0c0c0 1px dotted; HEIGHT: 177px\" cellSpacing=2 cellPadding=2 width=371 bgColor=#ffcc00 border=0>\r\n<TBODY>\r\n<TR>\r\n<TD class=\"\" vAlign=center align=left width=20 height=15>&nbsp;<EM><FONT color=#330099>(já)</FONT></EM></TD>\r\n<TD class=\"\" vAlign=center align=left width=150>&nbsp;<FONT color=#330099><STRONG>Je </STRONG><EM>mi </EM><STRONG>dvacet let.</STRONG></FONT></TD>\r\n<TD><FONT color=#330099>&nbsp;</FONT></TD></TR>\r\n<TR>\r\n<TD width=20><FONT color=#330099><EM>(ty)</EM>&nbsp;</FONT></TD>\r\n<TD class=\"\" vAlign=center align=left width=150>&nbsp;<FONT color=#330099><STRONG>Kolik je </STRONG><EM>Ti </EM><STRONG>let?</STRONG></FONT></TD>\r\n<TD><FONT color=#330099>&nbsp;</FONT></TD></TR>\r\n<TR>\r\n<TD width=20><FONT color=#330099><EM>(on)</EM>&nbsp;</FONT></TD>\r\n<TD width=150>&nbsp;<FONT color=#330099><STRONG>Je&nbsp;</STRONG><EM>mu&nbsp;&nbsp;</EM><STRONG>dvacet let?</STRONG></FONT></TD>\r\n<TD><FONT color=#330099>&nbsp;</FONT></TD></TR>\r\n<TR>\r\n<TD width=20><FONT color=#330099>&nbsp;<EM>(ona)</EM></FONT></TD>\r\n<TD width=150>&nbsp;<FONT color=#330099><STRONG>Je </STRONG><EM>jí </EM><STRONG>dvacet let.</STRONG></FONT></TD>\r\n<TD><FONT color=#330099>&nbsp;</FONT><FONT color=#ff6633><EM>Vlozit obraz.telefonu.</EM></FONT></TD></TR>\r\n<TR>\r\n<TD width=20><FONT color=#330099>&nbsp;<EM>(vy)</EM></FONT></TD>\r\n<TD width=150>&nbsp;<FONT color=#330099><STRONG>Kolik je&nbsp;</STRONG><EM>Vám </EM><STRONG>let?</STRONG></FONT></TD>\r\n<TD><FONT color=#330099>&nbsp;</FONT></TD></TR>\r\n<TR>\r\n<TD width=20><FONT color=#330099>&nbsp;<EM>(oni)</EM></FONT></TD>\r\n<TD width=150>&nbsp;<FONT color=#330099><STRONG>Je</STRONG><EM>&nbsp; jim </EM><STRONG>dvacet let.</STRONG></FONT></TD>\r\n<TD><FONT color=#330099>&nbsp;</FONT></TD></TR></TBODY></TABLE></FONT></P>\r\n<H3><FONT color=#330099>Odpovězte a v odpovědi pouijte osobní zájmeno!</FONT></H3>\r\n<TABLE class=\"\" cellSpacing=2 cellPadding=2 bgColor=#b0c4de border=0>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=bottom width=181>\r\n<P><I><FONT color=#330099>Kolik let je kamarádovi ?</FONT></I></P></TD>\r\n<TD vAlign=bottom width=433>\r\n<P><FONT color=#330099>&nbsp;[$1,text 40]</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=181>\r\n<P><I><FONT color=#330099>Kolik let je tatínkovi?</FONT></I></P></TD>\r\n<TD vAlign=bottom width=433>\r\n<P><FONT color=#330099>&nbsp;[$1,text 40]</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=181>\r\n<P><I><FONT color=#330099>Kolik let je bratrovi?</FONT></I></P></TD>\r\n<TD vAlign=bottom width=433>\r\n<P><FONT color=#330099>&nbsp;[$1,text 40]</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=181>\r\n<P><I><FONT color=#330099>Kolik let je dědečkovi?</FONT></I></P></TD>\r\n<TD vAlign=bottom width=433>\r\n<P><FONT color=#330099>&nbsp;[$1,text 40]</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=181>\r\n<P><I><FONT color=#330099>Kolik let je mamince?</FONT></I></P></TD>\r\n<TD vAlign=bottom width=433>\r\n<P><FONT color=#330099>&nbsp;[$1,text 40]</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=181>\r\n<P><I><FONT color=#330099>Kolik let je babičce?</FONT></I></P></TD>\r\n<TD vAlign=bottom width=433>\r\n<P><FONT color=#330099>&nbsp;[$1,text 40]</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=181>\r\n<P><I><FONT color=#330099>Kolik let je sestře?</FONT></I></P></TD>\r\n<TD vAlign=bottom width=433>\r\n<P><FONT color=#330099>&nbsp;[$1,text 40]</FONT></P></TD></TR></TBODY></TABLE>', 3, NULL),
(2049, 1, 'Hotovo W6 (68) Moje rodina', 'Taxt  a cvičení DOPLNIT OBRAZEK', 58, '', '<H1><FONT color=#330099>Moje rodina</FONT></H1>\r\n<H3 align=left><FONT color=#330099>Doplňte do textu následující slova: <EM>má(2x),je(2x),protoe,můj,moje(3x),já,my,nai,být,chce.&nbsp;</EM></FONT></H3>\r\n<P>\r\n<TABLE class=\"\" style=\"BORDER-RIGHT: #c0c0c0 1px dotted; BORDER-TOP: #c0c0c0 1px dotted; BORDER-LEFT: #c0c0c0 1px dotted; WIDTH: 526px; BORDER-BOTTOM: #c0c0c0 1px dotted; HEIGHT: 164px\" cellSpacing=2 cellPadding=2 width=526 bgColor=#ffffcc border=1>\r\n<TBODY>\r\n<TR>\r\n<TD>&nbsp;<FONT color=#ff6633>VLOZIT SEM OBRAZEK RODINY</FONT></TD>\r\n<TD>&nbsp; \r\n<P><I><FONT color=#330099>Jano, tady na fotografii je [$1,text 12:moje] rodina. Uprostřed je babička Věra a vedle jsem [$1,text 12:já]. Vzadu je tatínek a maminka. [$1,text 12:Můj] tatínek je doktor a [$1,text 12:moje] maminka je učitelka. Vedle maminky [$1,text 12:je] její sestra Alena. Její manel tady není, [$1,text 12:protoe] je nemocný. Teta Alena [$1,text 12:má] dvojčata Jarku a Ivu. [$1,text 12:Je] jim jedenáct let. A vepředu jsme [$1,text 12:my] děti.Tohle je [$1,text 12:moje] sestra Jana.Vedle jsou [$1,text 12:nai] bratři Mirek a Pavel. Pavlovi je 20 let a chce [$1,text 12:být] právník. Mirek [$1,text 12:má] rád zvířata a [$1,text 12:chce] být veterinář.</FONT></I></P></TD></TR></TBODY></TABLE></P>\r\n<H3><FONT color=#330099>Odpovězte na otázky!</FONT></H3>\r\n<TABLE class=\"\" cellSpacing=2 cellPadding=2 bgColor=#b0c4de border=0>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=bottom width=246>\r\n<P><I><FONT color=#330099>Co dělá její tatínek?</FONT></I></P></TD>\r\n<TD vAlign=bottom width=672>\r\n<P><FONT color=#330099>&nbsp;[$1,text 40]</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=246>\r\n<P><I><FONT color=#330099>Jak se jmenuje sestra maminky?</FONT></I></P></TD>\r\n<TD vAlign=bottom width=672>\r\n<P><FONT color=#330099>&nbsp;[$1,text 40]</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=246>\r\n<P><I><FONT color=#330099>Kolik let je dvojčatům?</FONT></I></P></TD>\r\n<TD vAlign=bottom width=672>\r\n<P><FONT color=#330099>&nbsp;[$1,text 40]</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=246>\r\n<P><I><FONT color=#330099>Kolik bratrů&nbsp; má?</FONT></I></P></TD>\r\n<TD vAlign=bottom width=672>\r\n<P><FONT color=#330099>&nbsp;[$1,text 40]</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=246>\r\n<P><I><FONT color=#330099>Kdo je svobodný?</FONT></I></P></TD>\r\n<TD vAlign=bottom width=672>\r\n<P><FONT color=#330099>&nbsp;[$1,text 40]</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=246>\r\n<P><I><FONT color=#330099>Proč chce být Mirek veterinář?</FONT></I></P></TD>\r\n<TD vAlign=bottom width=672>\r\n<P><FONT color=#330099>&nbsp;[$1,text 40]</FONT></P></TD></TR></TBODY></TABLE>\r\n<P><FONT color=#330099></FONT>&nbsp;</P>', 3, NULL),
(2050, 1, 'U36/5  Napite něco o své rodině!', '', 58, '', '<H3><FONT color=#330099>Napite něco o své rodině!</FONT></H3>\r\n<P>\r\n<TABLE class=\"\" style=\"WIDTH: 560px; HEIGHT: 98px\" cellSpacing=2 cellPadding=2 width=560 bgColor=#b0c4de border=0>\r\n<TBODY>\r\n<TR>\r\n<TD>&nbsp;<IMG height=79 src=\"http://www.bohemica.com/tuit/img/textbook/ax-image012.gif\" width=60>&nbsp;&nbsp; <FONT color=#330099>[$1,textarea 60,10]</FONT></TD>\r\n<TD>&nbsp;</TD></TR></TBODY></TABLE></P>', 3, NULL),
(2051, 1, 'U37/10  Doplňte prepozice!', 'do, k, na, u, vedle. blízko, bez, v', 58, '', '<H3><FONT color=#330099>Doplňte prepozice!</FONT></H3>\r\n<P><FONT color=#330099>\r\n<TABLE class=\"\" cellSpacing=2 cellPadding=2 width=\"100%\" align=left bgColor=#b0c4de border=0>\r\n<TBODY>\r\n<TR>\r\n<TD>&nbsp;<I><FONT color=#330099>Ráno chodím [$1,text 5:do] koly. Odpoledne chodím plavat [$1,text 5:do] bazénu. Večer chodím [$1,text 5:do] kina nebo [$1,text 5:do] divadla. Občas jdu [$1,text 5:ke] kamarádce Aleně. Čekáme [$1,text 5:na] Janu [$1,text 5:na] nádraí. Co si dáte [$1,text 5:k&nbsp;] večeři? Michal a David jsou [$1,text 5:z]&nbsp;Českého Krumlova. Dnes večer jdeme [$1,text 5:do] restaurace. Pota je [$1,text 5:u, vedle, blízko] hotelu. Prosím kávu [$1,text 5:bez] mléka. Jezdíte [$1,text 5:na] výlety? [$1,text 5:V]&nbsp;kolik hodin je četina? Musíte jít rovně [$1,text 5:na] náměstí. [$1,text 5:V]&nbsp;pátek jedeme [$1,text 5:do] Budapeti. Dneska večer jdeme [$1,text 5:na] diskotéku. Renata je [$1,text 5:u] Pavla. Jirka jde [$1,text 5:k]&nbsp;Pavle. Jdu [$1,text 5:do] hospody [$1,text 5:u, vedle, blízko] divadla. Ráno nejdeme [$1,text 5:na] výstavu.</FONT></I></TD></TR></TBODY></TABLE></FONT></P>', 3, NULL),
(2052, 1, 'U17/1', '', 58, '', '<H3 align=left><FONT color=#330099>Poslouchejte dialog!</FONT></H3>\r\n<TABLE class=\"\" cellSpacing=2 cellPadding=2 bgColor=#ffffcc border=0>\r\n<TBODY>\r\n<TR>\r\n<TD width=80>\r\n<P align=left><FONT color=#330099>Prodavač:</FONT></P></TD>\r\n<TD width=534>\r\n<P align=left><I><FONT color=#330099>Dobrý den! Přejete si, prosím?</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=80>\r\n<P align=left><I><FONT color=#330099>Zákazník:</FONT></I></P></TD>\r\n<TD width=534>\r\n<P align=left><I><FONT color=#330099>Dobrý den! Čtyři koláčky,prosím.</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=80>\r\n<P align=left><FONT color=#330099>Prodavač:</FONT></P></TD>\r\n<TD width=534>\r\n<P align=left><I><FONT color=#330099>Jetě něco?</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=80>\r\n<P align=left><I><FONT color=#330099>Zákazník:</FONT></I></P></TD>\r\n<TD width=534>\r\n<P align=left><I><FONT color=#330099>Ano, dvě koly a salát.</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=80>\r\n<P align=left><FONT color=#330099>Prodavač:</FONT></P></TD>\r\n<TD width=534>\r\n<P align=left><I><FONT color=#330099>Jaký?</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=80>\r\n<P align=left><I><FONT color=#330099>Zákazník:</FONT></I></P></TD>\r\n<TD width=534>\r\n<P align=left><I><FONT color=#330099>Kuřecí.</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=80>\r\n<P align=left><FONT color=#330099>Prodavač:</FONT></P></TD>\r\n<TD width=534>\r\n<P align=left><I><FONT color=#330099>A kolik?</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=80>\r\n<P align=left><I><FONT color=#330099>Zákazník:</FONT></I></P></TD>\r\n<TD width=534>\r\n<P align=left><I><FONT color=#330099>Dvacet deka</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=80>\r\n<P align=left><FONT color=#330099>Prodavač:</FONT></P></TD>\r\n<TD width=534>\r\n<P align=left><I><FONT color=#330099>Je to vechno?</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=80>\r\n<P align=left><I><FONT color=#330099>Zákazník:</FONT></I></P></TD>\r\n<TD width=534>\r\n<P align=left><I><FONT color=#330099>Ne. Jetě prosím rohlíky.</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=80>\r\n<P align=left><FONT color=#330099>Prodavač:</FONT></P></TD>\r\n<TD width=534>\r\n<P align=left><I><FONT color=#330099>Kolik, prosím?</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=80>\r\n<P align=left><I><FONT color=#330099>Zákazník:</FONT></I></P></TD>\r\n<TD width=534>\r\n<P align=left><I><FONT color=#330099>Pět. Máte neperlivou vodu ?</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=80>\r\n<P align=left><FONT color=#330099>Prodavač:</FONT></P></TD>\r\n<TD width=534>\r\n<P align=left><I><FONT color=#330099>Ne, nemáme, ale máme minerálku.</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=80>\r\n<P align=left><I><FONT color=#330099>Zákazník:</FONT></I></P></TD>\r\n<TD width=534>\r\n<P align=left><I><FONT color=#330099>Kolik stojí?</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=80>\r\n<P align=left><FONT color=#330099>Prodavač:</FONT></P></TD>\r\n<TD width=534>\r\n<P align=left><I><FONT color=#330099>Čtrnáct padesát</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=80>\r\n<P align=left><I><FONT color=#330099>Zákazník:</FONT></I></P></TD>\r\n<TD width=534>\r\n<P align=left><I><FONT color=#330099>Jednu, prosím. A je to vechno.</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=80>\r\n<P align=left><FONT color=#330099>Prodavač:</FONT></P></TD>\r\n<TD width=534>\r\n<P align=left><I><FONT color=#330099>158 korun.</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=80>\r\n<P align=left><I><FONT color=#330099>Zákazník:</FONT></I></P></TD>\r\n<TD width=534>\r\n<P align=left><I><FONT color=#330099>Prosím. (1 000 Kč)</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=80>\r\n<P align=left><FONT color=#330099>Prodavač:</FONT></P></TD>\r\n<TD width=534>\r\n<P align=left><I><FONT color=#330099>Nemáte drobné?</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=80>\r\n<P align=left><I><FONT color=#330099>Zákazník:</FONT></I></P></TD>\r\n<TD width=534>\r\n<P align=left><I><FONT color=#330099>Bohuel ne.</FONT></I></P></TD></TR></TBODY></TABLE>\r\n<P><FONT color=#330099></FONT>&nbsp;</P>', 3, NULL),
