(2085, 1, 'U4/1', '', 58, '', '<H1><FONT color=#330099>Pan, paní</FONT></H1>\r\n<TABLE cellSpacing=0 cellPadding=2 width=\"99%\" border=1>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=top align=middle width=\"50%\" height=72><FONT color=#330099>To je pan Novák.<BR>Je inenýr.<BR>Pan Novák je Čech.<BR></FONT></TD>\r\n<TD vAlign=top align=middle width=\"50%\" height=72><FONT color=#330099>To je paní Nováková.<BR>Je učitelka.<BR>Paní Nováková je Čeka.<BR></FONT></TD></TR>\r\n<TR>\r\n<TD vAlign=top align=middle width=\"50%\" height=203><FONT color=#330099><IMG height=195 alt=\"\" src=\"http://www.bohemica.com/tuit/img/textbook/ad-novak.jpg\" width=199 border=0> </FONT></TD>\r\n<TD vAlign=top align=middle width=\"50%\" height=203><FONT color=#330099><IMG height=198 alt=\"\" src=\"http://www.bohemica.com/tuit/img/textbook/ad-novakova.jpg\" width=202 border=0> </FONT></TD></TR></TBODY></TABLE>', 3, NULL),
(2086, 1, 'U4/2', '', 58, '', '<FONT color=#330099 size=4><STRONG>Doplňte!</STRONG></FONT>\r\n<TABLE cellSpacing=0 cellPadding=2 width=\"94%\" bgColor=#b0c4de border=0>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=top align=middle width=\"50%\" height=128><FONT color=#330099><IMG height=124 alt=\"\" src=\"http://www.bohemica.com/tuit/img/textbook/ad-brown.jpg\" width=126 border=0> </FONT></TD>\r\n<TD vAlign=top align=middle width=\"50%\" height=128><FONT color=#330099><IMG height=117 alt=\"\" src=\"http://www.bohemica.com/tuit/img/textbook/ad-brownova.jpg\" width=120 border=0> </FONT></TD></TR>\r\n<TR>\r\n<TD vAlign=top align=middle width=\"50%\" height=124><BR><FONT color=#330099>To je [$1,text 15].<BR><FONT size=3><SMALL>[$1,text 15] <FONT size=3>profesor.</FONT></SMALL><BR>[$1,text 12] Američan. </FONT></FONT></TD>\r\n<TD vAlign=top align=middle width=\"50%\" height=124><BR><FONT color=#330099>To je[$1,text 12] Brownová.<BR>[$1,text 15] doktorka.<BR>Je [$1,text 12] .</FONT></TD></TR></TBODY></TABLE>\r\n<H3><STRONG><BR></STRONG></H3>', 3, NULL),
