(2138, 1, 'U20/2', '', 58, '', '<FONT size=4><STRONG><FONT color=#330099>&nbsp;</FONT><FONT color=#330099>Doplňte rozhovor!</FONT></STRONG></FONT>\r\n<TABLE style=\"BORDER-RIGHT: #c0c0c0 1px dotted; BORDER-TOP: #c0c0c0 1px dotted; BORDER-LEFT: #c0c0c0 1px dotted; WIDTH: 470px; BORDER-BOTTOM: #c0c0c0 1px dotted; HEIGHT: 335px\" cellSpacing=2 cellPadding=2 width=470 bgColor=#b0c4de border=0>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=top width=200><FONT color=#330099><B>A:</B><I>Co si dáte k&nbsp;pití? </I><BR>&nbsp; <BR><B>B:</B> <I>Dám si </I>[$1,text 30]<I> .</I> </FONT>\r\n<P><FONT color=#330099><B>A:</B><I> A k&nbsp;jídlu?</I></FONT></P>\r\n<P><FONT color=#330099><B>B:</B><I> Dám si </I>[$1,text 30]<I> a zaplatím.</I></FONT></P>\r\n<P><FONT color=#330099><B>A:</B><I> Ano, 84 korun.</I></FONT></P>\r\n<P><FONT color=#330099><B>B:</B><I> Prosím. (90,-) To je </I>[$1,text 30]<I>.</I></FONT></P>\r\n<P><FONT color=#330099><B>A:</B><I> Děkuju.</I></FONT></P>\r\n<P><FONT color=#330099><B>A+B: </B>[$1,text 30]<I>.</I></FONT></P></TD>\r\n<TD vAlign=center>\r\n<H1><FONT color=#330099><IMG height=250 alt=\"\" src=\"http://www.bohemica.com/tuit/img/textbook/am-image015.gif\" width=225> </FONT></H1></TD></TR></TBODY></TABLE>', 3, NULL),
(2139, 1, 'U20/3', '', 58, '', '<H3><FONT color=#330099>Co řeknete?</FONT></H3>\r\n<P>\r\n<TABLE id=table1 cellSpacing=2 cellPadding=2 bgColor=#b0c4de border=0>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=top align=middle><FONT color=#330099>[$1,text 30]<BR>&nbsp;</FONT></TD>\r\n<TD vAlign=top align=middle><FONT color=#330099>[$1,text 30]<BR>&nbsp;</FONT></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=299>\r\n<P align=center><FONT color=#330099><IMG height=225 src=\"http://www.bohemica.com/tuit/img/textbook/am-image016.gif\" width=281></FONT></P></TD>\r\n<TD vAlign=top width=299>\r\n<P align=center><FONT color=#330099><IMG height=227 src=\"http://www.bohemica.com/tuit/img/textbook/am-image017.gif\" width=275></FONT></P></TD></TR></TBODY></TABLE></P>\r\n<P><FONT color=#330099 size=4><STRONG>Co řekne číník?</STRONG></FONT></P>\r\n<P><FONT color=#330099>\r\n<TABLE id=table2 cellSpacing=2 cellPadding=2 bgColor=#b0c4de border=0>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=top align=middle><FONT color=#330099>[$1,text 30]<BR>&nbsp;</FONT></TD>\r\n<TD vAlign=top align=middle><FONT color=#330099>[$1,text 30]<BR>&nbsp;</FONT></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=299><FONT color=#330099>\r\n<P align=center><IMG height=244 src=\"http://www.bohemica.com/tuit/img/textbook/am-image021.gif\" width=292></FONT></P></TD>\r\n<TD width=299>\r\n<P align=center><FONT color=#330099><IMG height=241 src=\"http://www.bohemica.com/tuit/img/textbook/am-image022.gif\" width=305></FONT></P></TD></TR></TBODY></TABLE><BR></FONT></P>', 3, NULL),
(2140, 1, 'U20/4', '', 58, '', '<H3><FONT color=#330099>Napite ve správném pořadí!</FONT></H3>\r\n<P><I><FONT color=#330099>Máte řecký salát? A co si dáte vy? Prosím dva dusy a jedno pivo. Dobrý den. Jídelní lístek, prosím. Jetě něco? Ne. To je vechno. Děkujeme Ano. Chcete velký nebo malý? Co si dáte k&nbsp;jídlu? Velký, prosím. Dobrý den. Co si dáte? Maďarský gulá a hranolky.</FONT></I></P>\r\n<TABLE cellSpacing=2 cellPadding=2 width=606 bgColor=#b0c4de border=0>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=bottom width=65>\r\n<P><FONT color=#330099>A+B+C:</FONT></P></TD>\r\n<TD vAlign=bottom width=541>\r\n<P><I><FONT color=#330099>[$1,text 40:Dobrý den. Jídelní lístek, prosím.]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=65>\r\n<P><FONT color=#330099>Číník:</FONT></P></TD>\r\n<TD vAlign=bottom width=541>\r\n<P><I><FONT color=#330099>[$1,text 40:Dobrý den. Co si dáte?]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=65>\r\n<P><FONT color=#330099>A:</FONT></P></TD>\r\n<TD vAlign=bottom width=541>\r\n<P><I><FONT color=#330099>[$1,text 40:Prosím dva dusy a jedno pivo.]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=65>\r\n<P><FONT color=#330099>Číník:</FONT></P></TD>\r\n<TD vAlign=bottom width=541>\r\n<P><I><FONT color=#330099>[$1,text 40:Co si dáte k&nbsp;jídlu?]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=65>\r\n<P><FONT color=#330099>C:</FONT></P></TD>\r\n<TD vAlign=bottom width=541>\r\n<P><I><FONT color=#330099>[$1,text 40:Maďarský gulá a hranolky.]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=65>\r\n<P><FONT color=#330099>B:</FONT></P></TD>\r\n<TD vAlign=bottom width=541>\r\n<P><I><FONT color=#330099>[$1,text 40:Máte řecký salát?]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=65>\r\n<P><FONT color=#330099>Číník:</FONT></P></TD>\r\n<TD vAlign=bottom width=541>\r\n<P><I><FONT color=#330099>[$1,text 40:Ano. Chcete velký nebo malý?]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=65>\r\n<P><FONT color=#330099>B:</FONT></P></TD>\r\n<TD vAlign=bottom width=541>\r\n<P><I><FONT color=#330099>[$1,text 40:Velký, prosím.]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=65>\r\n<P><FONT color=#330099>Číník:</FONT></P></TD>\r\n<TD vAlign=bottom width=541>\r\n<P><I><FONT color=#330099>[$1,text 40:A co si dáte vy?]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=65>\r\n<P><FONT color=#330099>A:</FONT></P></TD>\r\n<TD vAlign=bottom width=541>\r\n<P><I><FONT color=#330099>[$1,text 40:pagety se sýrem.]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=65>\r\n<P><FONT color=#330099>Číník:</FONT></P></TD>\r\n<TD vAlign=bottom width=541>\r\n<P><I><FONT color=#330099>[$1,text 40:Jetě něco?]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=65>\r\n<P><FONT color=#330099>A:</FONT></P></TD>\r\n<TD vAlign=bottom width=541>\r\n<P><I><FONT color=#330099>[$1,text 40:Ne. To je vechno. Děkujeme.]</FONT></I></P></TD></TR></TBODY></TABLE>', 3, NULL),
(2141, 1, 'U20/5', '', 58, '', '<H3><FONT color=#330099>Naučte se česká jídla!</FONT></H3>\r\n<TABLE cellSpacing=2 cellPadding=2 bgColor=#ffffcc border=0>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=top width=604>\r\n<P><B><FONT color=#330099>Jídelní lístek&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Menu</FONT></B></P>\r\n<P><B><FONT color=#330099>Polévky&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Soups</FONT></B></P>\r\n<P><FONT color=#330099>Kuřecí polévka.......................................... 27.40........................................... Chicken Soup</FONT></P>\r\n<P><FONT color=#330099>Hovězí vývar............................................. 21.20................................................. Beef broth</FONT></P>\r\n<P><FONT color=#330099>Bramborová polévka................................. 29.90.............................................. Potato Soup</FONT></P>\r\n<P><B><FONT color=#330099>Hotová jídla&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Main courses</FONT></B></P>\r\n<P><FONT color=#330099>Kuře, brambor, salát................................. 82.00........................... Chicken, potatoes, salad</FONT></P>\r\n<P><FONT color=#330099>Vepřové maso, zelí, knedlík....................... 98.00...................... Pork, sour kraut,dumplings</FONT></P>\r\n<P><FONT color=#330099>Rybí filé, hranolky, obloha....................... 74.00................. Fish filet, french fries, garnish</FONT></P>\r\n<P><FONT color=#330099>Hovězí gulá, rýe..................................... 89.00..................................... Beef goulash, rice</FONT></P>\r\n<P><B><FONT color=#330099>Bezmasá jídla&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Meatless dishes</FONT></B></P>\r\n<P><FONT color=#330099>Smaený sýr, tatarská omáčka.................. 65.00........................ Fried cheese, tartar sauce</FONT></P>\r\n<P><FONT color=#330099>Palačinka se lehačkou............................ 35.00.................. Pancake with whipped creeam</FONT></P>\r\n<P><FONT color=#330099>pagety se sýrem....................................... 59.00.................................. Spagetti with cheese</FONT></P>\r\n<P><B><FONT color=#330099>Nápoje&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Drinks</FONT></B></P>\r\n<P><FONT color=#330099>Káva......................................................... 23.00....................................................... Coffee</FONT></P>\r\n<P><FONT color=#330099>Dus.......................................................... 25.00......................................................... Juice</FONT></P>\r\n<P><FONT color=#330099>Víno.......................................................... 32.00.......................................................... Wine</FONT></P>\r\n<P><FONT color=#330099>Pivo........................................................... 12.80.......................................................... Beer</FONT></P>\r\n<P><FONT color=#330099>Minerálka................................................. 15.00........................................... Mineral water</FONT></P>\r\n<P align=right><FONT color=#330099></FONT>&nbsp;</P></TD></TR></TBODY></TABLE>', 2, NULL),
