(2172, 6, 'T Modal verbs', '', 58, 'Read', '<TABLE id=table1 style=\"BORDER-RIGHT: #c0c0c0 1px dotted; BORDER-TOP: #c0c0c0 1px dotted; BORDER-LEFT: #c0c0c0 1px dotted; WIDTH: 640px; COLOR: #000080; BORDER-BOTTOM: #c0c0c0 1px dotted; HEIGHT: 96px\" cellPadding=2 width=640 bgColor=#ffcc00 border=0>\r\n<TBODY>\r\n<TR>\r\n<TD width=86><B>muset</B></TD>\r\n<TD width=360><I><FONT size=2>musí, musí, musí, musíme,musíte, musí</FONT></I></TD>\r\n<TD width=22 bgColor=#ffff00 rowSpan=3>\r\n<P align=center><B>+</B></P></TD>\r\n<TD rowSpan=3>&nbsp;<I>jít, studovat, číst, ...</I></TD></TR>\r\n<TR>\r\n<TD width=86><B>moct</B></TD>\r\n<TD width=360><I><FONT size=2>můu, můe, můe, můeme, můete, můou</FONT></I></TD></TR>\r\n<TR>\r\n<TD width=86><B>nesmět</B></TD>\r\n<TD width=360><I><FONT size=2>nesmím, nesmí, nesmí, nesmíme, nesmíte, nesmí</FONT></I></TD></TR></TBODY></TABLE>', 3, NULL),
(2173, 6, 'T Kolik je hodin?', '', 58, 'Read', '<P>\r\n<TABLE id=table1 height=133 borderColorDark=#000080 cellPadding=2 bgColor=#ffcc00 borderColorLight=#000080 border=1>\r\n<TBODY>\r\n<TR>\r\n<TD borderColorLight=#ffcc00 align=middle borderColorDark=#ffcc00 colSpan=4 height=33>\r\n<P align=left>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <FONT color=#000080>&nbsp;<B><I>Kolik je hodin?</I></B></FONT></P></TD></TR>\r\n<TR>\r\n<TD borderColor=#ffcc00 height=33><FONT color=#000080 size=2><I>Je</I></FONT></TD>\r\n<TD borderColor=#ffff00 align=right bgColor=#ffff00 height=33><FONT color=#000080 size=2>1</FONT></TD>\r\n<TD borderColor=#ffcc00 height=33><FONT color=#000080 size=2><I>jedna hodina.</I></FONT></TD>\r\n<TD borderColor=#ffcc00 height=100 rowSpan=3>\r\n<TABLE id=table2 style=\"BORDER-RIGHT: #c0c0c0 1px dotted; BORDER-TOP: #c0c0c0 1px dotted; BORDER-LEFT: #c0c0c0 1px dotted; WIDTH: 81px; COLOR: #330099; BORDER-BOTTOM: #c0c0c0 1px dotted; HEIGHT: 84px\" borderColor=#0000ff bgColor=#ffcc00 border=1>\r\n<TBODY>\r\n<TR>\r\n<TD borderColor=#ffcc00 borderColorLight=#ffcc00 width=\"84%\" bgColor=#ffcc00 borderColorDark=#ffcc00 rowSpan=5>\r\n<P align=center><B><I><FONT color=#330099><IMG height=65 src=\"http://www.bohemica.com/tuit-ew/img/textbook/bl-acimage027.gif\" width=71></FONT></I></B></P></TD></TR></TBODY></TABLE></TD></TR>\r\n<TR>\r\n<TD borderColor=#ffcc00 height=33><FONT color=#000080 size=2><I>Jsou</I></FONT></TD>\r\n<TD borderColor=#ffff00 align=right bgColor=#ffff00 height=33><FONT color=#000080 size=2>2,3,4</FONT></TD>\r\n<TD borderColor=#ffcc00 height=33><FONT color=#000080 size=2><I>dv<SPAN lang=cs>ě, tři, čtyři hodiny.</SPAN></I></FONT></TD></TR>\r\n<TR>\r\n<TD borderColor=#ffcc00 height=34><FONT color=#000080 size=2><I>Je</I></FONT></TD>\r\n<TD borderColor=#ffff00 align=right bgColor=#ffff00 height=34><FONT color=#000080 size=2>5,6,7,8, ....</FONT></TD>\r\n<TD borderColor=#ffcc00 height=34><FONT color=#000080 size=2><I>pět, est, sedm, osm, .... h