(2199, 1, 'U27/3', '', 58, '', '<P></P>\r\n<H3><FONT color=#330099>Doplňte!</FONT></H3>\r\n<P>\r\n<TABLE class=MsoNormalTable id=table4 style=\"MARGIN-LEFT: 3.5pt; BORDER-COLLAPSE: collapse\" borderColor=#b0c4de cellPadding=2 width=619 border=1>\r\n<TBODY>\r\n<TR style=\"HEIGHT: 20.15pt\">\r\n<TD vAlign=bottom width=171 bgColor=#f2f2f2><FONT face=Arial color=#330099>Brno</FONT></TD>\r\n<TD bgColor=#b0c4de><I><FONT face=Arial color=#330099>Byl jsem v [$1,text 25:Brně]</FONT></I></TD></TR>\r\n<TR style=\"HEIGHT: 20.15pt\">\r\n<TD vAlign=bottom align=left width=171 bgColor=#f2f2f2><FONT face=Arial color=#330099>Václavské náměstí</FONT></TD>\r\n<TD bgColor=#b0c4de><I><FONT face=Arial color=#330099>Tereza je na [$1,text 25:Václavském náměstí]</FONT></I></TD></TR>\r\n<TR style=\"HEIGHT: 20.15pt\">\r\n<TD vAlign=bottom align=left width=171 bgColor=#f2f2f2><FONT face=Arial color=#330099>Vídeň</FONT></TD>\r\n<TD bgColor=#b0c4de><I><FONT face=Arial color=#330099>Byli jsme ve [$1,text 25:Vídni]</FONT></I></TD></TR>\r\n<TR style=\"HEIGHT: 20.15pt\">\r\n<TD vAlign=bottom align=left width=171 bgColor=#f2f2f2><FONT face=Arial color=#330099>Praský hrad</FONT></TD>\r\n<TD bgColor=#b0c4de><I><FONT face=Arial color=#330099>Veronika byla na [$1,text 25:Praském hradě]</FONT></I></TD></TR>\r\n<TR style=\"HEIGHT: 20.15pt\">\r\n<TD vAlign=bottom align=left width=171 bgColor=#f2f2f2><FONT face=Arial color=#330099>hezký bar</FONT></TD>\r\n<TD bgColor=#b0c4de><I><FONT face=Arial color=#330099>Jan a Věra jsou v [$1,text 25:hezkém baru]</FONT></I></TD></TR>\r\n<TR style=\"HEIGHT: 20.15pt\">\r\n<TD vAlign=bottom align=left width=171 bgColor=#f2f2f2><FONT face=Arial color=#330099>galerie</FONT></TD>\r\n<TD bgColor=#b0c4de><I><FONT face=Arial color=#330099>Byl jsem v [$1,text 25:galerii]</FONT></I></TD></TR>\r\n<TR style=\"HEIGHT: 20.15pt\">\r\n<TD vAlign=bottom align=middle width=171 bgColor=#f2f2f2>\r\n<P align=left><FONT face=Arial color=#330099>pizzerie</FONT></P></TD>\r\n<TD vAlign=bottom w