(2200, 1, 'U27/4', '', 58, '', '<H3><FONT color=#330099>Doplňte!</FONT></H3>\r\n<P>\r\n<TABLE class=\"\" id=table5 style=\"WIDTH: 753px; HEIGHT: 234px\" cellSpacing=2 cellPadding=2 bgColor=#b0c4de border=0>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=bottom width=256><I><FONT face=Arial color=#330099>Anna byla v[$1,text 12: divadle].</FONT></I></TD>\r\n<TD vAlign=bottom align=left width=96 bgColor=#f2f2f2>\r\n<P align=left><FONT face=Arial color=#330099>divadlo</FONT></P></TD>\r\n<TD vAlign=bottom width=291><I><FONT face=Arial color=#330099>Ve [$1,text 12:městě] jsou nové domy.</FONT></I></TD>\r\n<TD vAlign=bottom align=left width=84 bgColor=#f2f2f2>\r\n<P align=left><FONT face=Arial color=#330099>město</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=256><I><FONT face=Arial color=#330099>Co je dnes v [$1,text 12:televizi]?</FONT></I></TD>\r\n<TD vAlign=bottom align=left width=96 bgColor=#f2f2f2>\r\n<P align=left><FONT face=Arial color=#330099>televize</FONT></P></TD>\r\n<TD vAlign=bottom width=291><I><FONT face=Arial color=#330099>Je Martin v [$1,text 12:Berlíně]?</FONT></I></TD>\r\n<TD vAlign=bottom align=left width=84 bgColor=#f2f2f2>\r\n<P align=left><FONT face=Arial color=#330099>Berlín</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=256><I><FONT face=Arial color=#330099>Děti jsou ve [$1,text 12:kole].</FONT></I></TD>\r\n<TD vAlign=bottom align=left width=96 bgColor=#f2f2f2>\r\n<P align=left><FONT face=Arial color=#330099>kola</FONT></P></TD>\r\n<TD vAlign=bottom width=291><I><FONT face=Arial color=#330099>Pes je v [$1,text 12:parku].</FONT></I></TD>\r\n<TD vAlign=bottom align=left width=84 bgColor=#f2f2f2>\r\n<P align=left><FONT face=Arial color=#330099>park</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=256><I><FONT face=Arial color=#330099>Michal je v [$1,text 12:kině].</FONT></I></TD>\r\n<TD vAlign=bottom align=left width=96 bgColor=#f2f2f2>\r\n<P align=left><FONT face=Arial color=#330099>kino</FONT></P></TD>\r\n<TD vAlign=bottom width=291><I