(2223, 1, 'U30/3', '', 58, '', '<H3><FONT color=#330099>Doplňte!</FONT></H3>\r\n<P>\r\n<TABLE id=table16 style=\"BORDER-RIGHT: #c0c0c0 1px dotted; BORDER-TOP: #c0c0c0 1px dotted; BORDER-LEFT: #c0c0c0 1px dotted; WIDTH: 599px; BORDER-BOTTOM: #c0c0c0 1px dotted; BORDER-COLLAPSE: collapse; HEIGHT: 241px\" borderColor=#b0c4de cellPadding=2 width=599 bgColor=#b0c4de border=1>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=top borderColor=#b0c4de width=468><I><FONT face=Arial color=#330099>Chodím do [$1,text 12:koly] kadý den.</FONT></I></TD>\r\n<TD vAlign=top borderColor=#b0c4de width=142 bgColor=#f2f2f2><FONT face=Arial color=#330099>kola</FONT></TD></TR>\r\n<TR>\r\n<TD vAlign=top borderColor=#b0c4de width=468><I><FONT face=Arial color=#330099>Jdu do [$1,text 12:kina] bez [$1,text 12:kamaráda].</FONT></I></TD>\r\n<TD vAlign=top borderColor=#b0c4de width=142 bgColor=#f2f2f2><FONT face=Arial color=#330099>kino, kamarád</FONT></TD></TR>\r\n<TR>\r\n<TD vAlign=top borderColor=#b0c4de width=468><I><FONT face=Arial color=#330099>Chci kávu bez [$1,text 12:cukru].</FONT></I></TD>\r\n<TD vAlign=top borderColor=#b0c4de width=142 bgColor=#f2f2f2><FONT face=Arial color=#330099>cukr</FONT></TD></TR>\r\n<TR>\r\n<TD vAlign=top borderColor=#b0c4de width=468><I><FONT face=Arial color=#330099>Jsi z [$1,text 12:Jihlavy]?</FONT></I></TD>\r\n<TD vAlign=top borderColor=#b0c4de width=142 bgColor=#f2f2f2><FONT face=Arial color=#330099>Jihlava</FONT></TD></TR>\r\n<TR>\r\n<TD vAlign=top borderColor=#b0c4de width=468><I><FONT face=Arial color=#330099>V sobotu jedeme do [$1,text 12:Plzně].</FONT></I></TD>\r\n<TD vAlign=top borderColor=#b0c4de width=142 bgColor=#f2f2f2><FONT face=Arial color=#330099>Plzeň</FONT></TD></TR>\r\n<TR>\r\n<TD vAlign=top borderColor=#b0c4de width=468><I><FONT face=Arial color=#330099>Kino je vedle [$1,text 12:parku].</FONT></I></TD>\r\n<TD vAlign=top borderColor=#b0c4de width=142 bgColor=#f2f2f2><FONT face=Arial color=#330099>park</FONT></TD></TR>\r\n<TR>\r\n<TD vAlign=top borderColor=#b0c4de width=468><I><FONT face=Arial color=#330099>Dnes večer jdeme do [$1,text 12:restaurace.]</FONT></I></TD>\r\n<TD vAlign=top borderColor=#b0c4de width=142 bgColor=#f2f2f2><FONT face=Arial color=#330099>restaurace</FONT></TD></TR>\r\n<TR>\r\n<TD vAlign=top borderColor=#b0c4de width=468><I><FONT face=Arial color=#330099>Petr je u [$1,text 12:Alee].</FONT></I></TD>\r\n<TD vAlign=top borderColor=#b0c4de width=142 bgColor=#f2f2f2><FONT face=Arial color=#330099>Ale</FONT></TD></TR>\r\n<TR>\r\n<TD vAlign=top borderColor=#b0c4de width=468><I><FONT face=Arial color=#330099>Renata je vedle [$1,text 12:Jany].</FONT></I></TD>\r\n<TD vAlign=top borderColor=#b0c4de width=142 bgColor=#f2f2f2><FONT face=Arial color=#330099>Jana</FONT></TD></TR>\r\n<TR>\r\n<TD vAlign=top borderColor=#b0c4de width=468><I><FONT face=Arial color=#330099>Čekám na Kateřinu u [$1,text 12:Tesca].</FONT></I></TD>\r\n<TD vAlign=top borderColor=#b0c4de width=142 bgColor=#f2f2f2><FONT face=Arial color=#330099>Tesco</FONT></TD></TR></TBODY></TABLE></P>', 3, NULL),
(2224, 1, 'U30/4', '', 58, '', '<H3><FONT color=#330099>Doplňte!</FONT></H3>\r\n<TABLE id=table13 style=\"BORDER-COLLAPSE: collapse\" borderColor=#b0c4de cellPadding=2 bgColor=#b0c4de border=1>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=bottom borderColor=#b0c4de width=424>\r\n<P align=left><I><FONT color=#330099>Jana je z [$1,text 12:malého města].</FONT></I></P></TD>\r\n<TD vAlign=top width=199 bgColor=#f2f2f2>\r\n<P align=center><FONT color=#330099>malé město</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom borderColor=#b0c4de width=424>\r\n<P align=left><I><FONT color=#330099>Dám si trochu [$1,text 15:ovocného čaje].</FONT></I></P></TD>\r\n<TD vAlign=top width=199 bgColor=#f2f2f2>\r\n<P align=center><FONT color=#330099>ovocný čaj</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom borderColor=#b0c4de width=424>\r\n<P align=left><I><FONT color=#330099>Kdy jede do [$1,text 12:České Lípy]?</FONT></I></P></TD>\r\n<TD vAlign=top width=199 bgColor=#f2f2f2>\r\n<P align=center><FONT color=#330099>Česká Lípa</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom borderColor=#b0c4de width=424>\r\n<P align=left><I><FONT color=#330099>Jedu z [$1,text 12:Českého Krumlova] do [$1,text 12:Prahy].</FONT></I></P></TD>\r\n<TD vAlign=top width=199 bgColor=#f2f2f2>\r\n<P align=center><FONT color=#330099>Český Krumlov, Praha</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom borderColor=#b0c4de width=424>\r\n<P align=left><I><FONT color=#330099>Prosím kilo [$1,text 12:uzeného masa].</FONT></I></P></TD>\r\n<TD vAlign=top width=199 bgColor=#f2f2f2>\r\n<P align=center><FONT color=#330099>uzené maso</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom borderColor=#b0c4de width=424>\r\n<P align=left><I><FONT color=#330099>Chce kousek [$1,text 15:eidamského sýra].</FONT></I></P></TD>\r\n<TD vAlign=top width=199 bgColor=#f2f2f2>\r\n<P align=center><FONT color=#330099>eidamský sýr</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom borderColor=#b0c4de width=424>\r\n<P align=left><I><FONT color=#330099>Banka je vedle [$1,text 15:moderního hotelu].</FONT></I></P></TD>\r\n<TD vAlign=top width=199 bgColor=#f2f2f2>\r\n<P align=center><FONT color=#330099>moderní hotel</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom borderColor=#b0c4de width=424>\r\n<P align=left><I><FONT color=#330099>Co je [$1,text 12:nového]?</FONT></I></P></TD>\r\n<TD vAlign=top width=199 bgColor=#f2f2f2>\r\n<P align=center><FONT color=#330099>nový</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom borderColor=#b0c4de width=424>\r\n<P align=left><I><FONT color=#330099>Bydlí blízko [$1,text 12:Prahy].</FONT></I></P></TD>\r\n<TD vAlign=top width=199 bgColor=#f2f2f2>\r\n<P align=center><FONT color=#330099>Praha</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom borderColor=#b0c4de width=424>\r\n<P align=left><I><FONT color=#330099>Chcete jet do [$1,text 12:Kutné Hory]?</FONT></I></P></TD>\r\n<TD vAlign=top width=199 bgColor=#f2f2f2>\r\n<P align=center><FONT color=#330099>Kutná Hora</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom borderColor=#b0c4de width=424>\r\n<P align=left><I><FONT color=#330099>Dnes jdeme do [$1,text 12:kina] bez [$1,text 12:Tomáe].</FONT></I></P></TD>\r\n<TD vAlign=top width=199 bgColor=#f2f2f2>\r\n<P align=center><FONT color=#330099>&nbsp;kino,Tomá</FONT></P></TD></TR></TBODY></TABLE>', 3, NULL),
(2225, 1, 'U30/6', '', 58, '', '<H3><FONT color=#330099>\r\n<H3><FONT color=#330099>Doplňte!&nbsp; </FONT></H3>\r\n<TABLE id=table14 borderColor=#b0c4de cellPadding=2 bgColor=#b0c4de border=1>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=top width=424><I><FONT color=#330099>Mám tu knihu od kamaráda [$1,text 12:Jany].</FONT></I></TD>\r\n<TD width=199 bgColor=#f2f2f2>\r\n<P align=center><FONT color=#330099>Jana</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=424><I><FONT color=#330099>Vedle knihy [$1,text 12:Michala] je káva.</FONT></I></TD>\r\n<TD width=199 bgColor=#f2f2f2>\r\n<P align=center><FONT color=#330099>Michal</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=424><I><FONT color=#330099>Jsme u bratra [$1,text 12:Dominika].</FONT></I></TD>\r\n<TD width=199 bgColor=#f2f2f2>\r\n<P align=center><FONT color=#330099>Dominik</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=424><I><FONT color=#330099>Koncert [$1,text 12:Petra] byl dobrý.</FONT></I></TD>\r\n<TD width=199 bgColor=#f2f2f2>\r\n<P align=center><FONT color=#330099>Petr</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=424><I><FONT color=#330099>Chceme jet na výlet bez sestry [$1,text 12:Romana].</FONT></I></TD>\r\n<TD width=199 bgColor=#f2f2f2>\r\n<P align=center><FONT color=#330099>Roman</FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=424><I><FONT color=#330099>Mám knihu od kamarádky [$1,text 12:Jirky].</FONT></I></TD>\r\n<TD width=199 bgColor=#f2f2f2>\r\n<P align=center><FONT color=#330099>Jirka</FONT></P></TD></TR></TBODY></TABLE></FONT></H3>', 3, NULL),
(2226, 1, 'U30/7', '', 58, '', '<P class=MsoBodyTextIndent style=\"LINE-HEIGHT: normal\" align=left><B><FONT color=#000080 size=4>Řekněte, co nejvíce vět!</FONT></B></P>\r\n<TABLE id=table8 style=\"BORDER-RIGHT: #c0c0c0 1px dotted; BORDER-TOP: #c0c0c0 1px dotted; BORDER-LEFT: #c0c0c0 1px dotted; WIDTH: 815px; BORDER-BOTTOM: #c0c0c0 1px dotted; HEIGHT: 298px\" borderColor=#b0c4de cellPadding=2 width=815 bgColor=#b0c4de border=1>\r\n<TBODY>\r\n<TR>\r\n<TD width=291 bgColor=#f2f2f2>\r\n<DIV align=center><FONT color=#000080>ráno, dopoledne, v poledne, odpoledne, večer, v noci</FONT></DIV>\r\n<DIV align=center><FONT color=#000080>v pondělí, v úterý, ve středu, ve čtvrtek, v pátek, v sobotu, v neděli</FONT></DIV>\r\n<DIV align=center><FONT color=#000080>včera, dnes, dneska</FONT></DIV>\r\n<DIV align=center><FONT color=#000080>minulý týden</FONT></DIV>\r\n<DIV align=center><FONT color=#000080>v jednu hodinu, ve dvě hodiny,..</FONT></DIV></TD>\r\n<TD bgColor=#f2f2f2>\r\n<DIV align=center><FONT color=#000080>psát, číst, být, studovat, lyovat, plavat, vařit</FONT></DIV>\r\n<DIV align=center><FONT color=#000080>večeřet, obědvat, snídat, jíst, </FONT></DIV>\r\n<DIV align=center><FONT color=#000080>koupit si, dát si, odpočívat, čekat na, dívat se na</FONT></DIV>\r\n<DIV align=center><FONT color=#000080>muset, moct, nesmět, chtít, potřebodvat</FONT></DIV>\r\n<DIV align=center><FONT color=#000080>jít, jet, chodit, jezdit</FONT></DIV></TD>\r\n<TD width=334 bgColor=#f2f2f2>\r\n<DIV align=center><FONT color=#000080>kino, divadlo, restaurace, hospoda, vinárna, park, knihovna, kancelář, pokoj, třída, čistírna</FONT></DIV>\r\n<DIV align=center><FONT color=#000080>Český Krumlov, Kutná Hora, Brno, Praha</FONT></DIV>\r\n<DIV align=center><FONT color=#000080>&nbsp;Londýn,Paří, Řím, Berlín, Bratislava, Budape, Bukure</FONT></DIV>\r\n<DIV align=center><FONT color=#000080>Česká republika, Polsko, Německo, Rakousko, Itálie, Francie, Anglie, panělsko, Amerika, Evropa,</FONT></DIV>\r\n<DIV align=center><U><FONT color=#000080>kolej, výstava, diskotéka, tenis, hokej, Morava, policie, Slovensko, náměstí,nádraí, přednáka</FONT></U><FONT color=#000080> </FONT></DIV></TD></TR>\r\n<TR>\r\n<TD width=291 height=86>&nbsp;</TD>\r\n<TD height=86>\r\n<P align=center><SPAN lang=en-us>[$1, textarea 50,7]</SPAN></P></TD>\r\n<TD width=334 height=86>&nbsp;</TD></TR></TBODY></TABLE>', 3, NULL),
