(2252, 1, 'U36/4', '', 49, '', '<H1><FONT color=#330099>Moje rodina</FONT></H1>\r\n<H3 align=left><FONT color=#330099>Doplňte do textu následující slova: <EM><FONT size=3>má(2x), je(2x), protoe, můj, moje(3x), já, my, nai, být, chce</FONT><FONT size=4>!</FONT></EM></FONT></H3>\r\n<P align=left><IMG style=\"WIDTH: 633px; HEIGHT: 420px\" height=549 src=\"http://www.bohemica.com/tuit/img/textbook/family.gif\" width=718 align=default border=0></P>\r\n<P align=left>\r\n<TABLE cellSpacing=0 cellPadding=2 width=687 border=1>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=top></TD>\r\n<TD vAlign=top>\r\n<P><I><FONT color=#330099>Jano, <BR></FONT></I><I><FONT color=#330099>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; tady na fotografii je [$1,text 12:moje] rodina. Uprostřed je babička Věra a vedle jsem [$1,text 12:já]. Vzadu je tatínek a maminka. [$1,text 12:Můj] tatínek je doktor a [$1,text 12:moje] maminka je učitelka. Vedle maminky [$1,text 12:je] její sestra Alena. Její manel tady není, [$1,text 12:protoe] je nemocný. Teta Alena [$1,text 12:má] dvojčata Jarku a Ivu. [$1,text 12:Je] jim jedenáct let. A vepředu jsme [$1,text 12:my] děti.Tohle je [$1,text 12:moje] sestra Jana.Vedle jsou [$1,text 12:nai] bratři Mirek a Pavel. Pavlovi je 20 let a chce [$1,text 12:být] právník. Mirek [$1,text 12:má] rád zvířata a [$1,text 12:chce] být veterinář.</FONT></I></P></TD></TR></TBODY></TABLE></P>\r\n<H3><FONT color=#330099>Odpovězte na otázky!</FONT></H3>\r\n<P align=left>\r\n<TABLE cellSpacing=2 cellPadding=2 width=692 border=0>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=bottom width=246><I><FONT color=#330099>Co dělá její tatínek?</FONT></I></TD>\r\n<TD vAlign=bottom width=432><FONT color=#330099>&nbsp;[$1,text 40]</FONT></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=246><I><FONT color=#330099>Jak se jmenuje sestra maminky?</FONT></I></TD>\r\n<TD vAlign=bottom width=432><FONT color=#330099>&nbsp;[$1,text 40]</FONT></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=246><I><FONT color=#330099>Kolik let je dvojčatům?</FONT></I></TD>\r\n<TD vAlign=bottom width=432><FONT color=#330099>&nbsp;[$1,text 40]</FONT></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=246><I><FONT color=#330099>Kolik bratrů&nbsp; má?</FONT></I></TD>\r\n<TD vAlign=bottom width=432><FONT color=#330099>&nbsp;[$1,text 40]</FONT></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=246><I><FONT color=#330099>Kdo je svobodný?</FONT></I></TD>\r\n<TD vAlign=bottom width=432><FONT color=#330099>&nbsp;[$1,text 40]</FONT></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=246><I><FONT color=#330099>Proč chce být Mirek veterinář?</FONT></I></TD>\r\n<TD vAlign=bottom width=432><FONT color=#330099>&nbsp;[$1,text 40]</FONT></TD></TR></TBODY></TABLE></P>', 3, NULL),
(2253, 1, 'U37/1', '', 58, '', '&nbsp;\r\n<TABLE class=\"\" id=table8 style=\"BORDER-RIGHT: #000080 1px solid; BORDER-TOP: #000080 1px solid; BORDER-LEFT: #000080 1px solid; WIDTH: 751px; BORDER-BOTTOM: #000080 1px solid; HEIGHT: 130px\" cellSpacing=2 cellPadding=2 bgColor=#ffcf4c border=0>\r\n<TBODY>\r\n<TR>\r\n<TD rowSpan=5><FONT color=#ff6633 size=4>&nbsp;</FONT> <IMG title=\"\" style=\"MARGIN: 0px\" height=81 alt=\"\" src=\"http://www.bohemica.com/tuit-ew/img/textbook/bl-acimage027.gif\" width=91 align=default border=0> </TD></TR>\r\n<TR>\r\n<TD width=40 height=24><FONT color=#996600>&nbsp;<FONT size=4>TEN</FONT></FONT></TD>\r\n<TD width=171 height=24><FONT color=#996600 size=4>&nbsp;<SPAN lang=en-us>ob</SPAN>ěd<SPAN lang=en-us>, </SPAN>čaj&nbsp;</FONT></TD>\r\n<TD align=middle width=65 rowSpan=4><B><FONT color=#000080 size=7><FONT face=\"Times New Roman\">&#8594;</FONT>&nbsp;</FONT></B></TD>\r\n<TD width=46 height=48 rowSpan=2><FONT color=#996600 size=4>t</FONT><U><FONT color=#000080 size=4><B><I>o</I></B></FONT></U><I><U><B><FONT color=#000080 size=4>mu</FONT></B></U></I></TD>\r\n<TD width=71 height=48 rowSpan=2><FONT color=#996600 size=4>dobr</FONT><I><U><B><FONT color=#000080 size=4>ému</FONT></B></U></I><FONT color=#996600 size=4>&nbsp;</FONT></TD>\r\n<TD width=174 height=24><FONT color=#996600 size=4>oběd</FONT><B><I><U><FONT color=#000080 size=4>u</FONT></U></I></B><FONT color=#000080 size=4><B><I><U>*</U></I></B></FONT><FONT color=#996600 size=4>, čaj</FONT><B><I><U><FONT color=#000080 size=4>i</FONT></U></I></B><FONT color=#996600 size=4>&nbsp;</FONT></TD></TR>\r\n<TR>\r\n<TD width=40 height=24>&nbsp;</TD>\r\n<TD width=171 height=24><FONT color=#996600 size=4>kamarád, Tomá</FONT></TD>\r\n<TD width=174 height=24><FONT color=#996600 size=4>kamarád</FONT><B><I><U><FONT color=#000080 size=4>ovi</FONT></U></I></B><FONT color=#000080 size=4><I><U><B><FONT face=\"Times New Roman\">*</FONT></B></U></I></FONT><FONT color=#996600 size=4>,Tomá</FONT><U><FONT color=#000080 size=4><B><I>ovi</I></B></FONT></U><FONT color=#000080 size=4><I><U><B><FONT face=\"Times New Roman\">*</FONT></B></U></I></FONT></TD></TR>\r\n<TR>\r\n<TD width=40><FONT size=4>&nbsp;<FONT color=#ff6633>TA</FONT></FONT></TD>\r\n<TD width=171>&nbsp;<FONT color=#ff6633 size=4>Eva, večeře, mrkev</FONT></TD>\r\n<TD width=46><FONT color=#ff6633 size=4>t</FONT><B><I><U><FONT color=#000080 size=4>é</FONT></U></I></B></TD>\r\n<TD width=71><FONT color=#ff6633 size=4>dobr</FONT><I><U><FONT color=#000080 size=4><STRONG>é</STRONG></FONT></U></I></TD>\r\n<TD width=174><FONT color=#ff6633 size=4>Ev</FONT><I><U><FONT color=#000080 size=4><STRONG>ě</STRONG></FONT></U></I><FONT color=#ff6633 size=4>, večeř</FONT><I><U><FONT color=#000080 size=4><STRONG>i</STRONG></FONT></U></I><FONT color=#ff6633 size=4>, mrkv</FONT><U><B><FONT color=#000080 size=4><I>i</I></FONT></B></U></TD></TR>\r\n<TR>\r\n<TD width=40><FONT size=4>&nbsp;<FONT color=#339933>TO</FONT></FONT></TD>\r\n<TD width=171><FONT color=#339933 size=4>&nbsp;jídlo, kuře, pití</FONT></TD>\r\n<TD width=46><FONT color=#339933 size=4>t</FONT><U><FONT color=#000080 size=4><B><I>o</I></B></FONT></U><I><U><B><FONT color=#000080 size=4>mu</FONT></B></U></I></TD>\r\n<TD width=71><FONT color=#008000 size=4>dobr</FONT><I><U><B><FONT color=#000080 size=4>ému</FONT></B></U></I><FONT color=#996600 size=4>&nbsp;</FONT></TD>\r\n<TD width=174><FONT color=#339933 size=4>jídl</FONT><B><I><U><FONT color=#000080 size=4>u</FONT></U></I></B><FONT color=#339933 size=4>, kuř</FONT><B><I><U><FONT color=#000080 size=4>eti</FONT></U></I></B><FONT color=#339933 size=4>, pití</FONT></TD></TR></TBODY></TABLE>', 3, NULL),
(2254, 1, 'U37/2', '', 58, '', '<H3><FONT color=#330099>Doplňte a odpovězte?</FONT></H3>\r\n<TABLE class=\"\" id=table7 cellSpacing=2 cellPadding=2 bgColor=#b0c4de border=0>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=bottom width=185><FONT color=#330099><I>Co se líbí [$1,text 12:mamince]?</I></FONT></TD>\r\n<TD vAlign=bottom width=76 bgColor=#f2f2f2><FONT color=#330099>maminka</FONT></TD>\r\n<TD vAlign=bottom width=393><FONT color=#330099>&nbsp;[$1,text 40]</FONT></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=185><I><FONT color=#330099>Co se líbí [$1,text 12:tatínkovi]?</FONT></I></TD>\r\n<TD vAlign=bottom width=76 bgColor=#f2f2f2><FONT color=#330099>tatínek</FONT></TD>\r\n<TD vAlign=bottom width=393><FONT color=#330099>&nbsp;[$1,text 40]</FONT></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=185><I><FONT color=#330099>Co se líbí [$1,text 12:bratrovi]?</FONT></I></TD>\r\n<TD vAlign=bottom width=76 bgColor=#f2f2f2><FONT color=#330099>bratr</FONT></TD>\r\n<TD vAlign=bottom width=393><FONT color=#330099>&nbsp;[$1,text 40]</FONT></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=185><I><FONT color=#330099>Co se líbí [$1,text 12:Janě]?</FONT></I></TD>\r\n<TD vAlign=bottom width=76 bgColor=#f2f2f2><FONT color=#330099>Jana</FONT></TD>\r\n<TD vAlign=bottom width=393><FONT color=#330099>&nbsp;[$1,text 40]</FONT></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=185><I><FONT color=#330099>Co se líbí [$1,text 12:Lukáovi]?</FONT></I></TD>\r\n<TD vAlign=bottom width=76 bgColor=#f2f2f2><FONT color=#330099>Luká</FONT></TD>\r\n<TD vAlign=bottom width=393><FONT color=#330099>&nbsp;[$1,text 40]</FONT></TD></TR></TBODY></TABLE>', 3, NULL),
(2255, 1, 'U37/3', '', 58, '', '<H3><FONT color=#330099>Ke komu jdete? Ke komu jedete?</FONT></H3><FONT color=#330099>\r\n<TABLE class=\"\" id=table8 cellPadding=2 width=832 bgColor=#b0c4de border=0>\r\n<TBODY>\r\n<TR>\r\n<TD width=189 rowSpan=9>\r\n<P align=center><B><FONT color=#330099 size=4>Jdu k/ ke ...</FONT></B></P>\r\n<P align=center><B><FONT color=#330099 size=4>Jedu k/ke ...</FONT></B></P>\r\n<P align=center><FONT color=#330099><IMG height=198 src=\"http://www.bohemica.com/tuit/img/textbook/ax-image014.gif\" width=173> </FONT></P></TD>\r\n<TD width=109 bgColor=#f2f2f2><FONT color=#330099>Anna</FONT></TD>\r\n<TD width=281><I><FONT color=#330099>Jdu k [$1,text 12:Anně].</FONT></I></TD>\r\n<TD width=228 rowSpan=9>\r\n<P align=center><FONT color=#330099><IMG height=204 src=\"http://www.bohemica.com/tuit/img/textbook/ax-image016.gif\" width=204> </FONT></P></TD></TR>\r\n<TR>\r\n<TD width=109 bgColor=#f2f2f2><FONT color=#330099>maminka</FONT></TD>\r\n<TD width=281><I><FONT color=#330099>Jedu k [$1,text 12:mamince] do Ostravy.</FONT></I></TD></TR>\r\n<TR>\r\n<TD width=109 bgColor=#f2f2f2><FONT color=#330099>doktor</FONT></TD>\r\n<TD width=281><I><FONT color=#330099>Jdu k [$1,text 12:doktoru].</FONT></I></TD></TR>\r\n<TR>\r\n<TD width=109 bgColor=#f2f2f2><FONT color=#330099>kamarád</FONT></TD>\r\n<TD width=281><I><FONT color=#330099>Jedu ke [$1,text 12:kamarádovi] do Brna.</FONT></I></TD></TR>\r\n<TR>\r\n<TD width=109 bgColor=#f2f2f2><FONT color=#330099>Jiřina</FONT></TD>\r\n<TD width=281><I><FONT color=#330099>Jdu k [$1,text 12:Jiřině].</FONT></I></TD></TR>\r\n<TR>\r\n<TD width=109 bgColor=#f2f2f2><FONT color=#330099>pan Sovák</FONT></TD>\r\n<TD width=281><I><FONT color=#330099>Jdu k [$1,text 20:panu Sovákovi].</FONT></I></TD></TR>\r\n<TR>\r\n<TD width=109 bgColor=#f2f2f2><FONT color=#330099>doktorka Nová</FONT></TD>\r\n<TD width=281><I><FONT color=#330099>Jdu k&nbsp;[$1,text 20:doktorce Nové].</FONT></I></TD></TR>\r\n<TR>\r\n<TD width=109 bgColor=#f2f2f2><FONT color=#330099>Tomá</FONT></TD>\r\n<TD width=281><I><FONT color=#330099>Jedu k&nbsp;[$1,text 12:Tomáovi].</FONT></I></TD></TR>\r\n<TR>\r\n<TD width=109 bgColor=#f2f2f2><FONT color=#330099>doktor Veselý</FONT></TD>\r\n<TD width=281><I><FONT color=#330099>Jdu k&nbsp;[$1,text 20:panu Veselému].</FONT></I></TD></TR></TBODY></TABLE></FONT>', 3, NULL),
(2256, 1, 'U37/4', '', 58, '', '<FONT color=#330099>&nbsp;</FONT>\r\n<P><FONT color=#330099 size=4><STRONG>Napite správně!</STRONG></FONT></P>\r\n<TABLE class=\"\" id=table9 cellSpacing=2 cellPadding=2 width=492 bgColor=#b0c4de border=0>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=bottom width=380><I><FONT face=Arial color=#330099>Dnes odpoledne jdu ke [$1,text 12:Kateřině].</FONT></I></TD>\r\n<TD vAlign=bottom width=98 bgColor=#f2f2f2><FONT face=Arial color=#330099>Kateřina</FONT></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=380><I><FONT face=Arial color=#330099>Jirka jede k [$1,text 12:sestře].</FONT></I></TD>\r\n<TD vAlign=bottom width=98 bgColor=#f2f2f2><FONT face=Arial color=#330099>sestra</FONT></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=380><I><FONT face=Arial color=#330099>Co si dáte k&nbsp;]obědu]?</FONT></I></TD>\r\n<TD vAlign=bottom width=98 bgColor=#f2f2f2><FONT face=Arial color=#330099>oběd</FONT></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=380><I><FONT face=Arial color=#330099>Jdete k [$1,text 12:Danovi]?</FONT></I></TD>\r\n<TD vAlign=bottom width=98 bgColor=#f2f2f2><FONT face=Arial color=#330099>Dan</FONT></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=380><I><FONT face=Arial color=#330099>Jezdíte k [$1,text 12:mamince]?</FONT></I></TD>\r\n<TD vAlign=bottom width=98 bgColor=#f2f2f2><FONT face=Arial color=#330099>maminka</FONT></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=380><FONT color=#330099><I><FONT face=Arial color=#330099>Ke komu [$1,text 12:jede]?</FONT></I></FONT></TD>\r\n<TD vAlign=bottom width=98 bgColor=#f2f2f2><FONT face=Arial color=#330099>kdo</FONT></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=380><FONT color=#330099><I><FONT face=Arial color=#330099>Co si dá Jirka k [$1,text 12:večeři]?</FONT></I></FONT></TD>\r\n<TD vAlign=bottom width=98 bgColor=#f2f2f2><FONT face=Arial color=#330099>večeře</FONT></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=380><FONT color=#330099><I><FONT face=Arial color=#330099>Co si dáte k [$1,text 12:salátu]?</FONT></I><