(2273, 1, 'U39/2', '', 58, '', '&nbsp;<I><FONT face=Arial color=#000080 size=5><STRONG>Jana ráda lyuje.</STRONG></FONT></I>&nbsp;&nbsp; \r\n<TABLE id=table8 borderColor=#ffcc00 borderColorDark=#ffcc00 width=\"60%\" bgColor=#ffcc00 borderColorLight=#ffcc00 border=1>\r\n<TBODY>\r\n<TR>\r\n<TD borderColor=#ffcc00 width=\"18%\" bgColor=#ffcc00 rowSpan=3>\r\n<P align=center><FONT size=5><STRONG><IMG height=79 src=\"http://www.bohemica.com/tuit/img/textbook/as-image063.gif\" width=89 border=0></STRONG></FONT></P></TD>\r\n<TD borderColor=#ffcc00 borderColorLight=#ffcc00 width=\"11%\" bgColor=#ffcc00 borderColorDark=#ffcc00><I><B><FONT face=Arial color=#000080>Rád</FONT></B></I></TD>\r\n<TD borderColor=#ffcc00 borderColorLight=#ffcc00 width=\"40%\" bgColor=#ffcc00 borderColorDark=#ffcc00><I><FONT face=Arial color=#000080>lyuju, lyuje, lyuje</FONT></I></TD>\r\n<TD borderColor=#ffcc00 width=\"33%\" bgColor=#ffcc00 rowSpan=3>\r\n<P align=center><IMG height=74 src=\"http://www.bohemica.com/tuit/img/textbook/bd-image007.gif\" width=117 border=0></P></TD></TR>\r\n<TR>\r\n<TD borderColor=#ffcc00 borderColorLight=#ffcc00 width=\"11%\" bgColor=#ffcc00 borderColorDark=#ffcc00><I><B><FONT face=Arial color=#000080>Ráda</FONT></B></I></TD>\r\n<TD borderColor=#ffcc00 borderColorLight=#ffcc00 width=\"40%\" bgColor=#ffcc00 borderColorDark=#ffcc00><I><FONT face=Arial color=#000080>lyuju, lyuje, lyuje</FONT></I></TD></TR>\r\n<TR>\r\n<TD borderColor=#ffcc00 borderColorLight=#ffcc00 width=\"11%\" bgColor=#ffcc00 borderColorDark=#ffcc00><I><B><FONT face=Arial color=#000080>Rádi</FONT></B></I></TD>\r\n<TD borderColor=#ffcc00 borderColorLight=#ffcc00 width=\"40%\" bgColor=#ffcc00 borderColorDark=#ffcc00><I><FONT face=Arial color=#000080>lyujeme, lyujete, lyujou</FONT></I></TD></TR></TBODY></TABLE>', 3, NULL),
