(2275, 1, 'U39/4', '', 58, '', '&nbsp; \r\n<P><FONT color=#330099><IMG height=187 alt=\"\" src=\"http://www.bohemica.com/tuit/img/textbook/bd-image031.gif\" width=410></FONT></P>\r\n<P>&nbsp;<FONT color=#330099 size=4><STRONG>Napite otázky!</STRONG></FONT></P>\r\n<P>\r\n<TABLE id=table8 style=\"BORDER-RIGHT: #c0c0c0 1px dotted; BORDER-TOP: #c0c0c0 1px dotted; BORDER-LEFT: #c0c0c0 1px dotted; WIDTH: 441px; BORDER-BOTTOM: #c0c0c0 1px dotted; HEIGHT: 247px\" cellSpacing=2 cellPadding=2 bgColor=#b0c4de border=0>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=bottom width=219><I><FONT face=Arial color=#330099>[$1,text 30:Kde bydlí?]</FONT></I></TD>\r\n<TD vAlign=bottom width=206><I><FONT face=Arial color=#330099>Na koleji.</FONT></I></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=219><I><FONT face=Arial color=#330099>[$1,text 30:Kde obědvá?]</FONT></I></TD>\r\n<TD vAlign=bottom width=206><I><FONT face=Arial color=#330099>V restauraci.</FONT></I></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=219><I><FONT face=Arial color=#330099>[$1,text 30:Kam občas chodí?]</FONT></I></TD>\r\n<TD vAlign=bottom width=206><I><FONT face=Arial color=#330099>Do kina a na koncerty.</FONT></I></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=219><I><FONT face=Arial color=#330099>[$1,text 30:Kdy jezdí domů?]</FONT></I></TD>\r\n<TD vAlign=bottom width=206><I><FONT face=Arial color=#330099>V pátek.</FONT></I></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=219><I><FONT face=Arial color=#330099>[$1,text 30:Kde studuje?]</FONT></I></TD>\r\n<TD vAlign=bottom width=206><I><FONT face=Arial color=#330099>Na ČVUT.</FONT></I></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=219><I><FONT face=Arial color=#330099>[$1,text 30:Jak se jmenuje?]</FONT></I></TD>\r\n<TD vAlign=bottom width=206><I><FONT face=Arial color=#330099>Michal.</FONT></I></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=219><I><FONT face=Arial color=#330099>[$1,text 30:Kam jezdí v&nbsp;pátek?]</FONT></I></TD>\r\n<TD vAlign=bottom width=206><I><FONT face=Arial color=#330099>Do Děčína.</FONT></I></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=219><I><FONT face=Arial color=#330099>[$1,text 30:Co rád dělá?]</FONT></I></TD>\r\n<TD vAlign=bottom width=206><I><FONT face=Arial color=#330099>Hokej a fotbal.</FONT></I></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=219><I><FONT face=Arial color=#330099>[$1,text 30:Co dělá večer?]</FONT></I></TD>\r\n<TD vAlign=bottom width=206><I><FONT face=Arial color=#330099>Často se učím.</FONT></I></TD></TR></TBODY></TABLE></P>', 3, NULL),
(2277, 1, 'U40/1', '', 58, '', '<H1 align=justify><FONT color=#330099>Počasí</FONT></H1>\r\n<TABLE id=table6 borderColor=#000000 cellSpacing=0 cellPadding=3 width=680 border=1>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=top width=348>\r\n<P align=justify><IMG height=269 src=\"http://www.bohemica.com/tuit/img/textbook/bc-image002.gif\" width=337> </P></TD>\r\n<TD width=326>\r\n<P align=justify><IMG height=237 src=\"http://www.bohemica.com/tuit/img/textbook/bc-image004.gif\" width=319> <I>Na jaře a na podzim není moc hezké počasí. Často prí. Občas svítí sluníčko.</I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=348>\r\n<P align=justify><IMG height=227 src=\"http://www.bohemica.com/tuit/img/textbook/bc-image006.gif\" width=300> </P>\r\n<P align=justify><I>V létě je moc teplo. Často je přes třicet stupňů. Taky jsou bouřky.</I></P></TD>\r\n<TD vAlign=top width=326>\r\n<P align=justify><IMG height=251 src=\"http://www.bohemica.com/tuit/img/textbook/bc-image008.gif\" width=327> <I>V zimě je chladno. Prí nebo sněí. Někdy taky mrzne.</I></P></TD></TR></TBODY></TABLE>', 3, NULL),
(2278, 1, 'U40/3', '', 58, '', '&nbsp;<FONT color=#330099 size=4><STRONG>Napite, co obvykle děláte v&nbsp;létě a v&nbsp;zimě, na jaře a na podzim!</STRONG></FONT>\r\n<P>\r\n<TABLE id=table7 borderColor=#ffffff height=391 cellSpacing=0 cellPadding=2 width=542 border=2>\r\n<TBODY>\r\n<TR>\r\n<TD width=271 bgColor=#b0c4de height=195>\r\n<P align=center><I><FONT color=#330099>Na jaře je teplo.</FONT></I></P>\r\n<P align=center><FONT color=#330099>[$1,textarea 30,8]</FONT></P>\r\n<P align=center>&nbsp;</P></TD>\r\n<TD width=271 bgColor=#b0c4de height=195>\r\n<P align=center><I><FONT color=#330099>V létě je horko.</FONT></I></P>\r\n<P align=center><FONT color=#330099>[$1,textarea 30,8]</FONT> </P>\r\n<P align=center>&nbsp;</P></TD></TR>\r\n<TR>\r\n<TD width=271 bgColor=#b0c4de height=196>\r\n<P align=center><I><FONT color=#330099>V zimě je zima a mrzne.<BR>&nbsp;</FONT></I></P>\r\n<P align=center><FONT color=#330099>[$1,textarea 30,8]</FONT></P>\r\n<P>&nbsp;</P></TD>\r\n<TD width=271 bgColor=#b0c4de height=196>&nbsp; \r\n<P align=center><I><FONT color=#330099>Na podzim je chladno.<BR>&nbsp;</FONT></I></P>\r\n<P align=center><FONT color=#330099>[$1,textarea 30,8]</FONT></P>\r\n<DIV align=center>&nbsp;</DIV>\r\n<P>&nbsp;</P></TD></TR></TBODY></TABLE></P>\r\n<P>&nbsp;</P>', 3, NULL),
(2279, 1, 'U40/2', '', 58, '', '<TABLE id=table9 height=98 cellSpacing=0 width=545 bgColor=#ffcf4c border=0>\r\n<TBODY>\r\n<TR>\r\n<TD align=right width=62><B><I><FONT face=Arial color=#000080>CO?</FONT></I></B></TD>\r\n<TD align=right width=112 rowSpan=2>\r\n<P align=center><FONT color=#330099><IMG title=\"\" style=\"MARGIN: 0px\" height=81 alt=\"\" src=\"http://www.bohemica.com/tuit-ew/img/textbook/bl-acimage027.gif\" width=91 align=default border=0></FONT></P></TD>\r\n<TD align=middle width=93><FONT face=Arial color=#000080>jaro</FONT></TD>\r\n<TD align=middle width=94><FONT face=Arial color=#000080>léto</FONT></TD>\r\n<TD align=middle width=94><FONT face=Arial color=#000080>podzim</FONT></TD>\r\n<TD align=middle width=94><FONT face=Arial color=#000080>zima</FONT></TD></TR>\r\n<TR>\r\n<TD align=right width=62 height=43><B><I><FONT face=Arial color=#ff6633>KDY?</FONT></I></B></TD>\r\n<TD align=middle width=93 height=43><FONT face=Arial color=#ff6633><B>na </B>ja<B>ře</B></FONT></TD>\r\n<TD align=middle width=94 height=43><FONT face=Arial color=#ff6633><B>v </B>lét<B>ě</B></FONT></TD>\r\n<TD align=middle width=94 height=43><FONT face=Arial color=#ff6633><B>na </B>podzim</FONT></TD>\r\n<TD align=middle width=94 height=43><FONT face=Arial color=#ff6633><B>v </B>zim<B>ě</B></FONT></TD></TR></TBODY></TABLE>', 3, NULL),
(2280, 1, 'U40/4', '', 58, '', '<H3><FONT color=#330099>Jaké je počasí? </FONT></H3>\r\n<TABLE id=table6 cellSpacing=2 cellPadding=2 bgColor=#b0c4de border=0>\r\n<TBODY>\r\n<TR>\r\n<TD align=middle width=90 bgColor=#ffffff>\r\n<P align=center>&nbsp;<B><FONT color=#000080 size=4>co?</FONT></B></P></TD>\r\n<TD width=270 bgColor=#ffffff>\r\n<P align=center><B><FONT color=#000080 size=4>dnes</FONT></B></P></TD>\r\n<TD width=237 bgColor=#ffffff>\r\n<P align=center><B><FONT color=#000080 size=4>včera</FONT></B></P></TD></TR>\r\n<TR>\r\n<TD align=middle width=90 bgColor=#ffffff>\r\n<P align=right><FONT color=#330099><IMG height=53 src=\"http://www.bohemica.com/tuit/img/textbook/bc-image012.gif\" width=56></FONT><I><FONT color=#330099>slunce</FONT></I></P></TD>\r\n<TD width=270>\r\n<P align=center><I><FONT color=#330099>Svítí slunce.</FONT></I></P></TD>\r\n<TD width=237>\r\n<P align=center><I><FONT color=#330099>[$1,text 20:Svítilo slunce.]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD align=middle width=90 bgColor=#ffffff>\r\n<P align=right><FONT color=#330099><IMG height=53 src=\"http://www.bohemica.com/tuit/img/textbook/bc-image014.jpg\" width=63></FONT><I><FONT color=#330099>dé</FONT></I></P></TD>\r\n<TD width=270>\r\n<P align=center><I><FONT color=#330099>Prí.</FONT></I></P></TD>\r\n<TD width=237>\r\n<P align=center><I><FONT color=#330099>[$1,text 20:Prelo.]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD align=middle width=90 bgColor=#ffffff><FONT color=#330099><IMG height=53 src=\"http://www.bohemica.com/tuit/img/textbook/bc-image016.jpg\" width=70></FONT><I><FONT color=#330099>sníh</FONT></I></TD>\r\n<TD width=270>\r\n<P align=center><I><FONT color=#330099>Sněí.</FONT></I></P></TD>\r\n<TD width=237>\r\n<P align=center><I><FONT color=#330099>[$1,text 20:Sněilo.]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD align=middle width=90 bgColor=#ffffff><FONT color=#330099><IMG height=53 src=\"http://www.bohemica.com/tuit/img/textbook/bc-image018.jpg\" width=64></FONT><I><FONT color=#330099>bouřka</FONT></I></TD>\r\n<TD width=270>\r\n<P align=center><I><FONT color=#330099>Je bouřka.</FONT></I></P></TD>\r\n<TD width=237>\r\n<P align=center><I><FONT color=#330099>[$1,text 20:Byla bouřka.]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD align=middle width=90 bgColor=#ffffff><FONT color=#330099><IMG height=55 src=\"http://www.bohemica.com/tuit/img/textbook/bc-image020.gif\" width=72></FONT><I><FONT color=#330099>mlha</FONT></I></TD>\r\n<TD width=270>\r\n<P align=center><I><FONT color=#330099>Je mlha.</FONT></I></P></TD>\r\n<TD width=237>\r\n<P align=center><I><FONT color=#330099>[$1,text 20:Byla mlha.]</FONT></I></P></TD></TR></TBODY></TABLE>', 3, NULL),
(2281, 1, 'U40/5', '', 58, '', '<H3><FONT color=#330099>Jaké bylo počasí?</FONT></H3>\r\n<TABLE id=table6 cellSpacing=0 cellPadding=0 width=775 bgColor=#b0c4de border=0>\r\n<TBODY>\r\n<TR>\r\n<TD width=275>\r\n<P align=center><I><FONT color=#330099><IMG height=43 src=\"http://www.bohemica.com/tuit/img/textbook/bc-image022.gif\" width=75> Je skoro jasno.</FONT></I></P></TD>\r\n<TD width=229>\r\n<P align=center><I><FONT color=#330099><IMG height=47 src=\"http://www.bohemica.com/tuit/img/textbook/bc-image024.gif\" width=76> Je polojasno.</FONT></I></P></TD>\r\n<TD align=middle width=271>\r\n<P align=center><I><FONT color=#330099><IMG height=38 src=\"http://www.bohemica.com/tuit/img/textbook/bc-image026.gif\" width=90> Je zataeno.</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=275>\r\n<P align=center><I><FONT color=#330099>Včera [$1,text 20:bylo skoro jasno.]</FONT></I></P></TD>\r\n<TD width=229>\r\n<P align=center><I><FONT color=#330099>Včera [$1,text 20:bylo polojasno.]</FONT></I></P></TD>\r\n<TD align=middle width=271><I><FONT color=#330099>Včera [$1,text 20:bylo zataeno.]</FONT></I></TD></TR></TBODY></TABLE>', 3, NULL),
(2282, 1, 'U40/6', '', 58, '', '<H3><FONT color=#330099>Jaké počasí je v&nbsp;Evropě?</FONT></H3>\r\n<TABLE id=table6 cellSpacing=2 cellPadding=2 bgColor=#b0c4de border=0>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=center align=left width=85><FONT color=#330099>védsko</FONT></TD>\r\n<TD vAlign=center align=left width=227><I><FONT color=#330099>[$1,text 30:Sněí. Mínus devět stupňů.]</FONT></I></TD>\r\n<TD vAlign=top rowSpan=8><FONT color=#330099>&nbsp; </FONT>\r\n<P align=center><FONT color=#330099><IMG height=600 alt=\"\" src=\"http://www.bohemica.com/tuit/img/textbook/bc-image028.gif\" width=506> </FONT></P><BR>&nbsp;</TD></TR>\r\n<TR>\r\n<TD vAlign=center align=left width=85><FONT color=#330099>Polsko</FONT></TD>\r\n<TD vAlign=center align=left width=227><I><FONT color=#330099>[$1,text 30:Je zataeno. Nula stupňů.]</FONT></I></TD></TR>\r\n<TR>\r\n<TD vAlign=center align=left width=85><FONT color=#330099>Anglie</FONT></TD>\r\n<TD vAlign=center align=left width=227><I><FONT color=#330099>[$1,text 30:Je polojasno. Dva stupně.]</FONT></I></TD></TR>\r\n<TR>\r\n<TD vAlign=center align=left width=85><FONT color=#330099>Francie</FONT></TD>\r\n<TD vAlign=center align=left width=227><I><FONT color=#330099>[$1,text 30:Prí. Pět stupňů.]</FONT></I></TD></TR>\r\n<TR>\r\n<TD vAlign=center align=left width=85><FONT color=#330099>panělsko </FONT></TD>\r\n<TD vAlign=center align=left width=227><I><FONT color=#330099>[$1,text 30:Je skoro jasno. Patnáct stupňů.]</FONT></I></TD></TR>\r\n<TR>\r\n<TD vAlign=center align=left width=85><FONT color=#330099>Itálie</FONT></TD>\r\n<TD vAlign=center align=left width=227><I><FONT color=#330099>[$1,text 30:Svítí slunce. Čtrnáct stupňů.]</FONT></I></TD></TR>\r\n<TR>\r\n<TD vAlign=center align=left width=85><FONT color=#330099>Německo</FONT></TD>\r\n<TD vAlign=center align=left width=227><I><FONT color=#330099>[$1,text 30:Je zataeno. Čtyři stupně.]</FONT></I></TD></TR>\r\n<TR>\r\n<TD vAlign=center align=left width=85><FONT color=#330099>Rumunsko</FONT></TD>\r\n<TD vAlign=center align=left width=227><I><FONT color=#330099>[$1,text 30:Je skoro jasno. est stupňů.]</FONT></I></TD></TR></TBODY></TABLE>', 3, NULL),
(2283, 1, 'U40/7', '', 58, '', '&nbsp; \r\n<H3><B><FONT color=#330099>Co dělají Čei.</FONT></B></H3>\r\n<TABLE id=table6 style=\"BORDER-RIGHT: #c0c0c0 1px dotted; BORDER-TOP: #c0c0c0 1px dotted; BORDER-LEFT: #c0c0c0 1px dotted; WIDTH: 623px; BORDER-BOTTOM: #c0c0c0 1px dotted; HEIGHT: 328px\" cellSpacing=0 cellPadding=4 bgColor=#ffffcc border=0>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=top width=615><FONT color=#330099><IMG height=144 src=\"http://www.bohemica.com/tuit/img/textbook/bc-image029.gif\" width=182 align=left> </FONT>\r\n<P><I><FONT color=#330099>Téměř kadá česká rodina má chatu, chalupu nebo alespoň malou zahrádku a tak větinu volného času tráví tam. Lidé pracují na zahradě, upravují svoje domy, věnují se svému autu a&nbsp; koníčkům.</FONT></I></P>\r\n<P><I><FONT color=#330099>Čei také rádi cestují. Navtěvují české hrady a zámky, chodí na túry nebo cestují do zahraničí. Léto nejčastěji tráví na venkově. Chodí do lesa, sbírají houby, jezdí na kole nebo se koupou v&nbsp;rybníce.</FONT></I></P>\r\n<P><I><FONT color=#330099>Od listopadu do února lidé tráví víc času doma. Čtou knihy, dívají se na televizi, poslouchají hudbu, častěji chodí do divadla a na koncerty.</FONT></I><I><FONT color=#330099>V zimě nejraději lyují. Obvykle tráví na</FONT></I><FONT color=#330099><IMG height=130 src=\"http://www.bohemica.com/tuit/img/textbook/bc-image031.gif\" width=219 align=right></FONT><I><FONT color=#330099> horách alespoň týden dovolené. </FONT></I></P>\r\n<P><I><FONT color=#330099>Ti největí fandové ale jezdí lyovat kadý víkend. Někdy je sníh i ve městě, pak děti lyují a sáňkují na kadém kopci.</FONT></I></P>\r\n<P align=right><FONT color=#330099></FONT>&nbsp;</P></TD></TR></TBODY></TABLE>\r\n<H3><FONT color=#330099>\r\n<H3><FONT color=#330099>Je to pravda?</FONT></H3>\r\n<DIV align=left>\r\n<TABLE id=table7 style=\"BORDER-RIGHT: #c0c0c0 1px dotted; BORDER-TOP: #c0c0c0 1px dotted; BORDER-LEFT: #c0c0c0 1px dotted; WIDTH: 433px; BORDER-BOTTOM: #c0c0c0 1px dotted; HEIGHT: 274px\" cellSpacing=2 cellPadding=2 width=433 bgColor=#b0c4de border=0>\r\n<TBODY>\r\n<TR>\r\n<TD width=398><I><FONT color=#330099>V zimě jezdí na dovolenou na hory.</FONT></I></TD>\r\n<TD width=210>\r\n<P align=center><FONT color=#330099>[$1, select:/(ano/ne]</FONT></P></TD></TR>\r\n<TR>\r\n<TD width=398><I><FONT color=#330099>Větinu času tráví doma.</FONT></I></TD>\r\n<TD width=210>\r\n<P align=center><FONT color=#330099>[$1, select:/ano/(ne]</FONT></P></TD></TR>\r\n<TR>\r\n<TD width=398><I><FONT color=#330099>Rádi pracují na zahradě.</FONT></I></TD>\r\n<TD width=210>\r\n<P align=center><FONT color=#330099>[$1, select:/(ano/ne]</FONT></P></TD></TR>\r\n<TR>\r\n<TD width=398><I><FONT color=#330099>Nechodí do lesa na houby.</FONT></I></TD>\r\n<TD width=210>\r\n<P align=center><FONT color=#330099>[$1, select:/(ano/ne]</FONT></P></TD></TR>\r\n<TR>\r\n<TD width=398><I><FONT color=#330099>Koupou se v&nbsp;rybníce.</FONT></I></TD>\r\n<TD width=210>\r\n<P align=center><FONT color=#330099>[$1, select:/(ano/ne]</FONT></P></TD></TR>\r\n<TR>\r\n<TD width=398><I><FONT color=#330099>V zimě jezdí na kole.</FONT></I></TD>\r\n<TD width=210>\r\n<P align=center><FONT color=#330099>[$1, select:/ano/(ne]</FONT></P></TD></TR>\r\n<TR>\r\n<TD width=398><I><FONT color=#330099>V létě častěji chodí do divadla.</FONT></I></TD>\r\n<TD width=210>\r\n<P align=center><FONT color=#330099>[$1, select:/ano/(ne]</FONT></P></TD></TR>\r\n<TR>\r\n<TD width=398><I><FONT color=#330099>Ve městě není sníh.</FONT></I></TD>\r\n<TD width=210>\r\n<P align=center><FONT color=#330099>[$1, select:/(ano/ne]</FONT></P></TD></TR>\r\n<TR>\r\n<TD width=398><I><FONT color=#330099>V zimě se dívají na televizi a čtou knihy.</FONT></I></TD>\r\n<TD width=210>\r\n<P align=center><FONT color=#330099>[$1, select:/(ano/ne]</FONT></P></TD></TR>\r\n<TR>\r\n<TD width=398><I><FONT color=#330099>Taky cestují do zahraničí.</FONT></I></TD>\r\n<TD width=210>\r\n<P align=center><FONT color=#330099>[$1, select:/(ano/ne]</FONT></P></TD></TR></TBODY></TABLE></DIV></FONT></H3>', 3, NULL),
(2284, 1, 'U40/4a', '', 58, '', '<TABLE id=table9 style=\"BORDER-RIGHT: #c0c0c0 1px dotted; BORDER-TOP: #c0c0c0 1px dotted; BORDER-LEFT: #c0c0c0 1px dotted; WIDTH: 477px; BORDER-BOTTOM: #c0c0c0 1px dotted; HEIGHT: 341px\" cellSpacing=0 cellPadding=2 width=477 bgColor=#ffcc00 border=0>\r\n<TBODY>\r\n<TR>\r\n<TD width=\"16%\" rowSpan=8><I><FONT color=#000080><IMG height=333 src=\"http://www.bohemica.com/tuit/img/textbook/bc-image010.gif\" width=91></FONT></I></TD>\r\n<TD align=left width=\"17%\"><B><FONT face=Arial color=#000080>°C</FONT></B></TD>\r\n<TD width=\"39%\"><I><FONT face=Arial color=#000080>stupeň Celsia</FONT></I></TD></TR>\r\n<TR>\r\n<TD align=left colSpan=2><FONT face=Arial color=#000080><I><B>Kolik je stupňů?</B></I></FONT></TD></TR>\r\n<TR>\r\n<TD align=left width=\"17%\"><FONT face=Arial color=#000080><B>0°</B></FONT></TD>\r\n<TD width=\"39%\"><I><FONT face=Arial color=#000080>Je nula stupňů</FONT></I></TD></TR>\r\n<TR>\r\n<TD align=left width=\"17%\"><FONT face=Arial color=#000080><B>1°</B></FONT></TD>\r\n<TD width=\"39%\"><I><FONT face=Arial color=#000080>Je jeden stupeň</FONT></I></TD></TR>\r\n<TR>\r\n<TD align=left width=\"17%\"><FONT face=Arial color=#000080><B>2°,3°,4°</B></FONT></TD>\r\n<TD width=\"39%\"><I><FONT face=Arial color=#000080>Jsou dva, tři, čtyři stupně</FONT></I></TD></TR>\r\n<TR>\r\n<TD align=left width=\"17%\"><FONT face=Arial color=#000080><B>5°,6°,7°,.......</B></FONT></TD>\r\n<TD width=\"39%\"><I><FONT face=Arial color=#000080>Je pět, est, sedm,... stupňů</FONT></I></TD></TR>\r\n<TR>\r\n<TD align=left width=\"17%\"><FONT face=Arial color=#000080><B>- 15°C</B></FONT></TD>\r\n<TD width=\"39%\"><I><FONT face=Arial color=#000080>Je mínus patnáct stupňů Celsia</FONT></I></TD></TR>\r\n<TR>\r\n<TD align=left width=\"17%\"><FONT face=Arial color=#000080><B>+32°C</B></FONT></TD>\r\n<TD width=\"39%\"><I><FONT face=Arial color=#000080>Je (plus) třicet dva stupňů Celsia.</FONT></I></TD></TR></TBODY></TABLE>', 3, NULL),
(2285, 1, 'U41/1', '', 58, '', '&nbsp;<FONT color=#330099 size=6><STRONG>Měsíc a rok</STRONG></FONT>\r\n<TABLE borderColor=#ffcc00 height=363 cellSpacing=0 cellPadding=0 width=289 bgColor=#ffcc00 border=1>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=bottom align=middle width=33 colSpan=2 height=25>\r\n<P align=right><FONT face=Arial color=#330099><STRONG>KALENDÁŘ</STRONG></FONT></P></TD>\r\n<TD vAlign=bottom align=middle width=21 height=25>&nbsp;</TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=13 height=26>\r\n<P><B><FONT face=Arial color=#330099>leden</FONT></B></P></TD>\r\n<TD vAlign=bottom width=96 height=26>\r\n<P><I><FONT face=Arial color=#330099>v ledn<B>u</B></FONT></I></P></TD>\r\n<TD vAlign=bottom width=96 height=312 rowSpan=12>\r\n<P align=center><FONT color=#330099><IMG height=79 src=\"http://www.bohemica.com/tuit/img/textbook/bi-image007.gif\" width=89></FONT></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=13 height=26>\r\n<P><B><FONT face=Arial color=#330099>únor</FONT></B></P></TD>\r\n<TD vAlign=bottom width=96 height=26>\r\n<P><I><FONT face=Arial color=#330099>v únor<B>u</B></FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=13 height=26>\r\n<P><B><FONT face=Arial color=#330099>březen</FONT></B></P></TD>\r\n<TD vAlign=bottom width=96 height=26>\r\n<P><I><FONT face=Arial color=#330099>v březn<B>u</B></FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=13 height=26>\r\n<P><B><FONT face=Arial color=#330099>duben</FONT></B></P></TD>\r\n<TD vAlign=bottom width=96 height=26>\r\n<P><I><FONT face=Arial color=#330099>v dubn<B>u</B></FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=13 height=26>\r\n<P><B><FONT face=Arial color=#330099>květen</FONT></B></P></TD>\r\n<TD vAlign=bottom width=96 height=26>\r\n<P><I><FONT face=Arial color=#330099>v květn<B>u</B></FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=13 height=26>\r\n<P><B><FONT face=Arial color=#330099>červen</FONT></B></P></TD>\r\n<TD vAlign=bottom width=96 height=26>\r\n<P><I><FONT face=Arial color=#330099>v červn<B>u</B></FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=13 height=26>\r\n<P><B><FONT face=Arial color=#330099>červenec</FONT></B></P></TD>\r\n<TD vAlign=bottom width=96 height=26>\r\n<P><I><FONT face=Arial color=#330099>v červenc<B>i</B></FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=13 height=26>\r\n<P><B><FONT face=Arial color=#330099>srpen</FONT></B></P></TD>\r\n<TD vAlign=bottom width=96 height=26>\r\n<P><I><FONT face=Arial color=#330099>v srpn<B>u</B></FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=13 height=26>\r\n<P><B><FONT face=Arial color=#330099>září</FONT></B></P></TD>\r\n<TD vAlign=bottom width=96 height=26>\r\n<P><I><FONT face=Arial color=#330099>v září</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=13 height=26>\r\n<P><B><FONT face=Arial color=#330099>říjen</FONT></B></P></TD>\r\n<TD vAlign=bottom width=96 height=26>\r\n<P><I><FONT face=Arial color=#330099>v říjn<B>u</B></FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=13 height=26>\r\n<P><B><FONT face=Arial color=#330099>listopad</FONT></B></P></TD>\r\n<TD vAlign=bottom width=96 height=26>\r\n<P><I><FONT face=Arial color=#330099>v listopad<B>u</B></FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=13 height=26>\r\n<P><B><FONT face=Arial color=#330099>prosinec</FONT></B></P></TD>\r\n<TD vAlign=bottom width=96 height=26>\r\n<P><I><FONT face=Arial color=#330099>v prosinc<B>i</B></FONT></I></P></TD></TR></TBODY></TABLE>', 3, NULL),
