(2288, 1, 'U42/1', '', 58, '', '<p><font size=\"6\"><strong>&nbsp;<font color=\"#330099\">Akivity zítra</font>\r\n </strong>\r\n</font>\r\n</p>\r\n<font color=\"#330099\"><p><font color=\"#330099\"><img height=\"90\" src=\"http://www.bohemica.com/tuit/img/textbook/bh-image001.gif\" width=\"606\" />\r\n </font>\r\n</p>\r\n</font>\r\n<font color=\"#330099\"><h3><font color=\"#330099\"></font>\r\n</h3>\r\n</font>\r\n<h3></h3>\r\n<h3><font color=\"#330099\"><b></b>\r\n</font>\r\n</h3>\r\n<p><table bordercolor=\"#ffffff\" cellspacing=\"0\" cellpadding=\"4\" width=\"554\" bgcolor=\"#ffcc00\" border=\"1\"><tbody><tr><td bordercolor=\"#ffcc00\" align=\"right\" width=\"350\" bgcolor=\"#ffcc00\"><i><font face=\"Arial\" color=\"#330099\">(já)</font>\r\n </i>\r\n</td>\r\n<td bordercolor=\"#ffcc00\" width=\"163\" bgcolor=\"#ffcc00\"><b><font face=\"Arial\" color=\"#330099\">budu</font>\r\n </b>\r\n</td>\r\n<td bordercolor=\"#ffcc00\" width=\"90\" bgcolor=\"#ffcc00\" rowspan=\"6\"><p align=\"center\"><b><font face=\"Arial\" color=\"#330099\" size=\"6\">+</font>\r\n </b>\r\n</p>\r\n</td>\r\n<td bordercolor=\"#ffcc00\" width=\"169\" bgcolor=\"#ffcc00\" rowspan=\"6\"><font face=\"Arial\" color=\"#330099\"><b>INFINITIV&nbsp; </b>\r\n</font>\r\n</td>\r\n<td bordercolor=\"#ffcc00\" width=\"332\" bgcolor=\"#ffcc00\" rowspan=\"6\"><p align=\"center\"><font face=\"Arial\"><img title=\"\" style=\"MARGIN: 0px\" height=\"81\" alt=\"\" src=\"http://www.bohemica.com/tuit-ew/img/textbook/bl-acimage027.gif\" width=\"91\" align=\"default\" border=\"0\" />\r\n </font>\r\n</p>\r\n</td>\r\n</tr>\r\n<tr><td bordercolor=\"#ffcc00\" align=\"right\" width=\"350\" bgcolor=\"#ffcc00\"><i><font face=\"Arial\" color=\"#330099\">(ty)</font>\r\n </i>\r\n</td>\r\n<td bordercolor=\"#ffcc00\" width=\"163\" bgcolor=\"#ffcc00\"><b><font face=\"Arial\" color=\"#330099\">bude</font>\r\n </b>\r\n</td>\r\n</tr>\r\n<tr><td bordercolor=\"#ffcc00\" align=\"right\" width=\"350\" bgcolor=\"#ffcc00\"><i><font face=\"Arial\" color=\"#330099\">(on, ona, to)</font>\r\n </i>\r\n</td>\r\n<td bordercolor=\"#ffcc00\" width=\"163\" bgcolor=\"#ffcc00\"><b><font face=\"Arial\" color=\"#330099\">bude</font>\r\n </b>\r\n</td>\r\n</tr>\r\n<tr><td bordercolor=\"#ffcc00\" align=\"right\" width=\"350\" bgcolor=\"#ffcc00\"><i><font face=\"Arial\" color=\"#330099\">(my)</font>\r\n </i>\r\n</td>\r\n<td bordercolor=\"#ffcc00\" width=\"163\" bgcolor=\"#ffcc00\"><b><font face=\"Arial\" color=\"#330099\">budeme</font>\r\n </b>\r\n</td>\r\n</tr>\r\n<tr><td bordercolor=\"#ffcc00\" align=\"right\" width=\"350\" bgcolor=\"#ffcc00\"><i><font face=\"Arial\" color=\"#330099\">(vy)</font>\r\n </i>\r\n</td>\r\n<td bordercolor=\"#ffcc00\" width=\"163\" bgcolor=\"#ffcc00\"><b><font face=\"Arial\" color=\"#330099\">budete</font>\r\n </b>\r\n</td>\r\n</tr>\r\n<tr><td bordercolor=\"#ffcc00\" align=\"right\" width=\"350\" bgcolor=\"#ffcc00\"><i><font face=\"Arial\" color=\"#330099\">(oni)</font>\r\n </i>\r\n</td>\r\n<td bordercolor=\"#ffcc00\" width=\"163\" bgcolor=\"#ffcc00\"><b><font face=\"Arial\" color=\"#330099\">budou</font>\r\n </b>\r\n</td>\r\n</tr>\r\n<tr><td bordercolor=\"#ffcc00\" width=\"350\" bgcolor=\"#ffff00\"><font face=\"Arial\" color=\"#330099\"><b>jít :</b>\r\n </font>\r\n</td>\r\n<td bordercolor=\"#ffcc00\" width=\"947\" bgcolor=\"#ffff00\" colspan=\"4\"><font face=\"Arial\" color=\"#330099\"><b>půjdu,půjde,půjde,půjdeme,půjdete,půjdou</b>\r\n </font>\r\n</td>\r\n</tr>\r\n<tr><td bordercolor=\"#ffcc00\" width=\"350\" bgcolor=\"#ffff00\"><font face=\"Arial\" color=\"#330099\"><b>jet :</b>\r\n </font>\r\n</td>\r\n<td bordercolor=\"#ffcc00\" width=\"947\" bgcolor=\"#ffff00\" colspan=\"4\"><b><font face=\"Arial\" color=\"#330099\">pojedu, pojede, pojede, pojedeme, pojedete, pojedou</font>\r\n </b>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</p>\r\n', 3, NULL),
(2289, 1, 'U42/2', '', 58, '', '<P align=left><STRONG><FONT color=#000080 size=4>Čtěte text a odpovězte na otázky!</FONT></STRONG></P>\r\n<TABLE borderColor=#ffffcc cellSpacing=0 cellPadding=2 width=381 bgColor=#ffffcc>\r\n<TBODY>\r\n<TR>\r\n<TD borderColor=#ffff99 align=middle width=369 bgColor=#000099 colSpan=2>\r\n<P align=center><B><FONT face=Arial color=#ffff99>2005</FONT></B></P></TD></TR>\r\n<TR>\r\n<TD borderColor=#ffff99 align=right width=137 bgColor=#ffff99>\r\n<P align=left><I><FONT face=Arial color=#330099>LEDEN</FONT></I></P></TD>\r\n<TD width=232><I><FONT face=Arial color=#330099>V lednu budu lyovat.</FONT></I></TD></TR>\r\n<TR>\r\n<TD borderColor=#ffff99 align=right width=137 bgColor=#ffff99>\r\n<P align=left><I><FONT face=Arial color=#330099>ÚNOR</FONT></I></P></TD>\r\n<TD width=232>\r\n<P><I><FONT face=Arial color=#330099>V únoru pojedu na hory.</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD borderColor=#ffff99 align=right width=137 bgColor=#ffff99>\r\n<P align=left><I><FONT face=Arial color=#330099>BŘEZEN</FONT></I></P></TD>\r\n<TD width=232>\r\n<P><I><FONT face=Arial color=#330099>V březnu budu studovat.</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD borderColor=#ffff99 align=right width=137 bgColor=#ffff99>\r\n<P align=left><I><FONT face=Arial color=#330099>DUBEN</FONT></I></P></TD>\r\n<TD width=232>\r\n<P><I><FONT face=Arial color=#330099>V dubnu budu hrát tenis.</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD borderColor=#ffff99 align=right width=137 bgColor=#ffff99>\r\n<P align=left><I><FONT face=Arial color=#330099>KVĚTEN</FONT></I></P></TD>\r\n<TD width=232>\r\n<P><I><FONT face=Arial color=#330099>V květnu budu jezdit na kole.</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD borderColor=#ffff99 align=right width=137 bgColor=#ffff99>\r\n<P align=left><I><FONT face=Arial color=#330099>ČERVEN</FONT></I></P></TD>\r\n<TD width=232>\r\n<P><I><FONT face=Arial color=#330099>V červnu budu plavat.</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD borderColor=#ffff99 align=right width=137 bgColor=#ffff99>\r\n<P align=left><I><FONT face=Arial color=#330099>ČERVENEC</FONT></I></P></TD>\r\n<TD width=232>\r\n<P><I><FONT face=Arial color=#330099>V červenci pojedu do Itálie.</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD borderColor=#ffff99 align=right width=137 bgColor=#ffff99>\r\n<P align=left><I><FONT face=Arial color=#330099>SRPEN</FONT></I></P></TD>\r\n<TD width=232>\r\n<P><I><FONT face=Arial color=#330099>V srpnu budu mít prázdniny.</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD borderColor=#ffff99 align=right width=137 bgColor=#ffff99>\r\n<P align=left><I><FONT face=Arial color=#330099>ZÁŘÍ</FONT></I></P></TD>\r\n<TD width=232>\r\n<P><I><FONT face=Arial color=#330099>V září budu chodit na túry.</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD borderColor=#ffff99 align=right width=137 bgColor=#ffff99>\r\n<P align=left><I><FONT face=Arial color=#330099>ŘÍJEN</FONT></I></P></TD>\r\n<TD width=232>\r\n<P><I><FONT face=Arial color=#330099>V říjnu pojedu do Paříe.&nbsp;</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD borderColor=#ffff99 align=right width=137 bgColor=#ffff99>\r\n<P align=left><I><FONT face=Arial color=#330099>LISTOPAD</FONT></I></P></TD>\r\n<TD width=232>\r\n<P><I><FONT face=Arial color=#330099>V listopadu budu hrát hokej.</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD borderColor=#ffff99 align=right width=137 bgColor=#ffff99>\r\n<P align=left><I><FONT face=Arial color=#330099>PROSINEC</FONT></I></P></TD>\r\n<TD width=232>\r\n<P><I><FONT face=Arial color=#330099>V prosinci budu kupovat dárky.</FONT></I></P></TD></TR></TBODY></TABLE>\r\n<P>\r\n<TABLE class=MsoNormalTable id=table7 style=\"BORDER-COLLAPSE: collapse\" cellSpacing=0 cellPadding=0 width=549 border=0>\r\n<TBODY>\r\n<TR>\r\n<TD style=\"BORDER-RIGHT: medium none; PADDING-RIGHT: 5.4pt; PADDING-LEFT: 5.4pt; PADDING-BOTTOM: 0in; PADDING-TOP: 0in\" vAlign=top borderColor=#f2f2f2 align=left width=184 bgColor=#b0c4de><FONT face=Arial color=#330099>Co bude dělat v lednu?</FONT></TD>\r\n<TD style=\"BORDER-RIGHT: medium none; PA