(2290, 1, 'u42/5', '', 58, '', '<H3><FONT color=#330099>Napite v budoucím čase.</FONT></H3>\r\n<TABLE cellSpacing=0 cellPadding=2 width=636 border=0>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=bottom borderColor=#f2f2f2 width=243 bgColor=#f2f2f2 colSpan=2>\r\n<P><FONT face=Arial color=#330099>Jana píe dopis.</FONT></P></TD>\r\n<TD vAlign=bottom borderColor=#b0c4de width=381 bgColor=#b0c4de>\r\n<P align=left><I><FONT face=Arial color=#330099>[$1,text 30:Jana bude psát dopis.]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom borderColor=#f2f2f2 width=243 bgColor=#f2f2f2 colSpan=2><FONT face=Arial color=#330099>Studujeme četinu.</FONT></TD>\r\n<TD vAlign=bottom borderColor=#b0c4de width=381 bgColor=#b0c4de>\r\n<P align=left><I><FONT face=Arial color=#330099>[$1,text 30:Budeme studovat četinu.]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom borderColor=#f2f2f2 width=243 bgColor=#f2f2f2 colSpan=2>\r\n<P><FONT face=Arial color=#330099>Dnes čteme zajímavou knihu.</FONT></P></TD>\r\n<TD vAlign=bottom borderColor=#b0c4de width=381 bgColor=#b0c4de>\r\n<P align=left><I><FONT face=Arial color=#330099>[$1,text 30:Dnes budeme číst zajímavou knihu.]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top borderColor=#f2f2f2 width=243 bgColor=#f2f2f2 colSpan=2>\r\n<P><FONT face=Arial color=#330099>Michalo, kdy jde do kina?</FONT></P></TD>\r\n<TD vAlign=bottom borderColor=#b0c4de width=381 bgColor=#b0c4de>\r\n<P align=left><I><FONT face=Arial color=#330099>[$1,text 30:Michalo, kdy půjde do kina?]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top borderColor=#f2f2f2 width=243 bgColor=#f2f2f2 colSpan=2>\r\n<P><FONT face=Arial color=#330099>Tomá a Petr snídají v 10 hodin.</FONT></P></TD>\r\n<TD vAlign=bottom borderColor=#b0c4de width=381 bgColor=#b0c4de>\r\n<P align=left><I><FONT face=Arial color=#330099>[$1,text 30:Tomá a Petr budou snídat v&nbsp;10 hodin.]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom borderColor=#f2f2f2 width=243 bgColor=#f2f2f2 colSpan=2>\r\n<P><FONT face=Arial color=#330099>Dnes mám četinu v 8 hodin.</FONT></P></TD>\r\n<TD vAlign=bottom borderColor=#b0c4de width=381 bgColor=#b0c4de>\r\n<P align=left><I><FONT face=Arial color=#330099>[$1,text 30:Dnes budeme mít četinu v&nbsp;osm hodin.]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom borderColor=#f2f2f2 width=243 bgColor=#f2f2f2 colSpan=2>\r\n<P><FONT face=Arial color=#330099>V kolik hodin večeříte?</FONT></P></TD>\r\n<TD vAlign=bottom borderColor=#b0c4de width=381 bgColor=#b0c4de>\r\n<P align=left><I><FONT face=Arial color=#330099>[$1,text 30:V kolik hodin budete večeřet?]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom borderColor=#f2f2f2 width=243 bgColor=#f2f2f2 colSpan=2>\r\n<P><FONT face=Arial color=#330099>Máme auto.</FONT></P></TD>\r\n<TD vAlign=bottom borderColor=#b0c4de width=381 bgColor=#b0c4de>\r\n<P align=left><I><FONT face=Arial color=#330099>[$1,text 30:Budeme mít auto.]</FONT></I></P></TD></TR></TBODY></TABLE>', 3, NULL),
(2291, 1, 'U42/4', '', 58, '', '<H3><FONT color=#330099>Doplňte budu, bude .... budou !</FONT></H3>\r\n<TABLE cellSpacing=0 cellPadding=2 width=808 border=0>\r\n<TBODY>\r\n<TR>\r\n<TD width=33 bgColor=#f2f2f2>\r\n<P><FONT face=Arial color=#330099>já</FONT></P></TD>\r\n<TD width=376 bgColor=#b0c4de>\r\n<P><I><FONT face=Arial color=#330099>[$1,text 12:Budu] pracovat jako manaer.</FONT></I></P></TD>\r\n<TD width=38 bgColor=#f2f2f2>\r\n<P><FONT face=Arial color=#330099>my</FONT></P></TD>\r\n<TD width=337 bgColor=#b0c4de>\r\n<P><I><FONT face=Arial color=#330099>V sobotu [$1,text 12:budeme] hrát fotbal.</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=33 bgColor=#f2f2f2>\r\n<P><FONT face=Arial color=#330099>ona</FONT></P></TD>\r\n<TD width=376 bgColor=#b0c4de>\r\n<P><I><FONT face=Arial color=#330099>Dominika [$1,text 12:bude] pracovat jako doktorka.</FONT></I></P></TD>\r\n<TD width=38 bgColor=#f2f2f2>\r\n<P><FONT face=Arial color=#330099>já</FONT></P></TD>\r\n<TD width=337 bgColor=#b0c4de>\r\n<P><I><FONT face=Arial color=#330099>Odpoledne se [$1,text 12:budu] učit.</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=33 bgColor=#f2f2f2>\r\n<P><FONT face=Arial color=#330099>my</FONT></P></TD>\r\n<TD width=376 bgColor=#b0c4de>\r\n<P><I><FONT face=Arial color=#330099>[$1,text 12:Budeme] studovat četinu.</FONT></I></P></TD>\r\n<TD width=38 bgColor=#f2f2f2>\r\n<P><FONT face=Arial color=#330099>oni</FONT></P></TD>\r\n<TD width=337 bgColor=#b0c4de>\r\n<P><FONT face=Arial color=#330099><I>Večer [$1,text 12:</I> <I>budou] jíst v&nbsp;restauraci.</I></FONT></P></TD></TR>\r\n<TR>\r\n<TD width=33 bgColor=#f2f2f2>\r\n<P><FONT face=Arial color=#330099>ty</FONT></P></TD>\r\n<TD width=376 bgColor=#b0c4de>\r\n<P><I><FONT face=Arial color=#330099>[$1,text 12:Bude] dělat domácí úkol?</FONT></I></P></TD>\r\n<TD width=38 bgColor=#f2f2f2>\r\n<P><FONT face=Arial color=#330099>ty</FONT></P></TD>\r\n<TD width=337 bgColor=#b0c4de>\r\n<P><I><FONT face=Arial color=#330099>[$1,text 12:Bude] čekat na Martinu?</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=33 bgColor=#f2f2f2>\r\n<P><FONT face=Arial color=#330099>oni</FONT></P></TD>\r\n<TD width=376 bgColor=#b0c4de>\r\n<P><I><FONT face=Arial color=#330099>[$1,text 12:Budou] cvičit gramatiku.</FONT></I></P></TD>\r\n<TD width=38 bgColor=#f2f2f2>\r\n<P><FONT face=Arial color=#330099>já</FONT></P></TD>\r\n<TD width=337 bgColor=#b0c4de>\r\n<P><I><FONT face=Arial color=#330099>Dneska [$1,text 12:budu] běhat v&nbsp;parku.</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=33 bgColor=#f2f2f2>\r\n<P><FONT face=Arial color=#330099>já</FONT></P></TD>\r\n<TD width=376 bgColor=#b0c4de>\r\n<P><I><FONT face=Arial color=#330099>O víkendu [$1,text 12:budu] jezdit na kole.</FONT></I></P></TD>\r\n<TD width=38 bgColor=#f2f2f2>\r\n<P><FONT face=Arial color=#330099>my</FONT></P></TD>\r\n<TD width=337 bgColor=#b0c4de>\r\n<P><I><FONT face=Arial color=#330099>V červenci [$1,text 12:budeme] mít prázdniny.</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=33 bgColor=#f2f2f2>\r\n<P><FONT face=Arial color=#330099>vy</FONT></P></TD>\r\n<TD width=376 bgColor=#b0c4de>\r\n<P><I><FONT face=Arial color=#330099>[$1,text 12:Budete] obědvat ?</FONT></I></P></TD>\r\n<TD width=38 bgColor=#f2f2f2>\r\n<P><FONT face=Arial color=#330099>vy</FONT></P></TD>\r\n<TD width=337 bgColor=#b0c4de>\r\n<P><I><FONT face=Arial color=#330099>[$1,text 12:Budete] se dívat na televizi?</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=33 bgColor=#f2f2f2>\r\n<P><FONT face=Arial color=#330099>oni</FONT></P></TD>\r\n<TD width=376 bgColor=#b0c4de>\r\n<P><I><FONT face=Arial color=#330099>[$1,text 12:Budou] odpočívat.</FONT></I></P></TD>\r\n<TD width=38 bgColor=#f2f2f2>\r\n<P><FONT face=Arial color=#330099>já</FONT></P></TD>\r\n<TD width=337 bgColor=#b0c4de>\r\n<P><I><FONT face=Arial color=#330099>[$1,text 12:Budu] psát dopis mamince.</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=33 bgColor=#f2f2f2>\r\n<P><FONT face=Arial color=#330099>ona</FONT></P></TD>\r\n<TD width=376 bgColor=#b0c4de>\r\n<P><I><FONT face=Arial color=#330099>Marta [$1,text 12:bude] pracovat jako manaerka.</FONT></I></P></TD>\r\n<TD width=38 bgColor=#f2f2f2>\r\n<P><FONT face=Arial color=#330099>on</FONT></P></TD>\r\n<TD width=337 bgColor=#b0c4de>\r\n<P><I><FONT face=Arial color=#330099>[$1,text 12:Bude] číst noviny.</FONT></I></P></TD></TR></TBODY></TABLE>', 3, NULL),
(2292, 1, 'U42/6', '', 58, '', '<H3><FONT color=#330099>Napite v budoucím čase.</FONT></H3>\r\n<TABLE borderColor=#ffffff cellSpacing=0 cellPadding=2 bgColor=#b0c4de border=0>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=bottom borderColor=#f2f2f2 width=213 bgColor=#f2f2f2>\r\n<P><FONT face=Arial color=#330099>Jela jsem do Vídně.</FONT></P></TD>\r\n<TD vAlign=bottom width=478>\r\n<P align=left><I><FONT color=#330099>[$1,text 30:Pojedu do Vídně.]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top borderColor=#f2f2f2 width=213 bgColor=#f2f2f2>\r\n<P><FONT face=Arial color=#330099>Hráli jsme tenis.</FONT></P></TD>\r\n<TD vAlign=bottom width=478>\r\n<P align=left><I><FONT color=#330099>[$1,text 30:Budeme hrát tenis.]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom borderColor=#f2f2f2 width=213 bgColor=#f2f2f2>\r\n<P><FONT face=Arial color=#330099>Kdy jsi obědval?</FONT></P></TD>\r\n<TD vAlign=bottom width=478>\r\n<P align=left><I><FONT color=#330099>[$1,text 30:Kdy bude obědvat?]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom borderColor=#f2f2f2 width=213 bgColor=#f2f2f2>\r\n<P><FONT face=Arial color=#330099>Diskutovali jste o historii?</FONT></P></TD>\r\n<TD vAlign=bottom width=478>\r\n<P align=left><I><FONT color=#330099>[$1,text 30:Budeme diskutovat o historii.]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top borderColor=#f2f2f2 width=213 bgColor=#f2f2f2>\r\n<P><FONT face=Arial color=#330099>Museli běhat v&nbsp;parku.</FONT></P></TD>\r\n<TD vAlign=bottom width=478>\r\n<P align=left><I><FONT color=#330099>[$1,text 30:Budou muset běhat v&nbsp;parku.]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top borderColor=#f2f2f2 width=213 bgColor=#f2f2f2>\r\n<P><FONT face=Arial color=#330099>Nejedl jsem na koleji.</FONT></P></TD>\r\n<TD vAlign=bottom width=478>\r\n<P align=left><I><FONT color=#330099>[$1,text 30:Nebudu jíst na koleji.]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom borderColor=#f2f2f2 width=213 bgColor=#f2f2f2>\r\n<P><FONT face=Arial color=#330099>Spala v hotelu.</FONT></P></TD>\r\n<TD vAlign=bottom width=478>\r\n<P align=left><I><FONT color=#330099>[$1,text 30:Bude spát v&nbsp;hotelu.]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom borderColor=#f2f2f2 width=213 bgColor=#f2f2f2>\r\n<P><FONT face=Arial color=#330099>la jsi na koncert?</FONT></P></TD>\r\n<TD vAlign=bottom width=478>\r\n<P align=left><I><FONT color=#330099>[$1,text 30:Půjde na koncert?]</FONT></I></P></TD></TR></TBODY></TABLE>', 3, NULL),
(2293, 1, 'U42/7', '', 58, '', '<H3><FONT color=#330099>Napite, co bude zítra!</FONT></H3>\r\n<TABLE cellSpacing=0 cellPadding=2 border=0>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=bottom width=265 bgColor=#f2f2f2>\r\n<P align=left><FONT face=Arial color=#330099>Jsem ve kole.</FONT></P></TD>\r\n<TD vAlign=bottom width=426 bgColor=#b0c4de>\r\n<P align=left><I><FONT face=Arial color=#330099>[$1, text 30:Zítra budu ve kole.</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=265 bgColor=#f2f2f2>\r\n<P align=left><FONT face=Arial color=#330099>Jdu na nádraí.</FONT></P></TD>\r\n<TD vAlign=bottom width=426 bgColor=#b0c4de>\r\n<P align=left><I><FONT face=Arial color=#330099>[$1,text 30:Zítra půjdu na nádraí.]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=265 bgColor=#f2f2f2>\r\n<P align=left><FONT face=Arial color=#330099>Jdu do kina.</FONT></P></TD>\r\n<TD vAlign=bottom width=426 bgColor=#b0c4de>\r\n<P align=left><I><FONT face=Arial color=#330099>[$1,text 30:Zítra půjdu do kina.]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=265 bgColor=#f2f2f2>\r\n<P align=left><FONT face=Arial color=#330099>Kde je Petra?</FONT></P></TD>\r\n<TD vAlign=bottom width=426 bgColor=#b0c4de>\r\n<P align=left><I><FONT face=Arial color=#330099>[$1,text 30:Kde bude zítra Petra?]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=265 bgColor=#f2f2f2>\r\n<P align=left><FONT face=Arial color=#330099>Co je dnes v televizi?</FONT></P></TD>\r\n<TD vAlign=bottom width=426 bgColor=#b0c4de>\r\n<P align=left><I><FONT face=Arial color=#330099>[$1,text 30:Co bude zítra v&nbsp;televizi?]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=265 bgColor=#f2f2f2>\r\n<P align=left><FONT face=Arial color=#330099>Dnes je hezké počasí.</FONT></P></TD>\r\n<TD vAlign=bottom width=426 bgColor=#b0c4de>\r\n<P align=left><I><FONT face=Arial color=#330099>[$1,text 30:Zítra bude hezké počasí.]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=265 bgColor=#f2f2f2>\r\n<P align=left><FONT face=Arial color=#330099>Jdu na procházku.</FONT></P></TD>\r\n<TD vAlign=bottom width=426 bgColor=#b0c4de>\r\n<P align=left><I><FONT face=Arial color=#330099>[$1,text 30:Zítra půjdu na procházku.]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=265 bgColor=#f2f2f2>\r\n<P align=left><FONT face=Arial color=#330099>Jdou na výlet.</FONT></P></TD>\r\n<TD vAlign=bottom width=426 bgColor=#b0c4de>\r\n<P align=left><I><FONT face=Arial color=#330099>[$1,text 30:Zítra půjdou na výlet.]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=265 bgColor=#f2f2f2>\r\n<P align=left><FONT face=Arial color=#330099>Petr jde do koly.</FONT></P></TD>\r\n<TD vAlign=bottom width=426 bgColor=#b0c4de>\r\n<P align=left><I><FONT face=Arial color=#330099>[$1,text 30:Zítra půjde Petr do koly.]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=265 bgColor=#f2f2f2>\r\n<P align=left><FONT face=Arial color=#330099>Martin tady není.</FONT></P></TD>\r\n<TD vAlign=bottom width=426 bgColor=#b0c4de>\r\n<P align=left><I><FONT face=Arial color=#330099>[$1,text 30:Zítra tady Martin nebude.]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=265 bgColor=#f2f2f2>\r\n<P align=left><FONT face=Arial color=#330099>Dane, jde do restaurace?</FONT></P></TD>\r\n<TD vAlign=bottom width=426 bgColor=#b0c4de>\r\n<P align=left><I><FONT face=Arial color=#330099>[$1,text 30:Dane, půjde zítra do restaurace?]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=265 bgColor=#f2f2f2>\r\n<P align=left><FONT face=Arial color=#330099>Hana, Anna a Michal jdou na večeři.</FONT></P></TD>\r\n<TD vAlign=bottom width=426 bgColor=#b0c4de>\r\n<P align=left><I><FONT face=Arial color=#330099>[$1,text 30:Zítra půjdou Hana, Anna a Michal na večeři.]</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=265 bgColor=#f2f2f2>\r\n<P align=left><FONT face=Arial color=#330099>Dnes nejdu do hospody.</FONT></P></TD>\r\n<TD vAlign=bottom width=426 bgColor=#b0c4de>\r\n<P align=left><I><FONT face=Arial color=#330099>[$1,text 30:Zítra nepůjdu do hospody.]</FONT></I></P></TD></TR></TBODY></TABLE>', 3, NULL),
(2294, 1, 'U42/8', '', 58, '', '<H3><FONT color=#330099>Včera, dneska a zítra</FONT></H3>\r\n<TABLE borderColor=#ffffff cellSpacing=0 cellPadding=2 border=1>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=bottom borderColor=#b0c4de width=187>\r\n<P align=left><FONT color=#330099><IMG height=91 src=\"http://www.bohemica.com/tuit/img/textbook/bh-image006.gif\" width=118></FONT></P></TD>\r\n<TD width=511 bgColor=#b0c4de>\r\n<P align=left><I><FONT color=#330099>Včera Jim [$1,text 15:spal].</FONT></I></P>\r\n<P align=left><I><FONT color=#330099>Dneska [$1,text 15:spí].</FONT></I></P>\r\n<P align=left><I><FONT color=#330099>Zítra [$1,text 15:bude spát].</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom borderColor=#b0c4de width=187>\r\n<P align=right><FONT color=#330099><IMG height=86 src=\"http://www.bohemica.com/tuit/img/textbook/bh-image008.gif\" width=108></P></FONT></TD>\r\n<TD width=511 bgColor=#b0c4de>\r\n<P align=left><I><FONT color=#330099>Včera babička [$1,text 15:četla].</FONT></I></P>\r\n<P align=left><I><FONT color=#330099>Dneska [$1,text 15:čte].</FONT></I></P>\r\n<P align=left><I><FONT color=#330099>Zítra [$1,text 15:bude číst].</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom borderColor=#b0c4de width=187>\r\n<P align=left><FONT color=#330099><IMG height=85 src=\"http://www.bohemica.com/tuit/img/textbook/bh-image010.gif\" width=103></FONT></P></TD>\r\n<TD width=511 bgColor=#b0c4de>\r\n<P align=left><I><FONT color=#330099>Včera Martin [$1,text 15:snídal].</FONT></I></P>\r\n<P align=left><I><FONT color=#330099>Dneska [$1,text 15:snídá].</FONT></I></P>\r\n<P align=left><I><FONT color=#330099>Zítra [$1,text 15:bude snídat].</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom borderColor=#b0c4de width=187>\r\n<P align=right><FONT color=#330099><IMG height=87 src=\"http://www.bohemica.com/tuit/img/textbook/bh-image012.gif\" width=107></FONT></P></TD>\r\n<TD width=511 bgColor=#b0c4de>\r\n<P align=left><I><FONT color=#330099>Včera [$1,text 15:se] babička [$1,text 15:dívala] na televizi.</FONT></I></P>\r\n<P align=left><I><FONT color=#330099>Dneska [$1,text 15:se dívá] na televizi.</FONT></I></P>\r\n<P align=left><I><FONT color=#330099>Zítra [$1,text 15:se bude dívat] na televizi.</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom borderColor=#b0c4de width=187>\r\n<P align=left><FONT color=#330099><IMG height=87 src=\"http://www.bohemica.com/tuit/img/textbook/bh-image014.gif\" width=113></FONT></P></TD>\r\n<TD width=511 bgColor=#b0c4de>\r\n<P align=left><I><FONT color=#330099>Včera Honza [$1,text 15:hrál] fotbal.</FONT></I></P>\r\n<P align=left><I><FONT color=#330099>Dneska [$1,text 15:hraje] fotbal.</FONT></I></P>\r\n<P align=left><I><FONT color=#330099>Zítra [$1,text 15:bude hrát] fotbal.</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom borderColor=#b0c4de width=187>\r\n<P align=right><FONT color=#330099><IMG height=88 src=\"http://www.bohemica.com/tuit/img/textbook/bh-image016.gif\" width=117></FONT></P></TD>\r\n<TD width=511 bgColor=#b0c4de>\r\n<P align=left><I><FONT color=#330099>Včera Jim [$1,text 15:studoval].</FONT></I></P>\r\n<P align=left><I><FONT color=#330099>Dneska [$1,text 15:studuje].</FONT></I></P>\r\n<P align=left><I><FONT color=#330099>Zítra [$1,text 15:bude studovat].</FONT></I></P></TD></TR></TBODY></TABLE>', 3, NULL),
