(2316, 1, 'U45/5', '', 49, '', '<p class=\"MsoNormal\" align=\"left\"><b><font color=\"#330099\" size=\"4\">Odpovězte!</font>\r\n</b>\r\n</p>\r\n<div align=\"left\"><table id=\"table22\" bgcolor=\"#b0c4de\"><tbody><tr><td width=\"95\" bgcolor=\"#ffffff\"><p align=\"center\"><i><font color=\"#330099\"><img height=\"59\" src=http://www.bohemica.com/tuit/img/textbook/bl-acimage028.gif width=\"68\" />\r\n </font>\r\n</i>\r\n</p>\r\n</td>\r\n<td width=\"208\"><i><font face=\"Arial\" color=\"#330099\">Co ho bolí?</font>\r\n</i>\r\n<p></p>\r\n<p><i><font face=\"Arial\" color=\"#330099\">[$1,text 20:Bolí ho záda.]</font>\r\n</i>\r\n</p>\r\n</td>\r\n<td width=\"114\" bgcolor=\"#ffffff\"><p align=\"center\"><i><font face=\"Arial\" color=\"#330099\"><img height=\"65\" src=\"http://www.bohemica.com/tuit/img/textbook/bl-acimage029.gif\" width=\"92\" />\r\n </font>\r\n</i>\r\n</p>\r\n</td>\r\n<td width=\"183\"><i><font face=\"Arial\" color=\"#330099\">Co ji bolí?</font>\r\n</i>\r\n<p></p>\r\n<p><i><font face=\"Arial\" color=\"#330099\">[$1,text 20:Bolí ji záda.]</font>\r\n</i>\r\n</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n<p class=\"MsoNormal\" align=\"left\"><b><font color=\"#330099\" size=\"4\">Odpovězte!</font>\r\n</b>\r\n</p>\r\n<div align=\"left\"><table id=\"table23\" cellpadding=\"2\" width=\"616\" bgcolor=\"#b0c4de\"><tbody><tr><td valign=\"bottom\" width=\"199\" bgcolor=\"#ffffff\"><p align=\"center\"><i><font color=\"#330099\"><img height=\"64\" src=http://www.bohemica.com/tuit/img/textbook/bl-acimage030.gif width=\"75\" />\r\n &nbsp;&nbsp;&nbsp; <img height=\"56\" src=http://www.bohemica.com/tuit/img/textbook/acimage031.gif width=\"96\" />\r\n </font>\r\n</i>\r\n</p>\r\n</td>\r\n<td width=\"402\"><p align=\"center\"><i><font face=\"Arial\" color=\"#330099\">Co je bolí?</font>\r\n</i>\r\n</p>\r\n<p align=\"center\"></p>\r\n<p align=\"center\"><i><font face=\"Arial\" color=\"#330099\">[$1,text 20:Bolí je noha a záda.]</font>\r\n</i>\r\n</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>', 3, NULL),
(2317, 1, 'U45/6', '', 58, '', '<P class=MsoNormal align=left><B><FONT color=#330099 size=4>Doplňte!</FONT></B></P>\r\n<DIV align=left>\r\n<TABLE id=table22 cellPadding=2 bgColor=#b0c4de>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=top width=246>\r\n<P align=center><I><FONT color=#330099>Čekám na Janu.</FONT></I></P></TD>\r\n<TD vAlign=top width=237>\r\n<P align=center><I><FONT color=#330099>Jano, čekáme na [$1,text 5:tebe].</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=246>\r\n<P align=center><I><FONT color=#330099>Čekám na Karla.</FONT></I></P></TD>\r\n<TD vAlign=top width=237>\r\n<P align=center><I><FONT color=#330099>Karle, čekám na [$1,text 5:tebe].</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=246>\r\n<P align=center><I><FONT color=#330099>Čekám na rodiče.</FONT></I></P></TD>\r\n<TD vAlign=top width=237>\r\n<P align=center><I><FONT color=#330099>Tati, mami čekáme na [$1,text 5:vás].</FONT></I></P></TD></TR></TBODY></TABLE></DIV>', 3, NULL),
(2318, 1, 'U45/7', '', 58, '', '&nbsp;\r\n<P class=MsoNormal align=left><FONT color=#330099 size=4><B>Doplňte </B><I>mě, tě, ho, ji, to, nás, vás, je</I>!</FONT></P>\r\n<TABLE id=table22 cellPadding=2 width=387 bgColor=#b0c4de>\r\n<TBODY>\r\n<TR>\r\n<TD width=286>\r\n<P align=left><I><FONT face=Arial color=#330099>Mám [$1,text 5:tě] rád.</FONT></I></P></TD>\r\n<TD width=87 bgColor=#f2f2f2>\r\n<P align=left><I><FONT face=Arial color=#330099>ty</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=286>\r\n<P align=left><I><FONT face=Arial color=#330099>Koupím pro [$1,text 5:ni] dárek.</FONT></I></P></TD>\r\n<TD width=87 bgColor=#f2f2f2>\r\n<P align=left><I><FONT face=Arial color=#330099>ona</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=286>\r\n<P align=left><I><FONT face=Arial color=#330099>Čekám na [$1,text 5:ně].</FONT></I></P></TD>\r\n<TD width=87 bgColor=#f2f2f2>\r\n<P align=left><I><FONT face=Arial color=#330099>oni</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=286>\r\n<P align=left><I><FONT face=Arial color=#330099>Mám pro [$1,text 5:něho] ten slovník.</FONT></I></P></TD>\r\n<TD width=87 bgColor=#f2f2f2>\r\n<P align=left><I><FONT face=Arial color=#330099>on</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=286>\r\n<P align=left><I><FONT face=Arial color=#330099>Koupím si [$1,text 5:ho].</FONT></I></P></TD>\r\n<TD width=87 bgColor=#f2f2f2>\r\n<P align=left><I><FONT face=Arial color=#330099>ten chleba</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=286>\r\n<P align=left><I><FONT face=Arial color=#330099>Znám [$1,text 5:ji].</FONT></I></P></TD>\r\n<TD width=87 bgColor=#f2f2f2>\r\n<P align=left><I><FONT face=Arial color=#330099>ona</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=286>\r\n<P align=left><I><FONT face=Arial color=#330099>Eva na [$1,text 5:nás] čeká.</FONT></I></P></TD>\r\n<TD width=87 bgColor=#f2f2f2>\r\n<P align=left><I><FONT face=Arial color=#330099>my</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=286>\r\n<P align=left><I><FONT face=Arial color=#330099>Čtu [$1,text 5:ho].</FONT></I></P></TD>\r\n<TD width=87 bgColor=#f2f2f2>\r\n<P align=left><I><FONT face=Arial color=#330099>časopis</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=286>\r\n<P align=left><I><FONT face=Arial color=#330099>Nekoupím si [$1,text 5:ji].</FONT></I></P></TD>\r\n<TD width=87 bgColor=#f2f2f2>\r\n<P align=left><I><FONT face=Arial color=#330099>tu knihu</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=286>\r\n<P align=left><I><FONT face=Arial color=#330099>Navtívím [$1,text 5:ho].</FONT></I></P></TD>\r\n<TD width=87 bgColor=#f2f2f2>\r\n<P align=left><I><FONT face=Arial color=#330099>on</FONT></I></P></TD></TR></TBODY></TABLE>', 3, NULL),
(2319, 1, 'U45/8', '', 58, '', '<DIV align=left>\r\n<DIV align=left>\r\n<P class=MsoNormal align=left><B><FONT color=#330099 size=4>Doplňte!</FONT></B></P></DIV></DIV>\r\n<TABLE id=table22 cellPadding=2 bgColor=#b0c4de>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=top width=321><I><FONT color=#330099>To je pan Hlavatý. Znáte [$1,text 5:ho]?</FONT></I>\r\n<P><I><FONT color=#330099>To je dárek pro [$1,text 5:Vás], paní Čermáková!</FONT></I></P>\r\n<P><I><FONT color=#330099>Navtívíme [$1,text 5:Tě] , Jano.</FONT></I></P>\r\n<P><I><FONT color=#330099>Navtívíme [$1,text 5:Vás], Jano a Tomái.</FONT></I></P>\r\n<P><I><FONT color=#330099>To jsou Američané. Včera jsem [$1,text 5:je] viděla na náměstí.</FONT></I></P></TD>\r\n<TD vAlign=top width=321><I><FONT color=#330099>Tamhle jde Katka. vidí [$1,text 5:ji]?</FONT></I>\r\n<P><I><FONT color=#330099>To jsou moji kamarádi. Často na [$1,text 5:ně] myslím.</FONT></I></P>\r\n<P><I><FONT color=#330099>Jdeme domů. Nae děti [$1,text 5:nás] potřebují.</FONT></I></P>\r\n<P><I><FONT color=#330099>Kde je Pavel? Čekám na [$1,text 5:něj] u půl hodiny.</FONT></I></P>\r\n<P><I><FONT color=#330099>Psal u jsi tu esej? Ne, teď [$1,text 5:ji] píu.</FONT></I></P></TD></TR></TBODY></TABLE>', 3, NULL),
(2320, 1, 'U45/9', '', 49, '', '&nbsp; <table id=\"table23\" cellspacing=\"2\" cellpadding=\"2\" bgcolor=\"#ffffcc\" border=\"0\"><tbody><tr><td valign=\"top\" width=\"761\" colspan=\"2\"><h3 align=\"left\"><font color=\"#330099\">Anička je nemocná</font>\r\n </h3>\r\n<p align=\"left\"><i><font color=\"#330099\">O víkendu byla Anička v Tatrách. Kdy ve čtvrtek odjíděla z&nbsp;Prahy, bylo hezké počasí. Svítilo slunce a nebyla velká zima. Na Slovensku bylo chladněji a v&nbsp;sobotu ji překvapil sníh. Anička neměla moc teplé oblečení a nastydla.</font>\r\n </i>\r\n</p>\r\n<p align=\"left\"><i><font color=\"#330099\">Do Prahy se vrátila včera odpoledne a hned si lehla do postele, protoe se necítila dobře. V&nbsp;noci moc nespala, bolelo ji v&nbsp;krku a byla jí zima.</font>\r\n </i>\r\n</p>\r\n<p align=\"left\"><i><font color=\"#330099\">Dnes ráno má teplotu 38,7°C a kale,tak musí jít k&nbsp;doktorovi. Nejdřív telefonuje do koly a omlouvá se, e je nemocná. Potom jde k&nbsp;lékaři.</font>\r\n </i>\r\n</p>\r\n<p align=\"left\"><i><font color=\"#330099\">Anička má chřipku. Bude muset leet v&nbsp;posteli, pít čaj s&nbsp;citrónem, jíst hodně vitamínů. Kdy bude mít horečku, bude si brát paralen. </font>\r\n</i>\r\n</p>\r\n</td>\r\n</tr>\r\n<tr><td valign=\"top\" width=\"370\" bgcolor=\"#ffffff\"><p align=\"center\"><font color=\"#330099\"><img height=\"264\" src=\"http://www.bohemica.com/tuit/img/textbook/bl-acimage034.gif\" width=\"330\" />\r\n </font>\r\n</p>\r\n</td>\r\n<td valign=\"top\" width=\"391\" bgcolor=\"#ffffff\"><p align=\"center\"><font color=\"#330099\"><img height=\"262\" src=\"/tuit/img/textbook/bl-acimage036.gif\" width=\"328\" />\r\n </font>\r\n</p>\r\n</td>\r\n</tr>\r\n<tr><td valign=\"top\" width=\"370\" bgcolor=\"#ffffff\"><p align=\"center\"><font color=\"#330099\"><img height=\"277\" src=\"/tuit/img/textbook/bl-acimage038.gif\" width=\"334\" />\r\n </font>\r\n</p>\r\n</td>\r\n<td valign=\"top\" width=\"391\" bgcolor=\"#ffffff\"><p align=\"center\"><font color=\"#330099\"><img height=\"277\" src=\"/tuit/img/textbook/bl-acimage040.gif\" width=\"352\" />\r\n </font>\r\n</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<h3><font color=\"#330099\">Zeptejte se!</font>\r\n </h3>\r\n<table id=\"table22\" cellpadding=\"2\" width=\"546\" bgcolor=\"#b0c4de\"><tbody><tr><td align=\"left\" width=\"326\"><i><font face=\"Arial\" color=\"#330099\">[$1,text 40]</font>\r\n </i>\r\n</td>\r\n<td align=\"left\" width=\"206\"><i><font face=\"Arial\" color=\"#330099\">V Tatrách.</font>\r\n </i>\r\n</td>\r\n</tr>\r\n<tr><td align=\"left\" width=\"326\"><font face=\"Arial\" color=\"#330099\"><i>[$1,text 40]</i>\r\n </font>\r\n</td>\r\n<td align=\"left\" width=\"206\"><i><font face=\"Arial\" color=\"#330099\">Bylo chladno a sněilo.</font>\r\n </i>\r\n</td>\r\n</tr>\r\n<tr><td align=\"left\" width=\"326\"><font face=\"Arial\" color=\"#330099\"><i>[$1,text 40]</i>\r\n </font>\r\n</td>\r\n<td align=\"left\" width=\"206\"><i><font face=\"Arial\" color=\"#330099\">V neděli odpoledne.</font>\r\n </i>\r\n</td>\r\n</tr>\r\n<tr><td align=\"left\" width=\"326\"><font face=\"Arial\" color=\"#330099\"><i>[$1,text 40]</i>\r\n </font>\r\n</td>\r\n<td align=\"left\" width=\"206\"><i><font face=\"Arial\" color=\"#330099\">Protoe se necítila dobře.</font>\r\n </i>\r\n</td>\r\n</tr>\r\n<tr><td align=\"left\" width=\"326\"><font face=\"Arial\" color=\"#330099\"><i>[$1,text 40]</i>\r\n </font>\r\n</td>\r\n<td align=\"left\" width=\"206\"><i><font face=\"Arial\" color=\"#330099\">Bolí mě v&nbsp;krku a je mi zima.</font>\r\n </i>\r\n</td>\r\n</tr>\r\n<tr><td align=\"left\" width=\"326\"><font face=\"Arial\" color=\"#330099\"><i>[$1,text 40]</i>\r\n </font>\r\n</td>\r\n<td align=\"left\" width=\"206\"><i><font face=\"Arial\" color=\"#330099\">Jsem nemocná.</font>\r\n </i>\r\n</td>\r\n</tr>\r\n<tr><td align=\"left\" width=\"326\"><font face=\"Arial\" color=\"#330099\"><i>[$1,text 40]</i>\r\n </font>\r\n</td>\r\n<td align=\"left\" width=\"206\"><i><font face=\"Arial\" color=\"#330099\">Mám chřipku.</font>\r\n </i>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n', 3, NULL),
(2321, 1, 'U45/10', '', 49, '', '&nbsp;<h3><font color=\"#330099\">Odpovězte!</font>\r\n</h3>\r\n<table id=\"table23\" cellpadding=\"2\" bgcolor=\"#b0c4de\"><tbody><tr><td valign=\"top\" align=\"center\"><font color=\"#330099\">[$1,text 20:Bolí mě břicho.]<br />\r\n&nbsp;</font>\r\n</td>\r\n<td valign=\"top\" align=\"center\"><font color=\"#330099\">[$1,text 20:Bolí mě hlava.]<br />\r\n&nbsp;</font>\r\n</td>\r\n</tr>\r\n<tr><td valign=\"top\" width=\"298\" bgcolor=\"#ffffff\"><p align=\"center\"><font color=\"#330099\"><img height=\"248\" src=http://www.bohemica.com/tuit/img/textbook/bl-acimage049.gif width=\"309\" />\r\n</font>\r\n</p>\r\n</td>\r\n<td valign=\"top\" width=\"297\" bgcolor=\"#ffffff\"><font color=\"#330099\"><img height=\"244\" src=\"http://www.bohemica.com/tuit/img/textbook/bl-acimage051.gif\" width=\"290\" />\r\n</font>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>', 3, NULL),
(2322, 1, 'U45/11', '', 58, '', '<H3><FONT color=#330099>Vyberte správnou odpověď!</FONT></H3>\r\n<TABLE id=table23 cellPadding=2 bgColor=#b0c4de>\r\n<TBODY>\r\n<TR>\r\n<TD width=614 bgColor=#f2f2f2 colSpan=2><I><FONT color=#330099>Je mi patně. Záda. Jsem unavený. Není mi dobře. Jsem nemocný. Hlava. Docela dobře.</FONT></I></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=137><I><FONT color=#330099>Jak se cítíte?</FONT></I></TD>\r\n<TD vAlign=bottom width=477><I><FONT color=#330099>[$1, text 50:Je mi patně. Jsem unavený. Není mi dobře. Docele dobře.]</FONT></I></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=137><I><FONT color=#330099>Co je Vám?</FONT></I></TD>\r\n<TD vAlign=bottom width=477><I><FONT color=#330099>[$1, text 50:Jsem unavený. Jsem nemocný.] </FONT></I></TD></TR>\r\n<TR>\r\n<TD vAlign=bottom width=137><I><FONT color=#330099>Co Vás bolí?</FONT></I></TD>\r\n<TD vAlign=bottom width=477><I><FONT color=#330099>[$1, text 50:Záda. Hlava.]</FONT></I></TD></TR></TBODY></TABLE>', 3, NULL),
(2323, 1, 'U45/12', '', 58, '', '<H3><FONT color=#330099>Co je tam patně?</FONT></H3>\r\n<TABLE id=table23 cellPadding=2 bgColor=#b0c4de>\r\n<TBODY>\r\n<TR>\r\n<TD width=52 bgColor=#f2f2f2>\r\n<P align=center><I><B><FONT color=#330099>A</FONT></B></I></P></TD>\r\n<TD width=166 colSpan=2><I><FONT color=#330099><B>1.</B>Bolí mě hlava.</FONT></I></TD>\r\n<TD width=166 colSpan=2><I><FONT color=#330099><B>2.</B>Bolí mě ruka.</FONT></I></TD>\r\n<TD width=166 colSpan=2><I><FONT color=#330099><B>3.</B>Bolí mě teplotu.</FONT></I></TD>\r\n<TD width=166 colSpan=2><I><FONT color=#330099><B>4.</B>Bolí mě noha.</FONT></I></TD></TR>\r\n<TR>\r\n<TD width=52 bgColor=#f2f2f2>\r\n<P align=center><I><B><FONT color=#330099>B</FONT></B></I></P></TD>\r\n<TD width=166 colSpan=2><I><FONT color=#330099><B>1.</B>Máte vitamín A?</FONT></I></TD>\r\n<TD width=166 colSpan=2><I><FONT color=#330099><B>2.</B>Máte vitamín C ?</FONT></I></TD>\r\n<TD width=166 colSpan=2><I><FONT color=#330099><B>3.</B>Máte vitamín B ?</FONT></I></TD>\r\n<TD width=166 colSpan=2><I><FONT color=#330099><B>4.</B>Máte vitamín 2?</FONT></I></TD></TR>\r\n<TR>\r\n<TD width=52 bgColor=#f2f2f2>\r\n<P align=center><I><B><FONT color=#330099>C</FONT></B></I></P></TD>\r\n<TD width=166 colSpan=2><I><FONT color=#330099><B>1.</B>Mám rýmu.</FONT></I></TD>\r\n<TD width=166 colSpan=2><I><FONT color=#330099><B>2.</B>Mám kael.</FONT></I></TD>\r\n<TD width=166 colSpan=2><I><FONT color=#330099><B>3.</B>Mám nohu.</FONT></I></TD>\r\n<TD width=166 colSpan=2><I><FONT color=#330099><B>4.</B>Mám teplotu.</FONT></I></TD></TR>\r\n<TR>\r\n<TD width=52 bgColor=#f2f2f2>\r\n<P align=center><I><B><FONT color=#330099>D</FONT></B></I></P></TD>\r\n<TD width=166 colSpan=2><I><FONT color=#330099><B>1.</B>Hlava.</FONT></I></TD>\r\n<TD width=166 colSpan=2><I><FONT color=#330099><B>2.</B>Teplota.</FONT></I></TD>\r\n<TD width=166 colSpan=2><I><FONT color=#330099><B>3.</B>Rýma.</FONT></I></TD>\r\n<TD width=166 colSpan=2><I><FONT color=#330099><B>4.</B>Chřipka.</FONT></I></TD></TR>\r\n<TR>\r\n<TD width=52 bgColor=#f2f2f2>\r\n<P align=center><I><B><FONT color=#330099>E</FONT></B></I></P></TD>\r\n<TD width=166 colSpan=2><I><FONT color=#330099><B>1.</B>Co je Vám?</FONT></I></TD>\r\n<TD width=166 colSpan=2><I><FONT color=#330099><B>2.</B>Kolik je Vám let?</FONT></I></TD>\r\n<TD width=166 colSpan=2><I><FONT color=#330099><B>3.</B>Co Vás bolí?</FONT></I></TD>\r\n<TD width=166 colSpan=2><I><FONT color=#330099><B>4.</B>Jak se cítíte?</FONT></I></TD></TR>\r\n<TR>\r\n<TD style=\"BORDER-RIGHT: #c8d7f0 1px solid; BORDER-TOP: #c8d7f0 1px solid; BORDER-LEFT: #c8d7f0 1px solid; BORDER-BOTTOM: #c8d7f0 1px solid\" width=143 bgColor=#f2f2f2 colSpan=2 height=59>\r\n<P align=center><I><FONT color=#330099><B>A </B>[$1, select:/1/2/(3/4]</FONT></I></P></TD>\r\n<TD style=\"BORDER-RIGHT: #c8d7f0 1px solid; BORDER-TOP: #c8d7f0 1px solid; BORDER-LEFT: #c8d7f0 1px solid; BORDER-BOTTOM: #c8d7f0 1px solid\" width=143 bgColor=#f2f2f2 colSpan=2 height=59>\r\n<P align=center><I><FONT color=#330099><B>B&nbsp;</B>[$1, select:/1/2/3/(4]</FONT></I></P></TD>\r\n<TD style=\"BORDER-RIGHT: #c8d7f0 1px solid; BORDER-TOP: #c8d7f0 1px solid; BORDER-LEFT: #c8d7f0 1px solid; BORDER-BOTTOM: #c8d7f0 1px solid\" width=143 bgColor=#f2f2f2 colSpan=2 height=59>\r\n<P align=center><I><FONT color=#330099><B>C&nbsp;</B>[$1, select:/1/2/(3/4]</FONT></I></P></TD>\r\n<TD style=\"BORDER-RIGHT: #c8d7f0 1px solid; BORDER-TOP: #c8d7f0 1px solid; BORDER-LEFT: #c8d7f0 1px solid; BORDER-BOTTOM: #c8d7f0 1px solid\" width=143 bgColor=#f2f2f2 colSpan=2 height=59>\r\n<P align=center><I><FONT color=#330099><B>D&nbsp;</B>[$1, select:/(1/2/3/4]</FONT></I></P></TD>\r\n<TD style=\"BORDER-RIGHT: #c8d7f0 1px solid; BORDER-TOP: #c8d7f0 1px solid; BORDER-LEFT: #c8d7f0 1px solid; BORDER-BOTTOM: #c8d7f0 1px solid\" width=143 bgColor=#f2f2f2 height=59>\r\n<P align=center><I><FONT color=#330099><B>E&nbsp;</B>[$1, select:/(1/2/3/4]</FONT></I></P></TD></TR></TBODY></TABLE>', 3, NULL),
(2324, 1, 'U45/1', '', 58, '', '<H1><FONT color=#330099>Aktivity zítra</FONT></H1>\r\n<P align=center><I>&nbsp;</I><IMG height=88 src=\"http://www.bohemica.com/tuit/img/textbook/bk-abimage001.gif\" width=594 align=left> </P>\r\n<P align=left><I></I>&nbsp;</P>\r\n<P align=left>&nbsp;</P>\r\n<P align=center><FONT color=#000080 size=4><B><I>Naobědváme se.</I></B></FONT></P>\r\n<TABLE id=table22 borderColor=#000080 cellSpacing=0 cellPadding=2 width=585 border=1>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=top width=577 colSpan=4>\r\n<P align=right><FONT color=#000080><IMG height=82 src=\"http://www.bohemica.com/tuit/img/textbook/bk-abimage002.gif\" width=576></FONT></P></TD></TR>\r\n<TR>\r\n<TD style=\"BORDER-BOTTOM: medium none\" align=middle width=146><FONT color=#000080><B><U>o</U></B>sprchovat se</FONT></TD>\r\n<TD style=\"BORDER-RIGHT: medium none; BORDER-TOP: 1px solid; BORDER-LEFT: 1px solid; BORDER-BOTTOM: medium none\" align=right width=156><FONT color=#000080>sprchovat se</FONT></TD>\r\n<TD style=\"BORDER-LEFT: medium none; BORDER-BOTTOM: medium none\" align=right width=78><FONT color=#000080>jít</FONT></TD>\r\n<TD style=\"BORDER-BOTTOM: medium none\" align=middle width=185><B><U><FONT color=#000080>chodit</FONT></U></B></TD></TR>\r\n<TR>\r\n<TD style=\"BORDER-TOP: medium none; BORDER-BOTTOM: medium none\" align=middle width=146><FONT color=#000080><B><U>na</U></B>snídat<B><U> se</U></B></FONT></TD>\r\n<TD style=\"BORDER-RIGHT: medium none; BORDER-TOP: medium none; BORDER-LEFT: 1px solid; BORDER-BOTTOM: medium none\" align=right width=156><FONT color=#000080>snídat</FONT></TD>\r\n<TD style=\"BORDER-TOP: medium none; BORDER-LEFT: medium none; BORDER-BOTTOM: medium none\" align=right width=78><FONT color=#000080>jet</FONT></TD>\r\n<TD style=\"BORDER-TOP: medium none; BORDER-BOTTOM: medium none\" align=middle width=185><B><U><FONT color=#000080>jezdit</FONT></U></B></TD></TR>\r\n<TR>\r\n<TD style=\"BORDER-TOP: medium none; BORDER-BOTTOM: medium none\" align=middle width=146><FONT color=#000080><B><U>na</U></B>učit</FONT></TD>\r\n<TD style=\"BORDER-RIGHT: medium none; BORDER-TOP: medium none; BORDER-LEFT: 1px solid; BORDER-BOTTOM: medium none\" align=right width=156><FONT color=#000080>učit</FONT></TD>\r\n<TD style=\"BORDER-TOP: medium none; BORDER-LEFT: medium none; BORDER-BOTTOM: medium none\" align=right width=78><FONT color=#000080>běet</FONT></TD>\r\n<TD style=\"BORDER-TOP: medium none; BORDER-BOTTOM: medium none\" align=middle width=185><B><U><FONT color=#000080>běhat</FONT></U></B></TD></TR>\r\n<TR>\r\n<TD style=\"BORDER-TOP: medium none; BORDER-BOTTOM: medium none\" align=middle width=146><FONT color=#000080><B><U>u</U></B>vařit</FONT></TD>\r\n<TD style=\"BORDER-RIGHT: medium none; BORDER-TOP: medium none; BORDER-LEFT: 1px solid; BORDER-BOTTOM: medium none\" align=right width=156><FONT color=#000080>vařit</FONT></TD>\r\n<TD style=\"BORDER-TOP: medium none; BORDER-LEFT: medium none; BORDER-BOTTOM: medium none\" align=right width=78><FONT color=#000080>&nbsp;</FONT></TD>\r\n<TD style=\"BORDER-TOP: medium none\" align=middle width=185><FONT color=#000080>&nbsp;</FONT></TD></TR>\r\n<TR>\r\n<TD style=\"BORDER-TOP: medium none; BORDER-BOTTOM: medium none\" align=middle width=146><FONT color=#000080><B><U>vy</U></B>pít</FONT></TD>\r\n<TD style=\"BORDER-RIGHT: medium none; BORDER-TOP: medium none; BORDER-LEFT: 1px solid; BORDER-BOTTOM: medium none\" align=right width=156><FONT color=#000080>pít</FONT></TD>\r\n<TD style=\"BORDER-TOP: medium none; BORDER-LEFT: medium none; BORDER-BOTTOM: medium none\" align=middle width=78><FONT color=#000080>&nbsp;</FONT></TD>\r\n<TD align=middle width=185 bgColor=#ffcc00 rowSpan=5><FONT color=#000080>&nbsp;<IMG height=79 alt=width=89 src=\"http://www.bohemica.com/tuit/img/textbook/bk-abimage005.gif\"> </FONT></TD></TR>\r\n<TR>\r\n<TD style=\"BORDER-TOP: medium none; BORDER-BOTTOM: medium none\" align=middle width=146><FONT color=#000080><B><U>pře</U></B>číst</FONT></TD>\r\n<TD style=\"BORDER-RIGHT: medium none; BORDER-TOP: medium none; BORDER-LEFT: 1px solid; BORDER-BOTTOM: medium none\" align=right width=156><FONT color=#000080>číst</FONT></TD>\r\n<TD style=\"BORDER-TOP: medium none; BORDER-LEFT: medium none; BORDER-BOTTOM: medium none\" align=middle width=78><FONT color=#000080>&nbsp;</FONT></TD></TR>\r\n<TR>\r\n<TD style=\"BORDER-TOP: medium none; BORDER-BOTTOM: medium none\" align=middle width=146><FONT color=#000080><B><U>za</U></B>spat</FONT></TD>\r\n<TD style=\"BORDER-RIGHT: medium none; BORDER-TOP: medium none; BORDER-LEFT: 1px solid; BORDER-BOTTOM: medium none\" align=right width=156><FONT color=#000080>spát</FONT></TD>\r\n<TD style=\"BORDER-TOP: medium none; BORDER-LEFT: medium none; BORDER-BOTTOM: medium none\" align=middle width=78><FONT color=#000080>&nbsp;</FONT></TD></TR>\r\n<TR>\r\n<TD style=\"BORDER-TOP: medium none; BORDER-BOTTOM: medium none\" align=middle width=146><FONT color=#000080>koup<B><U>it</U></B></FONT></TD>\r\n<TD style=\"BORDER-RIGHT: medium none; BORDER-TOP: medium none; BORDER-LEFT: 1px solid; BORDER-BOTTOM: medium none\" align=right width=156><FONT color=#000080>kup<B><U>ovat</U></B></FONT></TD>\r\n<TD style=\"BORDER-TOP: medium none; BORDER-LEFT: medium none; BORDER-BOTTOM: medium none\" align=middle width=78><FONT color=#000080>&nbsp;</FONT></TD></TR>\r\n<TR>\r\n<TD style=\"BORDER-TOP: medium none; BORDER-BOTTOM: medium none\" align=middle width=146><FONT color=#000080>vst<B><U>át</U></B></FONT></TD>\r\n<TD style=\"BORDER-RIGHT: medium none; BORDER-TOP: medium none; BORDER-LEFT: 1px solid; BORDER-BOTTOM: medium none\" align=right width=156><FONT color=#000080>vst<B><U>ávat</U></B></FONT></TD>\r\n<TD style=\"BORDER-TOP: medium none; BORDER-LEFT: medium none; BORDER-BOTTOM: medium none\" align=middle width=78><FONT color=#000080>&nbsp;</FONT></TD></TR>\r\n<TR>\r\n<TD style=\"BORDER-TOP: medium none; BORDER-BOTTOM: medium none\" align=middle width=146><FONT color=#000080>vrá<B><U>tit se</U></B></FONT></TD>\r\n<TD style=\"BORDER-RIGHT: medium none; BORDER-TOP: medium none; BORDER-LEFT: 1px solid; BORDER-BOTTOM: medium none\" align=right width=156><FONT color=#000080>vra<B><U>cet se</U></B></FONT></TD>\r\n<TD style=\"BORDER-TOP: medium none; BORDER-LEFT: medium none; BORDER-BOTTOM: medium none\" align=middle width=78><FONT color=#000080>&nbsp;</FONT></TD>\r\n<TD style=\"BORDER-BOTTOM: medium none\" align=middle width=185><FONT color=#000080>&nbsp;</FONT></TD></TR>\r\n<TR>\r\n<TD style=\"BORDER-RIGHT: 1px solid; BORDER-TOP: medium none\" align=middle width=146><FONT color=#000080>navtív<B><U>it</U></B></FONT></TD>\r\n<TD style=\"BORDER-RIGHT: medium none; BORDER-TOP: medium none; BORDER-LEFT: 1px solid; BORDER-BOTTOM: 1px solid\" align=right width=156><FONT color=#000080>&nbsp;</FONT></TD>\r\n<TD style=\"BORDER-TOP: medium none; BORDER-LEFT: medium none\" align=middle width=78><FONT color=#000080>&nbsp;</FONT></TD>\r\n<TD style=\"BORDER-TOP: medium none\" vAlign=center align=middle width=185><FONT color=#000080>navtěv<B><U>ovat</U></B></FONT></TD></TR></TBODY></TABLE>', 3, NULL),
(2325, 1, 'U46/2', '', 58, '', '<TABLE id=table23 cellSpacing=0 cellPadding=3 width=675 bgColor=#ffffcc border=0>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=top width=669><B><FONT color=#330099 size=4>Co udělám zítra?!</FONT></B>\r\n<P><I><FONT color=#330099>Zítra budu vstávat v&nbsp;sedm hodin. Osprchuju se a budu <IMG height=58 src=\"http://www.bohemica.com/tuit/img/textbook/bk-abimage007.gif\" width=71> &nbsp;. A se nasnídám, půjdu do koly. Ve kole se budu <IMG height=62 src=\"http://www.bohemica.com/tuit/img/textbook/bk-abimage009.gif\" width=81> &nbsp;četinu a ekonomii. V&nbsp;poledne půjdu na oběd. A se na- <IMG height=61 src=\"http://www.bohemica.com/tuit/img/textbook/bk-abimage011.gif\" width=80> &nbsp;, vrátím se do koly a budu </FONT></I></P>\r\n<P><I><FONT color=#330099>psát esej. V&nbsp;pět hodin přijdeHonza a půjdeme <IMG height=63 src=\"http://www.bohemica.com/tuit/img/textbook/bk-abimage013.gif\" width=80> &nbsp;&nbsp;něco k&nbsp;večeři. Potom <IMG height=64 src=\"http://www.bohemica.com/tuit/img/textbook/bk-abimage015.gif\" width=82> &nbsp;na kolej, u- <IMG height=41 src=\"http://www.bohemica.com/tuit/img/textbook/bk-abimage017.gif\" width=58> &nbsp;večeři a budeme <IMG height=67 src=\"http://www.bohemica.com/tuit/img/textbook/bk-abimage019.gif\" width=91> &nbsp;nebo <IMG height=60 src=\"http://www.bohemica.com/tuit/img/textbook/bk-abimage021.gif\" width=70> &nbsp;. V&nbsp;deset hodin chceme <IMG height=62 src=\"http://www.bohemica.com/tuit/img/textbook/bk-abimage023.gif\" width=79> &nbsp;&nbsp;na diskotéku do Radosti FX.Tam budeme tancovat, bavit se a pít. A se vrátíme na kolej, budeme <IMG height=64 src=\"http://www.bohemica.com/tuit/img/textbook/bk-abimage025.gif\" width=85> &nbsp;, ale nesmíme zaspat, protoe ve středu začínají přednáky v 9 hodin.</FONT></I></P></TD></TR></TBODY></TABLE>', 3, NULL),
(2326, 1, 'U46/3', '', 58, '', '<H3><FONT color=#330099>Doplňte!</FONT></H3>\r\n<TABLE class=\"\" id=table24 cellSpacing=2 cellPadding=2 bgColor=#b0c4de border=0>\r\n<TBODY>\r\n<TR>\r\n<TD width=614 bgColor=#f2f2f2><B><FONT color=#330099>snídat - nasnídat se</FONT></B></TD></TR>\r\n<TR>\r\n<TD width=614>\r\n<P align=left><I><FONT color=#330099>Obvykle [$1,text 15:snídám] kávu a rohlík. A [$1,text 15:se nasnídám] půjdu do koly.</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=614 bgColor=#f2f2f2><B><FONT color=#330099>učit se - naučit se</FONT></B></TD></TR>\r\n<TR>\r\n<TD width=614>\r\n<P align=left><I><FONT color=#330099>[$1,text 15:Učím se] česky rád. Slovíčka [$1,text 15:se naučím] zítra.</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=614 bgColor=#f2f2f2><B><FONT color=#330099>kupovat - koupit</FONT></B></TD></TR>\r\n<TR>\r\n<TD width=614>\r\n<P align=left><I><FONT color=#330099>Zítra [$1,text 15:koupím] chleba. Kadý den [$1,text 15:kupuju] mléko.</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=614 bgColor=#f2f2f2><B><FONT color=#330099>psát  napsat</FONT></B></TD></TR>\r\n<TR>\r\n<TD width=614>\r\n<P align=left><I><FONT color=#330099>Odpoledne [$1,text 15:napíu] dopis kamarádovi. Kadý večer [$1,text 15:píu] domácí úkoly.</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=614 bgColor=#f2f2f2><B><FONT color=#330099>pít - napít se</FONT></B></TD></TR>\r\n<TR>\r\n<TD width=614>\r\n<P align=left><I><FONT color=#330099>V hospodě [$1,text 15:piju] pivo. Mám ízeň, a proto [$1,text 3:se] musím [$1,text 15:napít].</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD width=614 bgColor=#f2f2f2><B><FONT color=#330099>vařit  uvařit</FONT></B></TD></TR>\r\n<TR>\r\n<TD width=614><I><FONT color=#330099>Zítra [$1,text 15:uvařím] dobrý oběd. Kadý den musím [$1,text 15:vařit].</FONT></I></TD></TR>\r\n<TR>\r\n<TD width=614 bgColor=#f2f2f2><B><FONT color=#330099>číst  přečíst</FONT></B></TD></TR>\r\n<TR>\r\n<TD width=614><I><FONT color=#330099>[$1,text 15:Přečtu] ten časopis zítra. Ráda [$1,text 15:čtu] historické knihy.</FONT></I></TD></TR>\r\n<TR>\r\n<TD width=614 bgColor=#f2f2f2><B><FONT color=#330099>spát  zaspat</FONT></B></TD></TR>\r\n<TR>\r\n<TD width=614><I><FONT color=#330099>V pátek nesmíme [$1,text 15:zaspat]. Kadý den [$1,text 15:spím] osm hodin.</FONT></I></TD></TR></TBODY></TABLE>', 3, NULL),
(2327, 1, 'U46/4', '', 58, '', '<H3><FONT color=#330099>Napite kdy! </FONT></H3>\r\n<TABLE id=table25 style=\"WIDTH: 628px; HEIGHT: 355px\" cellPadding=2 bgColor=#b0c4de>\r\n<TBODY>\r\n<TR>\r\n<TD width=385>&nbsp;</TD>\r\n<TD width=190>\r\n<P align=center><I><B><FONT color=#330099>DNES / ZÍTRA</FONT></B></I></P></TD></TR>\r\n<TR>\r\n<TD width=385><I><FONT face=Arial color=#330099>Navečeříme se v restauraci.</FONT></I></TD>\r\n<TD width=190>\r\n<P align=center><FONT face=Arial color=#330099>[DNES/(ZÍTRA]</FONT></P></TD></TR>\r\n<TR>\r\n<TD width=385><I><FONT face=Arial color=#330099>Píeme dlouhý dopis pro kamaráda.</FONT></I></TD>\r\n<TD width=190>\r\n<P align=center><FONT face=Arial color=#330099>[(DNES/ZÍTRA]</FONT></P></TD></TR>\r\n<TR>\r\n<TD width=385><I><FONT face=Arial color=#330099>Pojedete do Brna.</FONT></I></TD>\r\n<TD width=190>\r\n<P align=center><FONT face=Arial color=#330099>[DNES/(ZÍTRA]</FONT></P></TD></TR>\r\n<TR>\r\n<TD width=385><I><FONT face=Arial color=#330099>Přijedeme v&nbsp;sobotu.</FONT></I></TD>\r\n<TD width=190>\r\n<P align=center><FONT face=Arial color=#330099>[DNES/(ZÍTRA]</FONT></P></TD></TR>\r\n<TR>\r\n<TD width=385><I><FONT face=Arial color=#330099>Spím dlouho.</FONT></I></TD>\r\n<TD width=190>\r\n<P align=center><FONT face=Arial color=#330099>[(DNES/ZÍTRA]</FONT></P></TD></TR>\r\n<TR>\r\n<TD width=385><I><FONT face=Arial color=#330099>Hrajeme tenis dvě hodiny.</FONT></I></TD>\r\n<TD width=190>\r\n<P align=center><FONT face=Arial color=#330099>[(DNES/ZÍTRA]</FONT></P></TD></TR>\r\n<TR>\r\n<TD width=385><I><FONT face=Arial color=#330099>Dám Honzovi dárek k svátku.</FONT></I></TD>\r\n<TD width=190>\r\n<P align=center><FONT face=Arial color=#330099>[DNES/(ZÍTRA]</FONT></P></TD></TR>\r\n<TR>\r\n<TD width=385><I><FONT face=Arial color=#330099>Naučím se gramatiku.</FONT></I></TD>\r\n<TD width=190>\r\n<P align=center><FONT face=Arial color=#330099>[DNES/(ZÍTRA]</FONT></P></TD></TR>\r\n<TR>\r\n<TD width=385><I><FONT face=Arial color=#330099>Vařím oběd pro kamarády.</FONT></I></TD>\r\n<TD width=190>\r\n<P align=center><FONT face=Arial color=#330099>[(DNES/ZÍTRA]</FONT></P></TD></TR>\r\n<TR>\r\n<TD width=385><I><FONT face=Arial color=#330099>Alena mi zavolá.</FONT></I></TD>\r\n<TD width=190>\r\n<P align=center><FONT face=Arial color=#330099>[DNES/(ZÍTRA]</FONT></P></TD></TR>\r\n<TR>\r\n<TD width=385><I><FONT face=Arial color=#330099>Nepiju alkohol.</FONT></I></TD>\r\n<TD width=190>\r\n<P align=center><FONT face=Arial color=#330099>[(DNES/ZÍTRA]</FONT></P></TD></TR>\r\n<TR>\r\n<TD width=385><I><FONT face=Arial color=#330099>Vrátím se večer</FONT></I></TD>\r\n<TD width=190>\r\n<P align=center><FONT face=Arial color=#330099>[DNES/(ZÍTRA]</FONT></P></TD></TR></TBODY></TABLE>', 3, NULL);
