(2329, 1, 'U46/6', '', 58, '', '<H3><FONT color=#330099>Co je správně?</FONT></H3>\r\n<P>\r\n<TABLE class=\"\" id=table27 height=699 cellSpacing=2 cellPadding=2 width=708 bgColor=#b0c4de border=0>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=top width=347 bgColor=#f2f2f2 height=28><I><FONT face=Arial color=#330099>Skončí film ve dvacet hodin?[$1, select:a/b/c]</FONT></I></TD>\r\n<TD vAlign=top width=347 bgColor=#f2f2f2 height=28><I><FONT face=Arial color=#330099>Pojede zítra do Ostravy?[$1, select:a/b/c]</FONT></I></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=347 height=101><I><FONT face=Arial color=#330099>a) Ne, končí a v deset.</FONT></I>\r\n<P><FONT face=Arial color=#330099><I>b) Ano, skončí.</I></FONT></P>\r\n<P><I><FONT face=Arial color=#330099>c) Bude končit&nbsp; ve dvanáct.</FONT></I></P></TD>\r\n<TD vAlign=top width=347 height=101><I><FONT face=Arial color=#330099>a) Ano, budu jet.</FONT></I>\r\n<P><I><FONT face=Arial color=#330099>b) Ano, půjdu.</FONT></I></P>\r\n<P><I><FONT face=Arial color=#330099>c) Ano, pojedu. </FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=347 bgColor=#f2f2f2 height=25><I><FONT face=Arial color=#330099>Co čte?[$1, select:a/b/c]</FONT></I></TD>\r\n<TD vAlign=top width=347 bgColor=#f2f2f2 height=25><I><FONT face=Arial color=#330099>Zeptá se kolik je hodin?[$1, select:a/b/c]</FONT></I></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=347 height=108><I><FONT face=Arial color=#330099>a) Čtu knihu</FONT></I>\r\n<P><I><FONT face=Arial color=#330099>b) Přečtu knihu.</FONT></I></P>\r\n<P><I><FONT face=Arial color=#330099>c) Čteme knihu </FONT></I></P></TD>\r\n<TD vAlign=top width=347 height=108><I><FONT face=Arial color=#330099>a) Ne, nezeptám se.</FONT></I>\r\n<P><I><FONT face=Arial color=#330099>b) Nebudu se ptát.</FONT></I></P>\r\n<P><I><FONT face=Arial color=#330099>c) Ano, budu se zeptat. </FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=347 bgColor=#f2f2f2 height=33><I><FONT face=Arial color=#330099>Píe dopis?[$1, select:a/b/c]</FONT></I></TD>\r\n<TD vAlign=top width=347 bgColor=#f2f2f2 height=33><I><FONT face=Arial color=#330099>Kdy zítra přijde?[$1, select:a/b/c]</FONT></I></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=347 height=103><I><FONT face=Arial color=#330099>a) Ano, píu.</FONT></I>\r\n<P><I><FONT face=Arial color=#330099>b) Ne, napíe ho zítra.</FONT></I></P>\r\n<P><I><FONT face=Arial color=#330099>c) Budeme ho psát odpoledne.</FONT></I></P></TD>\r\n<TD vAlign=top width=347 height=103><I><FONT face=Arial color=#330099>a) Půjdu odpoledne.</FONT></I>\r\n<P><I><FONT face=Arial color=#330099>b) Přijdu večer.</FONT></I></P>\r\n<P><I><FONT face=Arial color=#330099>c) Chodím ráno. </FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=347 bgColor=#f2f2f2 height=32><I><FONT face=Arial color=#330099>Půjde domů?[$1, select:a/b/c]</FONT></I></TD>\r\n<TD vAlign=top width=347 bgColor=#f2f2f2 height=32><I><FONT face=Arial color=#330099>Počká na mě?[$1, select:a/b/c]</FONT></I></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=347 height=110><I><FONT face=Arial color=#330099>a) Ne, nepůjdu.</FONT></I>\r\n<P><I><FONT face=Arial color=#330099>b) Ano, pojedu.</FONT></I></P>\r\n<P><I><FONT face=Arial color=#330099>c) Ano, přijedu. </FONT></I></P></TD>\r\n<TD vAlign=top width=347 height=110><I><FONT face=Arial color=#330099>a) Ne, nečekám.</FONT></I>\r\n<P><I><FONT face=Arial color=#330099>b) Ano, budu čekat.</FONT></I></P>\r\n<P><I><FONT face=Arial color=#330099>c) Ano, počkám. </FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=347 bgColor=#f2f2f2 height=29><I><FONT face=Arial color=#330099>Dá si kávu nebo čaj?[$1, select:a/b/c]</FONT></I></TD>\r\n<TD vAlign=top width=347 bgColor=#f2f2f2 height=29><I><FONT face=Arial color=#330099>Bude jíst tu housku?[$1, select:a/b/c]</FONT></I></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=347 height=108><I><FONT face=Arial color=#330099>a) Dávám si čaj.</FONT></I>\r\n<P><I><FONT face=Arial color=#330099>b) Dám si kávu.</FONT></I></P>\r\n<P><I><FONT face=Arial color=#330099>c) Dáme si čaj. </FONT></I></P></TD>\r\n<TD vAlign=top width=347 height=108><I><FONT face=Arial color=#330099>a) Ne, sním ji a za chvíli.</FONT></I>\r\n<P><I><FONT face=Arial color=#330099>b) Ano sním.</FONT></I></P>\r\n<P><I><FONT face=Arial color=#330099>c) Ano, budu. </FONT></I></P></TD></TR></TBODY></TABLE></P>', 3, NULL),
(2330, 1, 'U46/7', '', 58, '', '<H3><FONT color=#330099>Napite, co budete dělat zítra!</FONT></H3><FONT color=#330099>[$1,textarea 80,30]<BR>&nbsp;</FONT>', 3, NULL),
(2331, 1, 'U46-8', '', 58, '', '<H3><FONT color=#330099>Vyberte ze dvojice verb A-B a doplňte do vhodné věty!</FONT></H3>\r\n<TABLE class=\"\" id=table28 style=\"WIDTH: 821px; HEIGHT: 442px\" cellSpacing=2 cellPadding=2 bgColor=#b0c4de border=0>\r\n<TBODY>\r\n<TR>\r\n<TD vAlign=top width=92 bgColor=#f2f2f2>\r\n<P align=left><FONT face=Arial color=#330099><STRONG>A/ </STRONG>dívat se</FONT></P></TD>\r\n<TD vAlign=top align=middle width=66 bgColor=#f2f2f2><FONT face=Arial color=#330099><IMG height=20 src=\"http://www.bohemica.com/tuit/img/textbook/bk-abimage027.gif\" width=41></FONT></TD>\r\n<TD width=303><FONT color=#330099><STRONG>\r\n<P align=center></STRONG><FONT face=Arial><EM>Dnes [$1,text 10:se dívám] celý večer na televizi.</EM></FONT></FONT></P></TD>\r\n<TD vAlign=top width=104 bgColor=#f2f2f2>\r\n<P align=left><FONT face=Arial color=#330099><STRONG>A/ </STRONG>navtívit</FONT></P></TD>\r\n<TD vAlign=top align=middle width=71 bgColor=#f2f2f2><FONT face=Arial color=#330099><IMG height=19 alt=align=top src=\"http://www.bohemica.com/tuit/img/textbook/bk-abimage034.gif\" width=36></FONT></TD>\r\n<TD width=260>\r\n<P align=left><I><FONT face=Arial color=#330099>Obvykle [$1,text 10:navtěvuju] rodiče v&nbsp;sobotu.</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=92 bgColor=#f2f2f2>\r\n<P align=left><FONT face=Arial color=#330099><STRONG>B/ </STRONG>podívat se</FONT></P></TD>\r\n<TD vAlign=top align=middle width=66 bgColor=#f2f2f2><FONT face=Arial color=#330099><IMG height=24 src=\"http://www.bohemica.com/tuit/img/textbook/bk-abimage029.gif\" width=45></FONT></TD>\r\n<TD width=303>\r\n<P align=left><I><FONT face=Arial color=#330099>Můu [$1,text 10:se podívat] na tu fotografii?</FONT></I></P></TD>\r\n<TD vAlign=top width=104 bgColor=#f2f2f2>\r\n<P align=left><FONT face=Arial color=#330099><STRONG>B/ </STRONG>navtěvovat</FONT></P></TD>\r\n<TD vAlign=top align=middle width=71 bgColor=#f2f2f2><FONT face=Arial color=#330099><IMG height=20 src=\"http://www.bohemica.com/tuit/img/textbook/bk-abimage030.gif\" width=41></FONT></TD>\r\n<TD width=260>\r\n<P align=left><I><FONT face=Arial color=#330099>Tuhla sobotu jedem [$1,text 10:navtívit] Věru.</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=92 bgColor=#f2f2f2>\r\n<P align=left><FONT face=Arial color=#330099><STRONG>A/ </STRONG>ptát se</FONT></P></TD>\r\n<TD vAlign=top align=middle width=66 bgColor=#f2f2f2><FONT face=Arial color=#330099><IMG height=20 src=\"http://www.bohemica.com/tuit/img/textbook/bk-abimage031.gif\" width=41></FONT></TD>\r\n<TD width=303>\r\n<P align=left><I><FONT face=Arial color=#330099>Chci [$1,text 3:se] ho [$1,text 10:zeptat], kdy přijde.</FONT></I></P></TD>\r\n<TD vAlign=top width=104 bgColor=#f2f2f2>\r\n<P align=left><FONT face=Arial color=#330099><STRONG>A/ </STRONG>končit</FONT></P></TD>\r\n<TD vAlign=top align=middle width=71 bgColor=#f2f2f2><FONT face=Arial color=#330099><IMG height=20 src=\"http://www.bohemica.com/tuit/img/textbook/bk-abimage032.gif\" width=41></FONT></TD>\r\n<TD width=260>\r\n<P align=left><I><FONT face=Arial color=#330099>V kolik hodin [$1,text 10:skončí] ten film?</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=92 bgColor=#f2f2f2>\r\n<P align=left><FONT face=Arial color=#330099><STRONG>B/ </STRONG>zeptat se</FONT></P></TD>\r\n<TD vAlign=top align=middle width=66 bgColor=#f2f2f2><FONT face=Arial color=#330099><IMG height=19 src=\"http://www.bohemica.com/tuit/img/textbook/bk-abimage033.gif\" width=36></FONT></TD>\r\n<TD width=303>\r\n<P align=left><I><FONT face=Arial color=#330099>Často se mě [$1,text 10:ptá].</FONT></I></P></TD>\r\n<TD vAlign=top width=104 bgColor=#f2f2f2>\r\n<P align=left><FONT face=Arial color=#330099><STRONG>B/ </STRONG>skončit</FONT></P></TD>\r\n<TD vAlign=top align=middle width=71 bgColor=#f2f2f2><FONT face=Arial color=#330099><IMG height=19 src=\"http://www.bohemica.com/tuit/img/textbook/bk-abimage034.gif\" width=36></FONT></TD>\r\n<TD width=260>\r\n<P align=left><I><FONT face=Arial color=#330099>Filmový festival [$1,text 10:končí] tento týden.</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=92 bgColor=#f2f2f2>\r\n<P align=left><FONT face=Arial color=#330099><STRONG>A/ </STRONG>psát</FONT></P></TD>\r\n<TD vAlign=top align=middle width=66 bgColor=#f2f2f2><FONT face=Arial color=#330099><IMG height=20 src=\"http://www.bohemica.com/tuit/img/textbook/bk-abimage035.gif\" width=41></FONT></TD>\r\n<TD width=303>\r\n<P align=left><I><FONT face=Arial color=#330099>Studenti [$1,text 10:píou] do seitu.</FONT></I></P></TD>\r\n<TD vAlign=top width=104 bgColor=#f2f2f2>\r\n<P align=left><FONT face=Arial color=#330099><STRONG>A/ </STRONG>vidět</FONT></P></TD>\r\n<TD vAlign=top align=middle width=71 bgColor=#f2f2f2><FONT face=Arial color=#330099><IMG height=20 src=\"http://www.bohemica.com/tuit/img/textbook/bk-abimage036.gif\" width=41></FONT></TD>\r\n<TD width=260>\r\n<P align=left><I><FONT face=Arial color=#330099>[$1,text 10:Vidím] Michala kadou středu.</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=92 bgColor=#f2f2f2>\r\n<P align=left><FONT face=Arial color=#330099><STRONG>B/ </STRONG>napsat</FONT></P></TD>\r\n<TD vAlign=top align=middle width=66 bgColor=#f2f2f2><FONT face=Arial color=#330099><IMG height=19 src=\"http://www.bohemica.com/tuit/img/textbook/bk-abimage037.gif\" width=36></FONT></TD>\r\n<TD width=303>\r\n<P align=left><I><FONT face=Arial color=#330099>Zítra musím [$1,text 10:napsat] e- mail tatínkovi.</FONT></I></P></TD>\r\n<TD vAlign=top width=104 bgColor=#f2f2f2>\r\n<P align=left><FONT face=Arial color=#330099><STRONG>B/ </STRONG>uvidět </FONT></P></TD>\r\n<TD vAlign=top align=middle width=71 bgColor=#f2f2f2><FONT face=Arial color=#330099><IMG height=19 src=\"http://www.bohemica.com/tuit/img/textbook/bk-abimage038.gif\" width=36></FONT></TD>\r\n<TD width=260>\r\n<P align=left><I><FONT face=Arial color=#330099>[$1,text 10:Uvidím] Michala přítí týden.</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=92 bgColor=#f2f2f2>\r\n<P align=left><FONT face=Arial color=#330099><STRONG>A/ </STRONG>uklízet</FONT></P></TD>\r\n<TD vAlign=top align=middle width=66 bgColor=#f2f2f2><FONT face=Arial color=#330099><IMG height=20 src=\"http://www.bohemica.com/tuit/img/textbook/bk-abimage039.gif\" width=41></FONT></TD>\r\n<TD width=303>\r\n<P align=left><I><FONT face=Arial color=#330099>A [$1,text 10:uklidím] byt, dám si kávu.</FONT></I></P></TD>\r\n<TD vAlign=top width=104 bgColor=#f2f2f2>\r\n<P align=left><FONT face=Arial color=#330099><STRONG>A/ </STRONG>mýt si</FONT></P></TD>\r\n<TD vAlign=top align=middle width=71 bgColor=#f2f2f2><FONT face=Arial color=#330099><IMG height=20 src=\"http://www.bohemica.com/tuit/img/textbook/bk-abimage040.gif\" width=41></FONT></TD>\r\n<TD vAlign=top width=260>\r\n<P align=left><I><FONT face=Arial color=#330099>Malý moment,[$1,text 10: umyju si] ruce</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=92 bgColor=#f2f2f2>\r\n<P align=left><FONT face=Arial color=#330099><STRONG>B/ </STRONG>uklidit</FONT></P></TD>\r\n<TD vAlign=top align=middle width=66 bgColor=#f2f2f2><FONT face=Arial color=#330099><IMG height=19 src=\"http://www.bohemica.com/tuit/img/textbook/bk-abimage041.gif\" width=36></FONT></TD>\r\n<TD width=303>\r\n<P align=left><I><FONT face=Arial color=#330099>Kadý den děti [$1,text 10:uklízí] pokoj.</FONT></I></P></TD>\r\n<TD vAlign=top width=104 bgColor=#f2f2f2>\r\n<P align=left><FONT face=Arial color=#330099><STRONG>B/ </STRONG>umýt si</FONT></P></TD>\r\n<TD vAlign=top align=middle width=71 bgColor=#f2f2f2><FONT face=Arial color=#330099><IMG height=19 src=\"http://www.bohemica.com/tuit/img/textbook/bk-abimage042.gif\" width=36></FONT></TD>\r\n<TD width=260>\r\n<P align=left><I><FONT face=Arial color=#330099>Nohy [$1,text 10:si myju] ráno a večer.</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=92 bgColor=#f2f2f2>\r\n<P align=left><FONT face=Arial color=#330099><STRONG>A/ </STRONG>vstávat</FONT></P></TD>\r\n<TD vAlign=top align=middle width=66 bgColor=#f2f2f2><FONT face=Arial color=#330099><IMG height=20 src=\"http://www.bohemica.com/tuit/img/textbook/bk-abimage043.gif\" width=41></FONT></TD>\r\n<TD width=303>\r\n<P align=left><I><FONT face=Arial color=#330099>Celý týden [$1,text 10:vstávám] v&nbsp;sedm hodin.</FONT></I></P></TD>\r\n<TD vAlign=top width=104 bgColor=#f2f2f2>\r\n<P align=left><FONT face=Arial color=#330099><STRONG>A/ </STRONG>vracet se</FONT></P></TD>\r\n<TD vAlign=top align=middle width=71 bgColor=#f2f2f2><FONT face=Arial color=#330099><IMG height=20 src=\"http://www.bohemica.com/tuit/img/textbook/bk-abimage044.gif\" width=41></FONT></TD>\r\n<TD width=260>\r\n<P align=left><I><FONT face=Arial color=#330099>Často [$1,text 10:se vracím] pozdě.</FONT></I></P></TD></TR>\r\n<TR>\r\n<TD vAlign=top width=92 bgColor=#f2f2f2>\r\n<P align=left><FONT face=Arial color=#330099><STRONG>B/ </STRONG>vstát</FONT></P></TD>\r\n<TD vAlign=top align=middle width=66 bgColor=#f2f2f2><FONT face=Arial color=#330099><IMG height=19 src=\"http://www.bohemica.com/tuit/img/textbook/bk-abimage045.gif\" width=36></FONT></TD>\r\n<TD width=303>\r\n<P align=left><I><FONT face=Arial color=#330099>A vstanu, [$1,text 10:osprchuju se].</FONT></I></P></TD>\r\n<TD vAlign=top width=104 bgColor=#f2f2f2>\r\n<P align=left><FONT face=Arial color=#330099><STRONG>B/ </STRONG>vrátit se</FONT></P></TD>\r\n<TD vAlign=top align=middle width=71 bgColor=#f2f2f2><FONT face=Arial color=#330099><IMG height=19 src=\"http://www.bohemica.com/tuit/img/textbook/bk-abimage046.gif\" width=36></FONT></TD>\r\n<TD width=260>\r\n<P align=left><I><FONT face=Arial color=#330099>Domů [$1,text 10:se vrátím] ve 22 hodin.</FONT></I></P></TD></TR></TBODY></TABLE>', 3, NULL),
(2332, 1, 'U46-9', '', 58, '', '<H3><FONT color=#330099>Určete, zda je verbum prefektivní nebo imperfektivní a utvořte správnou formu!</FONT></H3>\r\n<P>\r\n<TABLE id=table29 cellSpacing=2 cellPadding=2 bgColor=#b0c4de border=0 class?>\r\n<TBODY>\r\n<TR>\r\n<TD width=43>\r\n<P align=center><I><B><FONT face=Arial color=#330099>P / I</FONT></B></I></P></TD>\r\n<TD vAlign=bottom width=104 bgColor=#f2f2f2>\r\n<P align=center><FONT face=Arial></FONT>&nbsp;</P></TD>\r\n<TD vAlign=bottom width=33 bgColor=#f2f2f2>\r\n<P align=center><FONT face=Arial></FONT>&nbsp;</P></TD>\r\n<TD vAlign=bottom width=275>\r\n<P align=center><FONT face=Arial></FONT>&nbsp;</P></TD>\r\n<TD vAlign=bottom width=52>\r\n<P align=center><I><B><FONT face=Arial color=#330099>P / I</FONT></B></I></P></TD>\r\n<TD vAlign=bottom width=80 bgColor=#f2f2f2>\r\n<P align=center><FONT face=Arial></FONT>&nbsp;</P></TD>\r\n<TD vAlign=bottom width=33 bgColor=#f2f2f2>\r\n<P align=center><FONT face=Arial></FONT>&nbsp;</P></TD>\r\n<TD vAlign=bottom width=246>\r\n<P align=center><FONT face=Arial></FONT>&nbsp;</P></TD></TR>\r\n<TR>\r\n<TD width=43><I><FONT face=Arial color=#330099>\r\n<P align=center>[$1, select:P/I]</FONT></I></P></TD>\r\n<TD width=104 bgColor=#f2f2f2><I><B><FONT face=Arial color=#330099>umýt si</FONT></B></I></TD>\r\n<TD width=33 bgColor=#f2f2f2>\r\n<P align=center><I><FONT face=Arial color=#330099>já</FONT></I></P></TD>\r\n<TD width=275><I><FONT face=Arial color=#330099>Musím [$1,text 10:si umýt] ruce.</FONT></I></TD>\r\n<TD width=52><I><FONT face=Arial color=#330099>\r\n<P align=center>[$1, select:P/I]</FONT></I></P></TD>\r\n<TD width=80 bgColor=#f2f2f2><I><B><FONT face=Arial color=#330099>vstávat</FONT></B></I></TD>\r\n<TD width=33 bgColor=#f2f2f2>\r\n<P align=center><I><FONT face=Arial color=#330099>já</FONT></I></P></TD>\r\n<TD width=246><I><FONT face=Arial color=#330099>Kadý den[$1,text 10: vstávám] v&nbsp;7 hodin.</FONT></I></TD></TR>\r\n<TR>\r\n<TD width=43><I><FONT face=Arial color=#330099>\