INSERT INTO `xcx_data` (`xcxd_xcx_id`, `xcxd_content`) VALUES
(1, '<font color=\"#000099\"><b>prosím</b></font> <i>(pro-seem)</i> Possibly the most useful word in Czech. Meaning 1: Please.'),
(1, '<font color=\"#000099\"><b>d&#283;kuju</b></font> <i>(dyeh-kooyoo)</i> Thank you, is a universally useful phrase.'),
(1, '<font color=\"#000099\"><b>ano</b></font> <i>(ah-noh)</i> Yes. Ano is often shortened to no, sometimes resulting in cross-language confusion.'),
(1, '<font color=\"#000099\"><b>ne</b></font> <i>(neh)</i> No. Fairly straightforward and direct.'),
(1, '<font color=\"#000099\"><b>dobrý den</b></font> <i>(dob-ree den)</i> Hello, Good afternoon. Use with people you dont know or who are superior to you.'),
(1, '<font color=\"#000099\"><b>nashledanou</b></font> <i>(nus-hle-dah-no)</i> Good bye. Use with people you dont know or who are superior to you.'),
(1, '<font color=\"#000099\"><b>Ahoj</b></font> <i>(ah-hoy)</i> Hi. or Bye. Much like Aloha this word can be used both when meeting and leaving. Cau is another informal equivalent.'),
(1, '<font color=\"#000099\"><b>Kde je toaleta?</b></font> <i>(kdeh yeh toh-ah-le-ta)</i> Where is the bathroom?'),
(1, '<font color=\"#000099\"><b>Kolik to stojí?</b></font> <i>(koh-leek toh stoh-yee)</i> How much is it?'),
(1, '<font color=\"#000099\"><b>Co je to?</b></font> <i>(tso yeh toh)</i> What is it?'),
(1, '<font color=\"#000099\"><b>&#269;etina</b></font> <i>(chesh-tyi-nah)</i> Czech language'),
(1, '<font color=\"#000099\"><b>&#268;eka</b></font> <i>(chesh-kah)</i> Czech woman'),
(1, '<font color=\"#000099\"><b>&#268;ech</b></font> <i>(chekh)</i> Czech man'),
(1, '<font color=\"#000099\"><b>&#269;eský, &#269;eská, &#269;eské</b></font> <i>(chess-keeee)</i> adjective as in &#268;eská republika  Czech Republic'),
(1, '<font color=\"#000099\"><b>&#269;esky</b></font> <i>(chess-kee)</i> Czech as in I speak Czech - an adverb'),
(1, '<font color=\"#000099\"><b>prosím</b></font> <i>(pro-seem)</i> Possibly the most useful word in Czech. Meaning 2: Here you are.'),
(1, '<font color=\"#000099\"><b>prosím</b></font> <i>(pro-seem)</i> Possibly the most useful word in Czech. Meaning 3: Youre welcome.'),
(1, '<font color=\"#000099\"><b>prosím</b></font> <i>(pro-seem)</i> Possibly the most useful word in Czech. Meaning 4: What did you say?.'),
