INSERT INTO `xc_articles` (`xca_id`, `xca_name`, `xca_author`, `xca_perex`, `xca_text`, `xca_time`, `xca_readers`, `xca_section`, `xca_priority`) VALUES
(38, 'Book Reviews', 'Dominik Luke', 'Czech textbooks and dictionaries compared. This is a much older version of what has now become the <a href=bookstore/index.php>Bookstore</a> on Bohemica.com.', '  <h1><span lang=\"EN-US\" style=\"font-family:Arial;mso-bidi-font-family:&quot;Times New Roman&quot;\">Overview\r\n  of Czech Textbooks\r\n  \r\n  </span></h1>\r\n</div>\r\n<p class=\"NormalNoIndent\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">Despite\r\nCzech for foreigners textbook-making being a relatively small field there are\r\ndozens of books bearing Czech for foreigners in their title. Not all of them are\r\nreadily available, however, and very few of them are worth a second look. This\r\nsection lists existing coursebooks which may be seen at bookstores both in the\r\nCzech Republic and overseas and which are of any value. Many of these materials\r\nare available through Internet bookstores such as Amazon and Barnes and Noble,\r\nCzech company Leda also offers its dictionaries over the Internet at www.leda.cz.\r\nThe prices given are for guidance only and may vary significantly.\r\n\r\n</span></p>\r\n<h3><span lang=\"EN-US\">Textbooks</span></h3>\r\n<table border=\"0\" cellspacing=\"0\" cellpadding=\"0\" style=\"border-collapse:collapse;\r\n mso-table-layout-alt:fixed;mso-padding-alt:0cm 5.4pt 0cm 5.4pt\">\r\n  <tr>\r\n    <td width=\"64\" valign=\"top\" style=\"width:47.95pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><b style=\"mso-bidi-font-weight:normal\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">Price\r\n      \r\n      </span></b></p>\r\n    </td>\r\n    <td width=\"104\" valign=\"top\" style=\"width:77.95pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><b style=\"mso-bidi-font-weight:normal\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">Author\r\n      \r\n      </span></b></p>\r\n    </td>\r\n    <td width=\"227\" valign=\"top\" style=\"width:6.0cm;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><b style=\"mso-bidi-font-weight:normal\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">Title\r\n      \r\n      </span></b></p>\r\n    </td>\r\n    <td width=\"57\" valign=\"top\" style=\"width:42.55pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><b style=\"mso-bidi-font-weight:normal\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">Year\r\n      \r\n      </span></b></p>\r\n    </td>\r\n    <td width=\"406\" valign=\"top\" style=\"width:304.75pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\" style=\"text-align:justify\"><b style=\"mso-bidi-font-weight:\r\n  normal\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">Notes\r\n      \r\n      </span></b></p>\r\n    </td>\r\n  </tr>\r\n  <tr>\r\n    <td width=\"64\" valign=\"top\" style=\"width:47.95pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">$16\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"104\" valign=\"top\" style=\"width:77.95pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\">&nbsp;<span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"227\" valign=\"top\" style=\"width:6.0cm;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">Berlitz\r\n      Czech Cassette Pack\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"57\" valign=\"top\" style=\"width:42.55pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">1993\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"406\" valign=\"top\" style=\"width:304.75pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\" style=\"text-align:justify\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">A\r\n      quality Berlitz tape with a lot of were so great, British talk.\r\n      Unlike the Fast and Easy Czech tape, it gives you more time to repeat. The\r\n      speakers pronounce more distinctly and the first utterance is always\r\n      slower than the second. Good for jogging, cooking, or driving. The pack\r\n      also contains a script and a phrasebook with a negligible dictionary and\r\n      grammar section. The phrasebook can be purchased separately.\r\n      \r\n      </span></p>\r\n    </td>\r\n  </tr>\r\n  <tr>\r\n    <td width=\"64\" valign=\"top\" style=\"width:47.95pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><a name=\"cechova\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">300\r\n      K&#269;\r\n      \r\n      </span></a></p>\r\n    </td>\r\n    <td width=\"104\" valign=\"top\" style=\"width:77.95pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">&#268;echová\r\n      M., H. Trabelsiová, H. Putz\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"227\" valign=\"top\" style=\"width:6.0cm;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">Do\r\n      You Want To Speak Czech\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"57\" valign=\"top\" style=\"width:42.55pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">1993\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"406\" valign=\"top\" style=\"width:304.75pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\" style=\"text-align:justify\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">Do\r\n      You Want To Speak Czech is not very suitable as a course book. The\r\n      language is too hard and sometimes unnatural. Very often grammar\r\n      introduced in a lesson is not sufficiently practiced in the subsequent\r\n      exercises. More advanced students, however, will find this book very\r\n      useful. It will help them to see what theyve learned in a different\r\n      light.\r\n      \r\n      </span></p>\r\n      <p class=\"TableSmall\" style=\"text-align:justify\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">The\r\n      2 tapes that come with it are not very good because the recordings are too\r\n      fast, and hard to follow.\r\n      \r\n      </span></p>\r\n      <p class=\"TableSmall\" style=\"text-align:justify\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">A\r\n      version for advanced students is also available.\r\n      \r\n      </span></p>\r\n    </td>\r\n  </tr>\r\n  <tr>\r\n    <td width=\"64\" valign=\"top\" style=\"width:47.95pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">300\r\n      K</span><span lang=\"CS\" style=\"font-family:&quot;Times New Roman&quot;;mso-ansi-language:\r\n  CS\">&#269;\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"104\" valign=\"top\" style=\"width:77.95pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">Aignerová,\r\n      A.\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"227\" valign=\"top\" style=\"width:6.0cm;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">Tschechish\r\n      Anders/</span><span lang=\"CS\" style=\"font-family:&quot;Times New Roman&quot;;mso-ansi-language:\r\n  CS\">&#268;</span><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">etina\r\n      jinak\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"57\" valign=\"top\" style=\"width:42.55pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">1994\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"406\" valign=\"top\" style=\"width:304.75pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\" style=\"text-align:justify\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">German-based\r\n      textbook but very interesting. It is the only one I know that uses songs\r\n      for its dialogues. It also contains many interesting exercises. You can\r\n      buy a tape with all the songs. I would recommend it to people who speak\r\n      some German, or to those who can read musical scores.\r\n      \r\n      </span></p>\r\n      <p class=\"TableSmall\" style=\"text-align:justify\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">An\r\n      interesting tape containing all the songs comes with the book.\r\n      \r\n      </span></p>\r\n    </td>\r\n  </tr>\r\n  <tr>\r\n    <td width=\"64\" valign=\"top\" style=\"width:47.95pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">500\r\n      K</span><span lang=\"CS\" style=\"font-family:&quot;Times New Roman&quot;;mso-ansi-language:\r\n  CS\">&#269;</span><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"104\" valign=\"top\" style=\"width:77.95pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">Bedná&#345;ová\r\n      and Pintarová\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"227\" valign=\"top\" style=\"width:6.0cm;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"MsoNormal\" align=\"left\" style=\"text-align:left\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">Communicative\r\n      Czech (Elementary and Intermediate)</span></p>\r\n    </td>\r\n    <td width=\"57\" valign=\"top\" style=\"width:42.55pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">1996\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"406\" valign=\"top\" style=\"width:304.75pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\" style=\"text-align:justify\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">Although\r\n      far from perfect, these are probably the best books in print. They cover a\r\n      wide range of grammar and communicative topics. A vocabulary list and a\r\n      collection of grammar charts are useful supplements. Probably the best\r\n      choice for a course book on the market.\r\n      \r\n      </span></p>\r\n    </td>\r\n  </tr>\r\n  <tr>\r\n    <td width=\"64\" valign=\"top\" style=\"width:47.95pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">$18\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"104\" valign=\"top\" style=\"width:77.95pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">Heim,\r\n      M.\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"227\" valign=\"top\" style=\"width:6.0cm;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">Contemporary\r\n      Czech\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"57\" valign=\"top\" style=\"width:42.55pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">1982\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"406\" valign=\"top\" style=\"width:304.75pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\" style=\"text-align:justify\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">A\r\n      more advanced book presupposing some knowledge of a related Slavic\r\n      language (Russian, Polish), certainly not very good for communicative\r\n      study but could be useful for reference.\r\n      \r\n      </span></p>\r\n    </td>\r\n  </tr>\r\n  <tr>\r\n    <td width=\"64\" valign=\"top\" style=\"width:47.95pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">200\r\n      K</span><span lang=\"CS\" style=\"font-family:&quot;Times New Roman&quot;;mso-ansi-language:\r\n  CS\">&#269;\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"104\" valign=\"top\" style=\"width:77.95pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">Hronová,\r\n      Turzíková \r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"227\" valign=\"top\" style=\"width:6.0cm;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">&#268;etina\r\n      pro cizince\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"57\" valign=\"top\" style=\"width:42.55pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">1989\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"406\" valign=\"top\" style=\"width:304.75pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\" style=\"text-align:justify\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">A\r\n      revised edition of a classic. Very comprehensive but also very\r\n      traditional. Includes many dialogues, pictures, charts, and a lot of\r\n      useful phrases. In the back, it has a small dictionary with equivalents in\r\n      3 languages.\r\n      \r\n      </span></p>\r\n    </td>\r\n  </tr>\r\n  <tr>\r\n    <td width=\"64\" valign=\"top\" style=\"width:47.95pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">80\r\n      K</span><span lang=\"CS\" style=\"font-family:&quot;Times New Roman&quot;;mso-ansi-language:\r\n  CS\">&#269;\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"104\" valign=\"top\" style=\"width:77.95pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">Kami\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"227\" valign=\"top\" style=\"width:6.0cm;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">U</span><span lang=\"CS\" style=\"font-family:&quot;Times New Roman&quot;;mso-ansi-language:CS\">&#269;</span><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">íme\r\n      se &#269;esky I. and II.\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"57\" valign=\"top\" style=\"width:42.55pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">1992\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"406\" valign=\"top\" style=\"width:304.75pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\" style=\"text-align:justify\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">Nicely\r\n      printed textbook in nice covers. Plenty of pictures but also very\r\n      traditionally grammatically oriented. Contains no English.\r\n      \r\n      </span></p>\r\n    </td>\r\n  </tr>\r\n  <tr>\r\n    <td width=\"64\" valign=\"top\" style=\"width:47.95pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">1200\r\n      K</span><span lang=\"CS\" style=\"font-family:&quot;Times New Roman&quot;;mso-ansi-language:\r\n  CS\">&#269;\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"104\" valign=\"top\" style=\"width:77.95pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">Kelly,\r\n      M.\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"227\" valign=\"top\" style=\"width:6.0cm;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">Czech\r\n      For You<i style=\"mso-bidi-font-style:normal\">\r\n      \r\n      </i></span></p>\r\n    </td>\r\n    <td width=\"57\" valign=\"top\" style=\"width:42.55pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">1993\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"406\" valign=\"top\" style=\"width:304.75pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\" style=\"text-align:justify\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">Contains\r\n      many drills and countless flashcards. Otherwise it is very superficial and\r\n      not well outlined. The dialogues are sometimes inappropriate to the\r\n      context, and not very well structured. Its main virtue is the 8 tapes, all\r\n      recorded by professional speakers, giving you enough time to repeat\r\n      everything several times. The book contains several mistakes.\r\n      \r\n      </span></p>\r\n    </td>\r\n  </tr>\r\n  <tr>\r\n    <td width=\"64\" valign=\"top\" style=\"width:47.95pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">530\r\n      K</span><span lang=\"CS\" style=\"font-family:&quot;Times New Roman&quot;;mso-ansi-language:\r\n  CS\">&#269;\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"104\" valign=\"top\" style=\"width:77.95pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">Naughton,\r\n      M\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"227\" valign=\"top\" style=\"width:6.0cm;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">Colloquial\r\n      Czech\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"57\" valign=\"top\" style=\"width:42.55pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">1989\r\n      \r\n      </span></p>\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">1999\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"406\" valign=\"top\" style=\"width:304.75pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\" style=\"text-align:justify\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">Funny\r\n      dialogues, not very well structured and suited to learners needs. More\r\n      of an annotated soap-opera than a textbook. More advanced learners,\r\n      however, might profit from listening to the tape. Some people also like\r\n      the grammatical explanations. Contains very few exercises, and a modest\r\n      dictionary. The language is much less colloquial than the situations.\r\n      \r\n      </span></p>\r\n      <p class=\"TableSmall\" style=\"text-align:justify\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">Tape\r\n      to the book which may be good for learning pronunciation of some less\r\n      common or more complex phrases. It will also give you a chance to listen\r\n      to soap opera like dialogues. The recordings are very professional.\r\n      \r\n      </span></p>\r\n      <p class=\"TableSmall\" style=\"text-align:justify\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">A\r\n      new revised edition should be available soon.\r\n      \r\n      </span></p>\r\n    </td>\r\n  </tr>\r\n  <tr>\r\n    <td width=\"64\" valign=\"top\" style=\"width:47.95pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">200\r\n      </span><span lang=\"CS\" style=\"font-family:&quot;Times New Roman&quot;;mso-ansi-language:\r\n  CS\">K&#269;\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"104\" valign=\"top\" style=\"width:77.95pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">Parolková\r\n      and Nováková\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"227\" valign=\"top\" style=\"width:6.0cm;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">Czech\r\n      For Foreigners<i style=\"mso-bidi-font-style:normal\">\r\n      \r\n      </i></span></p>\r\n    </td>\r\n    <td width=\"57\" valign=\"top\" style=\"width:42.55pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">1993\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"406\" valign=\"top\" style=\"width:304.75pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\" style=\"text-align:justify\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">Contains\r\n      a plenty of pictures and flashcards. It also has some very interesting\r\n      exercises. It is far from comprehensive and generally disliked by students\r\n      using it regularly. It may be a good springboard to better things.\r\n      \r\n      </span></p>\r\n      <p class=\"TableSmall\" style=\"text-align:justify\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">The\r\n      book is accompanied by a fairly good tape. It is the only tape, however,\r\n      that contains comprehension exercises, and dictations. Unfortunately, the\r\n      authors tried to squeeze too much into little space. I would recommend it\r\n      for self study at a more advanced level to increase comprehension.\r\n      \r\n      </span></p>\r\n      <p class=\"TableSmall\" style=\"text-align:justify\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">A\r\n      set of scored tests are available with the book but it doesnt tell you\r\n      what the scores mean. \r\n      \r\n      </span></p>\r\n    </td>\r\n  </tr>\r\n  <tr>\r\n    <td width=\"64\" valign=\"top\" style=\"width:47.95pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">$15\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"104\" valign=\"top\" style=\"width:77.95pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">Short,\r\n      D\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"227\" valign=\"top\" style=\"width:6.0cm;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">Teach\r\n      Yourself Czech\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"57\" valign=\"top\" style=\"width:42.55pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">1993\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"406\" valign=\"top\" style=\"width:304.75pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\" style=\"text-align:justify\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">A\r\n      professionally looking book. It is very well organized if a little too\r\n      traditional. More advanced learners may profit from the dialogues which\r\n      often contain less common phrases. The same fact may obscure the meaning\r\n      of some dialogues to a beginner. The plentiful grammatical explanations\r\n      are very thorough and detail. Also contains useful appendices (index,\r\n      vocabulary list). It contains a lesson on archaic language used in written\r\n      texts of today.\r\n      \r\n      </span></p>\r\n    </td>\r\n  </tr>\r\n</table>\r\n<h3><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">Dictionaries\r\n\r\n</span></h3>\r\n<table border=\"0\" cellspacing=\"0\" cellpadding=\"0\" style=\"border-collapse:collapse;\r\n mso-table-layout-alt:fixed;mso-padding-alt:0cm 5.4pt 0cm 5.4pt\">\r\n  <tr>\r\n    <td width=\"76\" valign=\"top\" style=\"width:2.0cm;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"CS\" style=\"font-family:&quot;Times New Roman&quot;;\r\n  mso-ansi-language:CS\">535 K&#269;</span><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"113\" valign=\"top\" style=\"width:3.0cm;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">J.\r\n      Fronek\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"215\" valign=\"top\" style=\"width:161.1pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"CS\" style=\"font-family:&quot;Times New Roman&quot;;\r\n  mso-ansi-language:CS\">English</span><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">-Czech/Czech-English\r\n      Dictionary</span><span lang=\"CS\" style=\"font-family:&quot;Times New Roman&quot;;\r\n  mso-ansi-language:CS\">\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"50\" valign=\"top\" style=\"width:37.35pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">1998\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"435\" valign=\"top\" style=\"width:326.05pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">Without\r\n      argument the very best dictionary usable for learners on the market.\r\n      Provides useful grammatical information, context and clear layout. A must\r\n      have for a serious learner.\r\n      \r\n      </span></p>\r\n    </td>\r\n  </tr>\r\n  <tr>\r\n    <td width=\"76\" valign=\"top\" style=\"width:2.0cm;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">350\r\n      </span><span lang=\"CS\" style=\"font-family:&quot;Times New Roman&quot;;mso-ansi-language:\r\n  CS\">K&#269;\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"113\" valign=\"top\" style=\"width:3.0cm;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">Filipec\r\n      et al.\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"215\" valign=\"top\" style=\"width:161.1pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"CS\" style=\"font-family:&quot;Times New Roman&quot;;\r\n  mso-ansi-language:CS\">Slovník spisovné &#269;etiny\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"50\" valign=\"top\" style=\"width:37.35pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">1994\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"435\" valign=\"top\" style=\"width:326.05pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">Very\r\n      good reference work. Pretty much the only single-volume Czech-Czech\r\n      dictionary. Gives you all the necessary grammatical information and more.\r\n      Its entries often contain short examples. The downside: Everything is in\r\n      Czech for Czechs. Also available on CD-ROM.\r\n      \r\n      </span></p>\r\n    </td>\r\n  </tr>\r\n  <tr>\r\n    <td width=\"76\" valign=\"top\" style=\"width:2.0cm;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">1200\r\n      </span><span lang=\"CS\" style=\"font-family:&quot;Times New Roman&quot;;mso-ansi-language:\r\n  CS\">K&#269;\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"113\" valign=\"top\" style=\"width:3.0cm;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">Hais,\r\n      Hodek \r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"215\" valign=\"top\" style=\"width:161.1pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"CS\" style=\"font-family:&quot;Times New Roman&quot;;\r\n  mso-ansi-language:CS\">Anglicko - &#269;eský slovník I.-IV.\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"50\" valign=\"top\" style=\"width:37.35pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">1993-94\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"435\" valign=\"top\" style=\"width:326.05pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">The\r\n      largest English-Czech dictionary available. Designed for Czech users with\r\n      no regard to foreign learner. Recently also published in a two-volume\r\n      revised edition. Available on CD-ROM which is a great thing for\r\n      translators but at 10&nbsp;000 K</span><span lang=\"CS\" style=\"font-family:&quot;Times New Roman&quot;;\r\n  mso-ansi-language:CS\">&#269;</span><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">\r\n      pricey for mere mortals.\r\n      \r\n      </span></p>\r\n    </td>\r\n  </tr>\r\n  <tr>\r\n    <td width=\"76\" valign=\"top\" style=\"width:2.0cm;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">80\r\n      </span><span lang=\"CS\" style=\"font-family:&quot;Times New Roman&quot;;mso-ansi-language:\r\n  CS\">K&#269;\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"113\" valign=\"top\" style=\"width:3.0cm;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">Kneovi&#269;\r\n      et al\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"215\" valign=\"top\" style=\"width:161.1pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"CS\" style=\"font-family:&quot;Times New Roman&quot;;\r\n  mso-ansi-language:CS\">Anglicko-&#268;eský/&#268;esko-Anglický Slovník\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"50\" valign=\"top\" style=\"width:37.35pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">1993\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"435\" valign=\"top\" style=\"width:326.05pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">This\r\n      is a dictionary for Czechs, therefore, while being the most comprehensive\r\n      pocket dictionary available it has severe limitations in providing\r\n      necessary grammatical information (gender, aspect). When using it the\r\n      student has about a fifty percent chance of getting the right equivalent,\r\n      and much less of being able to use it correctly. \r\n      \r\n      </span></p>\r\n    </td>\r\n  </tr>\r\n  <tr>\r\n    <td width=\"76\" valign=\"top\" style=\"width:2.0cm;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">$20\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"113\" valign=\"top\" style=\"width:3.0cm;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">Nina\r\n      Trnka\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"215\" valign=\"top\" style=\"width:161.1pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\">Czech-English/English-Czech\r\n      Concise Dictionary</span></p>\r\n    </td>\r\n    <td width=\"50\" valign=\"top\" style=\"width:37.35pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\">&nbsp;<span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">\r\n      \r\n      </span></p>\r\n    </td>\r\n    <td width=\"435\" valign=\"top\" style=\"width:326.05pt;padding:0cm 5.4pt 0cm 5.4pt\">\r\n      <p class=\"TableSmall\"><span lang=\"EN-US\" style=\"font-family:&quot;Times New Roman&quot;\">The\r\n      only dictionary published in the US, designed specifically for non-native\r\n      speakers. It is the only dictionary to give phonetic transcriptions of\r\n      Czech words. Its main limitation is the vocabulary range. While\r\n      potentially useful for complete beginners, it will not be enough for\r\n      serious learners.\r\n      \r\n      </span></p>\r\n    </td>\r\n  </tr>\r\n</table>', '2002-10-12 21:11:37', 1569, 85, 4);
INSERT INTO `xc_articles` (`xca_id`, `xca_name`, `xca_author`, `xca_perex`, `xca_text`, `xca_time`, `xca_readers`, `xca_section`, `xca_priority`) VALUES
(39, 'Internet Resources', 'Dominik Luke', 'What are some of the resources that can be used to learn Czech on the Internet. The <a href=links/index.php>Links</a> section grew out of this modest effort.', '  <h2 style=\"margin-top:0cm\"><a name=\"_Toc442241312\"></a><a name=\"_Toc442241513\"></a><a name=\"_Toc450141134\"><span lang=\"EN-US\" style=\"mso-bookmark: _Toc442241312\">Czech\r\n  Republic on the Internet</span></a></h2>\r\n</div>\r\n<p class=\"NormalFirst\"><span lang=\"EN-US\">Once you master Czech, there is a vast\r\narray of resources available on the internet, many of these sites have English\r\nversions (especially the service oriented ones like time tables) but there is\r\nmuch that is Czech only.</span></p>\r\n<table border=\"0\" cellspacing=\"0\" cellpadding=\"0\" style=\"border-collapse: collapse; mso-table-layout-alt: fixed; mso-padding-alt: 0cm 3.5pt 0cm 3.5pt\" width=\"663\">\r\n  <tr>\r\n    <td width=\"180\" valign=\"top\" style=\"padding-left: 3.5pt; padding-right: 3.5pt; padding-top: 0cm; padding-bottom: 0cm\">\r\n      <p class=\"TableHeading1\"><big><b><a name=\"_Toc442241314\"></a><a name=\"_Toc442241515\"><span lang=\"EN-US\" style=\"mso-bookmark: _Toc442241314\">Search\r\n      Engines</span></a></b></big></p>\r\n    </td>\r\n    <td width=\"150\" valign=\"top\" style=\"padding-left: 3.5pt; padding-right: 3.5pt; padding-top: 0cm; padding-bottom: 0cm\">\r\n      <p class=\"TableNormal\"><span lang=\"EN-US\"><a href=\"http://www.seznam.cz\">www.seznam.cz<br>\r\n      </a><a href=\"http://www.atlas.cz\">www.atlas.cz<br>\r\n      </a><a href=\"http://www.zmije.cz\">www.zmije.cz</a></span></td>\r\n    <td width=\"297\" valign=\"top\" style=\"padding-left: 3.5pt; padding-right: 3.5pt; padding-top: 0cm; padding-bottom: 0cm\">\r\n      <p class=\"TableNormal\"><span lang=\"EN-US\">All these search engines combine\r\n      Yahoo and AltaVista approach. Seznam, the most popular also offers daily\r\n      news.</span></p>\r\n    </td>\r\n  </tr>\r\n  <tr>\r\n    <td width=\"180\" valign=\"top\" style=\"padding-left: 3.5pt; padding-right: 3.5pt; padding-top: 0cm; padding-bottom: 0cm\">\r\n      <p class=\"TableHeading1\"><big><b><a name=\"_Toc442241315\"></a><a name=\"_Toc442241516\"><span lang=\"EN-US\" style=\"mso-bookmark: _Toc442241315\">Useful\r\n      Information</span></a></b></big></p>\r\n    </td>\r\n    <td width=\"150\" valign=\"top\" style=\"padding-left: 3.5pt; padding-right: 3.5pt; padding-top: 0cm; padding-bottom: 0cm\">\r\n      <p class=\"TableNormal\"><span lang=\"EN-US\">\r\n      <a href=\"http://www.czech.cz\">www.czech.cz</a>\r\n      </span></td>\r\n    <td width=\"297\" valign=\"top\" style=\"padding-left: 3.5pt; padding-right: 3.5pt; padding-top: 0cm; padding-bottom: 0cm\">\r\n      <p class=\"TableNormal\"><span lang=\"EN-US\">Czech Ministry of foreign affairs</span></td>\r\n  </tr>\r\n  <tr>\r\n    <td width=\"180\" valign=\"top\" style=\"padding-left: 3.5pt; padding-right: 3.5pt; padding-top: 0cm; padding-bottom: 0cm\">\r\n      <p class=\"MsoNormal\"><big><b>&nbsp;\r\n      \r\n      </b></big></p>\r\n    </td>\r\n    <td width=\"150\" valign=\"top\" style=\"padding-left: 3.5pt; padding-right: 3.5pt; padding-top: 0cm; padding-bottom: 0cm\">\r\n      <p class=\"TableNormal\" style=\"margin-top:0cm\"><span lang=\"EN-US\"><a href=\"http://www.czechinvest.cz\">www.czechinvest.cz</a></span></p>\r\n    </td>\r\n    <td width=\"297\" valign=\"top\" style=\"padding-left: 3.5pt; padding-right: 3.5pt; padding-top: 0cm; padding-bottom: 0cm\">\r\n      <p class=\"TableNormal\" style=\"margin-top:0cm\"><span lang=\"EN-US\">Information\r\n      for investors in the CR.</span></p>\r\n    </td>\r\n  </tr>\r\n  <tr>\r\n    <td width=\"180\" valign=\"top\" style=\"padding-left: 3.5pt; padding-right: 3.5pt; padding-top: 0cm; padding-bottom: 0cm\">\r\n      <p class=\"MsoNormal\"><big><b>&nbsp;\r\n      \r\n      </b></big></p>\r\n    </td>\r\n    <td width=\"150\" valign=\"top\" style=\"padding-lef