INSERT INTO `xc_articles` (`xca_id`, `xca_name`, `xca_author`, `xca_perex`, `xca_text`, `xca_time`, `xca_readers`, `xca_section`, `xca_priority`) VALUES
(97, 'Enoch Powell\'s \"Rivers of Blood\" speech', '', 'These are only excerpts from the speech (about 10%) chosen to illustrate both speech and propaganda. Cut parts are marked by \'...\'. <br>\r\nSee here for the full text of the speech: <A href=\"http://www.sterlingtimes.org/text_rivers_of_blood.htm\">http://www.sterlingtimes.org/text_rivers_of_blood.htm</A>', '<P class=MsoNormal style=\"MARGIN: 0cm 0cm 9pt; TEXT-ALIGN: center\" align=center><STRONG><SPAN lang=EN-GB style=\"FONT-SIZE: 14pt; mso-bidi-font-size: 18.0pt; mso-bidi-font-family: \'Courier New\'\"><FONT face=Arial>Speech given by Enoch Powell in April 1968<?xml:namespace prefix = o ns = \"urn:schemas-microsoft-com:office:office\" /><o:p></o:p></FONT></SPAN></STRONG></P>\r\n<P class=MsoNormal style=\"MARGIN: 0cm 0cm 9pt; TEXT-ALIGN: justify\"><STRONG><SPAN lang=EN-GB style=\"FONT-SIZE: 16pt; FONT-FAMILY: \'Times New Roman\'; mso-bidi-font-size: 18.0pt\">T</SPAN></STRONG><STRONG><SPAN lang=EN-GB style=\"FONT-WEIGHT: normal; FONT-SIZE: 12pt; FONT-FAMILY: \'Times New Roman\'; mso-bidi-font-size: 18.0pt\">he supreme function of statesmanship is to provide against</SPAN></STRONG><SPAN lang=EN-GB style=\"FONT-SIZE: 12pt; FONT-FAMILY: \'Times New Roman\'\"> </SPAN><STRONG><SPAN lang=EN-GB style=\"FONT-WEIGHT: normal; FONT-SIZE: 12pt; FONT-FAMILY: \'Times New Roman\'; mso-bidi-font-size: 18.0pt\">preventable evils. In seeking to do so, it encounters</SPAN></STRONG><SPAN lang=EN-GB style=\"FONT-SIZE: 12pt; FONT-FAMILY: \'Times New Roman\'\"> </SPAN><STRONG><SPAN lang=EN-GB style=\"FONT-WEIGHT: normal; FONT-SIZE: 12pt; FONT-FAMILY: \'Times New Roman\'; mso-bidi-font-size: 18.0pt\">obstacles which are deeply rooted in human nature. <SPAN style=\"mso-spacerun: yes\">&nbsp;</SPAN>INSERT INTO `xc_articles` (`xca_id`, `xca_name`, `xca_author`, `xca_perex`, `xca_text`, `xca_time`, `xca_readers`, `xca_section`, `xca_priority`) VALUES
(102, 'Klobouk ve křoví (1935) LEVEL 1', 'Jiří Voskovec and Jan Werich', 'This poem is also a song. Listen to it <a href=tuit/sound/poetry/kloboukvekrovi.mp3>here</a>.', '<P class=MsoNormal style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=CS style=\"FONT-FAMILY: Arial; mso-bidi-font-family: \'Times New Roman\'; mso-ansi-language: CS\">Vítr vane<SUP>1</SUP> poutí<?xml:namespace prefix = o ns = \"urn:schemas-microsoft-com:office:office\" /><o:p></o:p></SPAN></P>\r\n<P class=MsoNormal style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=CS style=\"FONT-FAMILY: Arial; mso-bidi-font-family: \'Times New Roman\'; mso-ansi-language: CS\">po písku ene<SUP>2</SUP> klobouk<o:p></o:p></SPAN></P>\r\n<P class=MsoNormal style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=CS style=\"FONT-FAMILY: Arial; mso-bidi-font-family: \'Times New Roman\'; mso-ansi-language: CS\">zahnal ho do houtí<o:p></o:p></SPAN></P>\r\n<P class=MsoNormal style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=CS style=\"FONT-FAMILY: Arial; mso-bidi-font-family: \'Times New Roman\'; mso-ansi-language: CS\">starý a černý klobouk<o:p></o:p></SPAN></P>\r\n<P class=MsoNormal style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=CS style=\"FONT-FAMILY: Arial; mso-bidi-font-family: \'Times New Roman\'; mso-ansi-language: CS\"><o:p> </o:p></SPAN></P>\r\n<P class=MsoNormal style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=CS style=\"FONT-FAMILY: Arial; mso-bidi-font-family: \'Times New Roman\'; mso-ansi-language: CS\">Kdepak<SUP>3</SUP> je ta hlava,<o:p></o:p></SPAN></P>\r\n<P class=MsoNormal style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=CS style=\"FONT-FAMILY: Arial; mso-bidi-font-family: \'Times New Roman\'; mso-ansi-language: CS\">která klobouk nosila<o:p></o:p></SPAN></P>\r\n<P class=MsoNormal style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=CS style=\"FONT-FAMILY: Arial; mso-bidi-font-family: \'Times New Roman\'; mso-ansi-language: CS\">Byla černá či plavá?<o:p></o:p></SPAN></P>\r\n<P class=MsoNormal style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=CS style=\"FONT-FAMILY: Arial; mso-bidi-font-family: \'Times New Roman\'; mso-ansi-language: CS\">Komu asi patřila?<o:p></o:p></SPAN></P>\r\n<P class=MsoNormal style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=CS style=\"FONT-FAMILY: Arial; mso-bidi-font-family: \'Times New Roman\'; mso-ansi-language: CS\"><o:p> </o:p></SPAN></P>\r\n<P class=MsoNormal style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=CS style=\"FONT-FAMILY: Arial; mso-bidi-font-family: \'Times New Roman\'; mso-ansi-language: CS\">Kdo to v pouti zmizel?<o:p></o:p></SPAN></P>\r\n<P class=MsoNormal style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=CS style=\"FONT-FAMILY: Arial; mso-bidi-font-family: \'Times New Roman\'; mso-ansi-language: CS\">Odkud el a kam?<o:p></o:p></SPAN></P>\r\n<P class=MsoNormal style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=CS style=\"FONT-FAMILY: Arial; mso-bidi-font-family: \'Times New Roman\'; mso-ansi-language: CS\">Jakou to měl svízel,<o:p></o:p></SPAN></P>\r\n<P class=MsoNormal style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=CS style=\"FONT-FAMILY: Arial; mso-bidi-font-family: \'Times New Roman\'; mso-ansi-language: CS\">e byl v pouti sám?<o:p></o:p></SPAN></P>\r\n<P class=MsoNormal style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=CS style=\"FONT-FAMILY: Arial; mso-bidi-font-family: \'Times New Roman\'; mso-ansi-language: CS\"><o:p> </o:p></SPAN></P>\r\n<P class=MsoNormal style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=CS style=\"FONT-FAMILY: Arial; mso-bidi-font-family: \'Times New Roman\'; mso-ansi-language: CS\">Jen zaváté stopy<o:p></o:p></SPAN></P>\r\n<P class=MsoNormal style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=CS style=\"FONT-FAMILY: Arial; mso-bidi-font-family: \'Times New Roman\'; mso-ansi-language: CS\">starý klobouk ve křoví<o:p></o:p></SPAN></P>\r\n<P class=MsoNormal style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=CS style=\"FONT-FAMILY: Arial; mso-bidi-font-family: \'Times New Roman\'; mso-ansi-language: CS\">nikdo nic nepochopí<o:p></o:p></SPAN></P>\r\n<P class=MsoNormal style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=CS style=\"FONT-FAMILY: Arial; mso-bidi-font-family: \'Times New Roman\'; mso-ansi-language: CS\">nikdo se nic nedoví<SUP>4<o:p></o:p></SUP></SPAN></P>\r\n<P class=MsoNormal style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=PL style=\"FONT-FAMILY: Arial; mso-bidi-font-family: \'Times New Roman\'; mso-ansi-language: PL\"><o:p> </o:p></SPAN></P>\r\n<P class=MsoNormal style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=PL style=\"FONT-FAMILY: Arial; mso-bidi-font-family: \'Times New Roman\'; mso-ansi-language: PL\">1 vát  vane<o:p></o:p></SPAN></P>\r\n<P class=MsoNormal style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=PL style=\"FONT-FAMILY: Arial; mso-bidi-font-family: \'Times New Roman\'; mso-ansi-language: PL\">2 hn</SPAN><SPAN lang=CS style=\"FONT-FAMILY: Arial; mso-bidi-font-family: \'Times New Roman\'; mso-ansi-language: CS\">át  ene<o:p></o:p></SPAN></P>\r\n<P class=MsoNormal style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=CS style=\"FONT-FAMILY: Arial; mso-bidi-font-family: \'Times New Roman\'; mso-ansi-language: CS\">3 kdepak = kde asi<o:p></o:p></SPAN></P>\r\n<P class=MsoNormal style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=CS style=\"FONT-FAMILY: Arial; mso-bidi-font-family: \'Times New Roman\'; mso-ansi-language: CS\">4 dozvědět se  doví se<o:p></o:p></SPAN></P>', '2002-11-25 13:18:03', 1262, 204, 30),
(103, 'Most (Level 1)', 'Leopold Staff (1954)', '', '<P class=MsoNormal style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=PL style=\"FONT-SIZE: 11pt; FONT-FAMILY: Arial; mso-bidi-font-family: \'Times New Roman\'; mso-ansi-language: PL; mso-bidi-font-size: 10.0pt\">Nie wierzyłem<?xml:namespace prefix = o ns = \"urn:schemas-microsoft-com:office:office\" /><o:p></o:p></SPAN></P>\r\n<P class=MsoNormal style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=PL style=\"FONT-SIZE: 11pt; FONT-FAMILY: Arial; mso-bidi-font-family: \'Times New Roman\'; mso-ansi-language: PL; mso-bidi-font-size: 10.0pt\">Stojšc nad brzegiem rzeki,<o:p></o:p></SPAN></P>\r\n<P class=MsoNormal style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=PL style=\"FONT-SIZE: 11pt; FONT-FAMILY: Arial; mso-bidi-font-family: \'Times New Roman\'; mso-ansi-language: PL; mso-bidi-font-size: 10.0pt\">Która była szeroka i rwista,<o:p></o:p></SPAN></P>\r\n<P class=MsoNormal style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=PL style=\"FONT-SIZE: 11pt; FONT-FAMILY: Arial; mso-bidi-font-family: \'Times New Roman\'; mso-ansi-language: PL; mso-bidi-font-size: 10.0pt\">Że przejdę ten most,<o:p></o:p></SPAN></P>\r\n<P class=MsoNormal style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=PL style=\"FONT-SIZE: 11pt; FONT-FAMILY: Arial; mso-bidi-font-family: \'Times New Roman\'; mso-ansi-language: PL; mso-bidi-font-size: 10.0pt\">Spleciony z cienkiej, kruchej trzciny<o:p></o:p></SPAN></P>\r\n<P class=MsoNormal style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=PL style=\"FONT-SIZE: 11pt; FONT-FAMILY: Arial; mso-bidi-font-family: \'Times New Roman\'; mso-ansi-language: PL; mso-bidi-font-size: 10.0pt\">Powišzanej łykiem.<o:p></o:p></SPAN></P>\r\n<P class=MsoNormal style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=PL style=\"FONT-SIZE: 11pt; FONT-FAMILY: Arial; mso-bidi-font-family: \'Times New Roman\'; mso-ansi-language: PL; mso-bidi-font-size: 10.0pt\">Szedłem lekko jak motyl<o:p></o:p></SPAN></P>\r\n<P class=MsoNormal style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=PL style=\"FONT-SIZE: 11pt; FONT-FAMILY: Arial; mso-bidi-font-family: \'Times New Roman\'; mso-ansi-language: PL; mso-bidi-font-size: 10.0pt\">I ciężko jak słoń,<o:p></o:p></SPAN></P>\r\n<P class=MsoNormal style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=PL style=\"FONT-SIZE: 11pt; FONT-FAMILY: Arial; mso-bidi-font-family: \'Times New Roman\'; mso-ansi-language: PL; mso-bidi-font-size: 10.0pt\">Szedłem pewnie jak tancerz<o:p></o:p></SPAN></P>\r\n<P class=MsoNormal style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=PL style=\"FONT-SIZE: 11pt; FONT-FAMILY: Arial; mso-bidi-font-family: \'Times New Roman\'; mso-ansi-language: PL; mso-bidi-font-size: 10.0pt\">I chwiejnie jak lepiec.<o:p></o:p></SPAN></P>\r\n<P class=MsoNormal style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=PL style=\"FONT-SIZE: 11pt; FONT-FAMILY: Arial; mso-bidi-font-family: \'Times New Roman\'; mso-ansi-language: PL; mso-bidi-font-size: 10.0pt\">Nie wierzyłem, że przejdę ten most,<o:p></o:p></SPAN></P>\r\n<P class=MsoNormal style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=PL style=\"FONT-SIZE: 11pt; FONT-FAMILY: Arial; mso-bidi-font-family: \'Times New Roman\'; mso-ansi-language: PL; mso-bidi-font-size: 10.0pt\">I gdy stoję już na drugim brzegu,<o:p></o:p></SPAN></P>\r\n<P class=MsoNormal style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=PL style=\"FONT-SIZE: 11pt; FONT-FAMILY: Arial; mso-bidi-font-family: \'Times New Roman\'; mso-ansi-language: PL; mso-bidi-font-size: 10.0pt\">Nie wierzę, że go przeszedłem.<o:p></o:p></SPAN></P>', '2002-11-25 13:20:20', 2625, 205, 30),
(104, 'paradiso', 'Marta Podgórnik (2000)', '\r\n', '<P class=MsoBodyText2 style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=PL><FONT face=Arial>Zrób co, abym rozebrać się mogła jeszcze bardziej<BR>Ostatni listek wstydu już dawno odrzuciłam</FONT></SPAN></P>\r\n<P class=MsoBodyText2 style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=PL><FONT face=Arial>I najcieńsze wspomnienie sukienki także zmyłam</FONT></SPAN></P>\r\n<P class=MsoBodyText2 style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=PL><FONT face=Arial>I choć kogo nagiego bardziej ode mnie nagiej</FONT></SPAN></P>\r\n<P class=MsoBodyText2 style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=PL><FONT face=Arial>Na pewno mieć nie mogłe, zrób co, bym uwierzyła</FONT></SPAN></P>\r\n<P class=MsoBodyText2 style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=PL><?xml:namespace prefix = o ns = \"urn:schemas-microsoft-com:office:office\" /><o:p><FONT face=Arial>&nbsp;</FONT></o:p></SPAN></P>\r\n<P class=MsoBodyText2 style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=PL><FONT face=Arial>Zrób co, abym otworzyć się mogła jeszcze bardziej</FONT></SPAN></P>\r\n<P class=MsoBodyText2 style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=PL><FONT face=Arial>Już w ostatni por skóry tak dawno mi wniknšłe</FONT></SPAN></P>\r\n<P class=MsoBodyText2 style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=PL><FONT face=Arial>Że nie wierzę, iż kiedy jeszcze nie być tam mogłe</FONT></SPAN></P>\r\n<P class=MsoBodyText2 style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=PL><FONT face=Arial>I choć nie wierzę by mógł być kto bardziej otwarty</FONT></SPAN></P>\r\n<P class=MsoBodyText2 style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=PL><FONT face=Arial>Dla Ciebie niż ja jestem, zrób co, otwórz mnie, rozbierz</FONT></SPAN></P>', '2002-11-25 13:22:08', 4243, 205, 10),
(105, 'Proba', 'Rafał Wojaczek (1972)', '', '<P class=MsoBodyText2 style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=PL><FONT face=Arial>Zrób co, abym rozebrać się mogła jeszcze bardziej<BR>Ostatni listek wstydu już dawno odrzuciłam</FONT></SPAN></P>\r\n<P class=MsoBodyText2 style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=PL><FONT face=Arial>I najcieńsze wspomnienie sukienki także zmyłam</FONT></SPAN></P>\r\n<P class=MsoBodyText2 style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=PL><FONT face=Arial>I choć kogo nagiego bardziej ode mnie nagiej</FONT></SPAN></P>\r\n<P class=MsoBodyText2 style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=PL><FONT face=Arial>Na pewno mieć nie mogłe, zrób co, bym uwierzyła</FONT></SPAN></P>\r\n<P class=MsoBodyText2 style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=PL><?xml:namespace prefix = o ns = \"urn:schemas-microsoft-com:office:office\" /><o:p><FONT face=Arial> </FONT></o:p></SPAN></P>\r\n<P class=MsoBodyText2 style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=PL><FONT face=Arial>Zrób co, abym otworzyć się mogła jeszcze bardziej</FONT></SPAN></P>\r\n<P class=MsoBodyText2 style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=PL><FONT face=Arial>Już w ostatni por skóry tak dawno mi wniknšłe</FONT></SPAN></P>\r\n<P class=MsoBodyText2 style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=PL><FONT face=Arial>Że nie wierzę, iż kiedy jeszcze nie być tam mogłe</FONT></SPAN></P>\r\n<P class=MsoBodyText2 style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=PL><FONT face=Arial>I choć nie wierzę by mógł być kto bardziej otwarty</FONT></SPAN></P>\r\n<P class=MsoBodyText2 style=\"MARGIN: 0cm 0cm 0pt\"><SPAN lang=PL><FONT face=Arial>Dla Ciebie niż ja jestem, zrób co, otwórz mnie, rozbierz</FONT></SPAN></P>', '2002-11-25 13:23:47', 2986, 205, 20),
