(170, '', '', '', '<p class=\"MsoNormal\" style=\"MARGIN: 0cm -72pt 0pt 0cm; TEXT-ALIGN: center\" align=\"center\"><span lang=\"FR\" style=\"FONT-SIZE: 11pt; mso-bidi-font-size: 10.0pt; mso-ansi-language: FR\"><font face=\"Times\">Curriculum Vitae<p></p>\r\n</font>\r\n</span>\r\n</p>\r\n<p></p>\r\n<p></p>\r\n<p></p>\r\n<p></p>\r\n<p class=\"MsoNormal\" style=\"MARGIN: 0cm -72pt 0pt 0cm\"><span lang=\"FR\" style=\"FONT-SIZE: 8pt; mso-bidi-font-size: 10.0pt; mso-ansi-language: FR\"><p><font face=\"Times\"></font>\r\n</p>\r\n</span>\r\n</p>\r\n<p><font face=\"Times\"></font>\r\n</p>\r\n<p></p>\r\n<p><font face=\"Times\"></font>\r\n</p>\r\n<p></p>\r\n<p class=\"MsoNormal\" style=\"MARGIN: 0cm -72pt 0pt 0cm; TEXT-ALIGN: center\" align=\"center\"><font face=\"Times\"><b style=\"mso-bidi-font-weight: normal\"><span lang=\"FR\" style=\"FONT-SIZE: 11pt; mso-bidi-font-size: 10.0pt; mso-ansi-language: FR\">MILUSE SASKOVA-<span style=\"TEXT-TRANSFORM: uppercase\">Pierce</span>\r\n</span>\r\n</b>\r\n<span lang=\"FR\" style=\"FONT-SIZE: 11pt; mso-bidi-font-size: 10.0pt; mso-ansi-language: FR\"><p></p>\r\n</span>\r\n</font>\r\n</p>\r\n<p></p>\r\n<p></p>\r\n<p></p>\r\n<p></p>\r\n<p class=\"MsoNormal\" style=\"MARGIN: 0cm -72pt 0pt 0cm; tab-stops: 288.0pt\"><span lang=\"FR\" style=\"FONT-SIZE: 8pt; mso-bidi-font-size: 10.0pt; mso-ansi-language: FR\"><p><font face=\"Times\"></font>\r\n</p>\r\n</span>\r\n</p>\r\n<p><font face=\"Times\"></font>\r\n</p>\r\n<p></p>\r\n<p><font face=\"Times\"></font>\r\n</p>\r\n<p></p>\r\n<p class=\"MsoNormal\" style=\"MARGIN: 0cm -72pt 0pt 0cm\"><font face=\"Times\"><u><span lang=\"EN-US\" style=\"FONT-SIZE: 11pt; mso-bidi-font-size: 10.0pt\">EDUCATION</span>\r\n</u>\r\n<span lang=\"EN-US\" style=\"FONT-SIZE: 11pt; mso-bidi-font-size: 10.0pt\"><p></p>\r\n</span>\r\n</font>\r\n</p>\r\n<p></p>\r\n<p></p>\r\n<p></p>\r\n<p></p>\r\n<p class=\"MsoNormal\" style=\"MARGIN: 0cm -72pt 0pt 0cm\"><span lang=\"EN-US\" style=\"FONT-SIZE: 8pt; mso-bidi-font-size: 10.0p