(15, '', '\r\n<hr />\r\n<table width=\"100%\" cellspacing=\"0\" cellpadding=\"2\" border=\"0\"><tbody><tr><td width=\"14%\" valign=\"top\" height=\"21\"><b>Name:</b>\r\n</td>\r\n<td width=\"34%\" valign=\"top\" height=\"21\">Markéta Bártová</td>\r\n<td width=\"15%\" valign=\"top\" height=\"21\"><b>Location:</b>\r\n</td>\r\n<td width=\"43%\" valign=\"top\" height=\"21\">Tokyo, Japan</td>\r\n</tr>\r\n<tr><td width=\"14%\" valign=\"top\" height=\"21\"><b>Contact:</b>\r\n</td>\r\n<td width=\"86%\" valign=\"top\" height=\"21\" colspan=\"3\"><p align=\"left\"><a href=\"mailto:marbartova@hotmail.com\">marbartova@hotmail.com</a>\r\n</p>\r\n</td>\r\n</tr>\r\n<tr><td width=\"14%\" valign=\"top\" height=\"21\"><b>Services:</b>\r\n</td>\r\n<td width=\"86%\" valign=\"top\" height=\"21\" colspan=\"3\"><p>Private lessons. </p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<hr />\r\n<table width=\"100%\" cellspacing=\"0\" cellpadding=\"2\" border=\"0\"><tbody><tr><td width=\"14%\" valign=\"top\" height=\"21\"><b>Name:</b>\r\n</td>\r\n<td width=\"34%\" valign=\"top\" height=\"21\"><p>Masae Takenova   </p>\r\n</td>\r\n<td width=\"15%\" valign=\"top\" height=\"21\"><b>Location:</b>\r\n</td>\r\n<td width=\"43%\" valign=\"top\" height=\"21\"><p>Japan, Tokyo</p>\r\n</td>\r\n</tr>\r\n<tr><td width=\"14%\" valign=\"top\" height=\"21\"><b>Contact:</b>\r\n</td>\r\n<td width=\"86%\" valign=\"top\" height=\"21\" colspan=\"3\"><p align=\"left\"><a href=\"mailto:Takenoko@seznam.cz\">Takenoko@seznam.cz</a>\r\n</p>\r\n</td>\r\n</tr>\r\n<tr><td width=\"14%\" valign=\"top\" height=\"21\"><b>Services:</b>\r\n</td>\r\n<td width=\"86%\" valign=\"top\" height=\"21\" colspan=\"3\">I teach Czech by e-mail.</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<hr />\r\n<table width=\"100%\" cellspacing=\"0\" cellpadding=\"2\" border=\"0\"><tbody><tr><td width=\"14%\" valign=\"top\" height=\"21\"><b>Name:</b>\r\n</td>\r\n<td width=\"34%\" valign=\"top\" height=\"21\"><p>Tereza Kim   </p>\r\n</td>\r\n<td width=\"15%\" va